INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R3', 'ru', '“Demolisher” Scythes', 'ceb4fe2a2adf8e8b715d4963897dca00206591315fb9681e66fb5812e5fffedc', '«Разрушитель» Косы', 'Когда этот Адмирал использует качество оружия Сочувственная детонация, каждый жетон, который они сбрасывают, позволяет им преобразовать один Тяжелый успех или Стандартный успех в Взрывной успех.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R76', 'ru', 'Ablative Armour', '1d3bcfb67b4f08a4765c87d85d89efeb338bb80668fee8ab6bc59bd643c63868', 'Абляционная броня', 'Когда эта модель является Первоначальной целью действия Атаки, замените X взрывных успехов в броске действия на тяжелые успехи сразу после броска кубиков, до начала этапа разрешения взрывных успехов. Иногда, это Свойство будет перечислено для определенного сектора, например, Аблятивная броня: Фор (3). В этом случае Свойство применяется только если, как минимум, половина моделей, участвующих в действии Атаки, находятся в перечисленном секторе от целевой модели. *Примечание: Аблятивная броня (X) напрямую противостоит качеству Разрушительному (X), и их значения X компенсируют друг друга. Например, если атака имеет Разрушительное (3) и Первоначальная цель имеет Аблятивную броню (2), Аблятивная броня будет полностью нейтрализована и атака будет разрешена с Разрушительным (1).*');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R312', 'ru', 'Abyssal Terror', 'e7eb3c5fed0e366dc8eca99ba25e4a20c6257dfd8ad58a158b62f5b0c853027c', 'Абиссальный ужас', 'Когда выполняется действие Атака с помощью подводного отряда Империи с статусом Выход на поверхность, этот Адмирал может, в начале шага Подсчет попаданий, выбрать отказ от карты Победа и Доблесть. Если он сделает это, преобразуйте все стандартные счетчики в броске действия в стандартные успехи.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R356', 'ru', 'Acceptable Losses', '79193a6b70605993edfc7bc7620ba2ea2f9b6560021c6fdd5d3454a12ea1b0f6', 'Допустимые потери', 'Когда модель Содружества в этом Формировании получает повреждение, ее Адмирал может объявить это Допустимой потерей, пока в ее отряде остается не менее 2 других боеготовых моделей, не считая Присоединений. Когда модель объявляется Допустимой потерей, противоположный Адмирал не получает никаких Очков Победы за повреждение ее, но каждая модель в ее отряде (включая саму повреждённую модель) получает 1 Беспорядок.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R12', 'ru', 'Additional Incendiaries Injection', '379b9aae72acc4efb2b4af71b83d66870bc7b5047bcc047ca33653fd453c8340', 'Дополнительная инъекция зажигательных веществ', 'Один раз за игру, когда этот Адмирал активирует отряд с признаком Colossus, он может попытаться реализовать Специальный Эффект Мужества. Если успешно, значение Torrent (X) всех орудий в отряде удваивается на время Активации.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R5', 'ru', 'Advanced Protocol Cyclers', '55831d2c8ddb5f09145cebaafdc212e5240d817d154974e3d086045cd99403c2', 'Усовершенствованные протоколы циклов', 'Один раз за Ход, до того как сделать бросок действия для отряда Автоматов из этой Силы, этот Адмирал может выбросить карту Победы и Доблести из своей руки. Если он это сделает, он может заново бросить любые пустые результаты в броске.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R350', 'ru', 'ADVANCED TELEMETROS', 'b10018e8318fbc5d72fe07da7967860315081d8f15281d4e3f3034ecd771e3d9', 'УСОВЕРШЕНСТВОВАННАЯ ТЕЛЕМЕТРИЯ', 'Когда модель в этом Силе совершает Атаку с качеством Руководимый (X), она получает преимущество, если цель находится в пределах 10" от Дружественной модели с системой Ретранслятора гидрофона, даже если она не находится под Угрозой от Дружественного стека СРС.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R95', 'ru', 'Aerial', '99210e8153cbe2151233f0a3a1582edaa3ec6547872b0639aa047cfc9fb71303', 'Воздушное оружие', 'Оружие с этим Специальным качеством атаки является воздушным оружием и может вносить свой вклад в действие атаки только в том случае, если все вносящие вклад оружия также являются воздушными оружием. Первоначальной целью этого действия не может быть подводная модель. Если первоначальной целью является воздушная модель, она не получает преимущества от правила Необычная цель.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R289', 'ru', 'Aerial Reconnaissance', '338549a35fbee1e03e7976aaf44a47dac95c4309003c06c74aaaa83f139ae526', 'Воздушная разведка', 'В шаге Очистки фазы Конец, каждый стек СРС, который все еще находится в игре (т.е. который не решил миссию СРС), выполняет Воздушную разведку. Оба адмирала бросают кубик действия для каждого токена СРС, который у них все еще находится в игре. За каждый взрывающийся успех один эскадрон успешно выполнил миссию Воздушной разведки и предоставит своему адмиралу карту бонуса на шаге Вытягивание карт следующей фазы Готовности. Максимальное количество карт бонуса, которое адмирал может получить от Воздушной разведки, равно его пределу руки. Как напоминание, каждый адмирал может положить токен СРС рядом со своей колодой Победа и Доблесть для каждой карты бонуса, которую он получит. Любые оставшиеся токены СРС затем удаляются из игры.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R185', 'ru', 'Aerial Repair Facilities', '83438496892d30768585fee67dd84a1f9ddad10039e12c5ae0a3f450bd272774', 'Авиационные ремонтные сооружения', 'При броске ремонта для воздушной модели добавьте X бонусных кубиков, если она находится в пределах 4" от хотя бы одной дружественной модели с этой системой.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R47', 'ru', 'Aerial Shield Enhancer', '02b76e14e850209f04ebd93d7aaba99e75cd8d6f19fc478b3c70b7bb73129603', 'Усилитель воздушного щита', 'Если воздушная модель в пределах X" от хотя бы одной дружественной модели с этой системой пользуется щитом тяжелого класса, ее показатель брони получает модификатор +2 вместо +1.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R301', 'ru', 'Aethernauts', 'f34fad7d82fc618635e33ecea23513858cdbce41c96cbb85b7e7b98aa9ec33ab', 'Аэтронавты', 'Если отряд из этого Силы покидает через Портал, его Адмирал может попытаться реализовать Специальный Эффект Мужества в конце Хода Движения. Если эффект отклонен, отряд возвращается в Резерв как обычно. Если он успешно реализован, отряд немедленно Развертывается через другой Портал в Игровой Зоне, как будто он только что прибыл из Резерва.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R156', 'ru', 'Agile', '03ea6b23ef58ff287ff6fe8a3c7ccdcbda895485c4d554d4b35e67a688348d6d', 'Манёвренный', 'Во время своего Хода Движения эта модель может совершить до X Дополнительных маневров.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R235', 'ru', 'Agitation', '098e9027cf169f5211e9e3448eabd2c2a2d3d5faba6f48d34aeffb63c1d43507', 'Агитация', 'Каждый из показателей огневой мощи этого оружия увеличивается на бонус Агитации. Этот бонус равен показателю Массы Первоначальной Цели, до максимального значения X. Показатели огневой мощи «-» не могут быть увеличены таким образом. Однако показатели огневой мощи 0 могут быть увеличены таким образом. *Например, оружие с качеством Агитация (4) имеет показатели огневой мощи 0 / 2 / -. Если Первоначальная Цель имеет Массу 2, ее показатели огневой мощи увеличиваются до 2 / 4 / -. Если Первоначальная Цель имеет Массу 6, ее показатели огневой мощи увеличиваются до 4 / 6 / -.*');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R177', 'ru', 'Air Support Incoming', '005b21ee7873e4008201c0facaf706a305907e6818e4b874eb69673f19660a10', 'Воздушная поддержка приближается', 'Когда делается бросок резерва для воздушного отряда, Адмирал удваивает количество кубиков, которые он бросает. Это означает, что он бросает четыре кубика в 2-м раунде, шесть кубиков в 3-м раунде и так далее.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R214', 'ru', 'Airborne', 'e5fe0b777ceb1bc2b58a8f9e113d647240d56c24928cc82e9d8c67185dfa3be7', 'Воздушный', 'Десантные модели следуют этим дополнительным правилам: Открытое небо, Воздушная поддержка поступает, Необычная цель.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R37', 'ru', 'Alchemical', '87a980615061baf863e1bebc10344417a5ece33e46691ed0fab3ca21716e1150', 'Алхимический', 'После разрешения этого действия Атаки каждое вносящее вклад оружие с этим Качеством накладывает на Первоначальную Цель X токенов Негативного Эффекта. Это токены Горения. Модель с критическим повреждением опасности не может получить токены Горения. Если хотя бы одно вносящее вклад в это действие Атаки оружие также имеет качество Взрыв (X), любые Вторичные Цели, получившие хотя бы 1 Повреждение, также получают токен Горения. Если модель накапливает токены Горения в количестве, равном или превышающем ее Рейтинг Массы, все ее токены Горения удаляются, и она сразу же получает Критический Эффект Повреждения Опасности. При выполнении броска Ремонтного Ролла Адмирал может удалить все токены Горения с модели, как если бы они были единственным Критическим Эффектом Повреждения.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R229', 'ru', 'All Around', '0b0fbc331f31e3741e93855669319f3951b75b5a156494399175bf807da4344a', 'Круговой огонь', 'При объявлении задействованных орудий для действия атаки это орудие можно задействовать независимо от того, в каком секторе обстрела находится основная цель.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R23', 'ru', 'All Hail the Whale!', '37551e7a765d00529fdb00e2c3882af00a5a8de0b67329fd8548f96776f81af8', 'Слава киту!', 'В конце фазы развертывания этот Адмирал получает 6 токенов Конструкта Физетера. Затем они могут распределить эти токены между отрядами в своей Армии, с максимальным количеством 3 токенов на отряд.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R173', 'ru', 'Amphibious', '97484867f8fffac8504953ee75e7e86abd43db20c7164a7329db3336dec86a7a', 'Амфибия', 'Если подводная модель имеет это свойство, оно применяется только тогда, когда она выходит на поверхность. Эта модель может перемещаться в или через опасности для посадки и острова без столкновения с ними и может по-прежнему восстанавливать порядок, когда она находится в пределах досягаемости их. Если эта модель заканчивает свое перемещение так, что она полностью находится на острове, она пересекает этот остров. Погруженные орудия больше не могут вносить свой вклад в атаки против нее, и если она участвует в атаке, ее собственные погруженные орудия не могут вносить свой вклад. Для определения видимости ее рейтинг Массы увеличивается на рейтинг Массы острова. Кроме того, она не получает никакого ущерба в результате критического ущерба от прорыва на этапе консолидации. Пока модель пересекает территорию, противостоящий адмирал не может распределять токены десантной партии по этой территории (см. свойство Нападение на сушу (X)), и любые токены десантной партии, уже распределенные по ней, немедленно удаляются из игры.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R279', 'ru', 'Aquatic', '62e71c53efda1704e39ad814955869cdf95e6ada25a0be732981779b425e18b3', 'Водный', 'Подводный отряд может совершить действие Атака, если все вносящие вклад орудия обладают этим качеством, и Первоначальная цель также является подводной моделью.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R288', 'ru', 'Arc', 'b11a7a46735f12cc5ee4dc3fa93e452a01398109870840c8ab00039bc5c2b20a', 'Дуга', 'До того, как сделать бросок действия для действия Атака, активный Адмирал бросает X кубиков критического урона для каждого орудия с этим качеством. Если любой кубик показывает Системную неисправность, Первоначальная цель сразу же получает один эффект критического урона Системная неисправность. Если Первоначальная цель уже получила Системную неисправность на этом этапе действия, это качество не имеет эффекта.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R290', 'ru', 'Arc Generator', '18fd2e6c975bf1aff8b669b5ee6954eae23a25ff197befcd082704cfbb2df7b3', 'Генератор дуги', 'Это Генератор и предоставляет следующую выгоду отряда: когда этот отряд совершает действие Атаки, его Адмирал может объявить, что они перезаряжают свои орудия. В течение действия все вносящие вклад орудия с качеством Дуга (X) получают качество Разрушительный (1), или увеличивают значение X своего качества Разрушительный на 1. Они также увеличивают значение X качества Дуга на 1. После того, как действие было разрешено, активный Адмирал выбирает одну модель в отряде с Генератором дуги. Эта модель получает 1 Беспорядок. Если она уже имеет 3 уровня Беспорядка, она получает 1 Урон вместо этого. Если выгода отряда была предоставлена моделью из другого отряда - например, моделью с системой Генератор корабля - эта модель получает Беспорядок вместо этого.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R15', 'ru', 'Armed Survey Detachment', '948f9e49457abc19d900e7b8bcd34130bf11320ff28434b0d9fc8df134e9cf5e', 'Вооруженная разведывательная группа', 'В начале своего хода на этапе особого развертывания в фазе развертывания этот Адмирал может выбрать один из своих отрядов в игровой зоне, который не является Неподвижным. Этот отряд получает свойство Авангард (5”). Адмирал может использовать эту Доктрину только один раз.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R121', 'ru', 'Armoured Stern', '39e42f2238527dd4b7844bf4c3bcf91f06912edb7a9ce4d3fa267ec016628b47', 'Бронированная Корма', 'Когда на эту модель совершается атака, правило Уязвимая Корма не применяется.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R112', 'ru', 'Assault', 'ce2120fbcdf26c937f11aa7f05a3ef53173be512b26eb97cf435ea2f01b0583f', 'Штурмовое оружие', 'Оружие с этим особым качеством атаки являются штурмовыми орудиями и могут вносить свой вклад в действие атаки только в том случае, если все вносящие вклад оружия также являются штурмовыми орудиями. Модель может участвовать в этом действии только в том случае, если первоначальная цель находится на расстоянии 2" от нее. Первоначальной целью этого действия не может быть воздушная или подводная модель, если отряд, совершающий это действие, не имеет того же позиционного признака.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R260', 'ru', 'Atomic Generator', '9688e516309fb2ad4c6c141e15adc3c24aa2ea0fcca5376f49f6bc5eecbb86ea', 'Атомный Генератор', 'Это Генератор и предоставляет следующую Преимущество Отряду: Когда вы перемещаете модель в этом отряде, Адмирал может объявить Атомный Прилив. На протяжении всего перемещения модели она получает модификатор +3” к своей Максимальной Скорости и свойство Ловкость (1). В конце своего перемещения модель получает уровень Беспорядка. Атомный Генератор не предоставляет Преимущества Отряду Неподвижным моделям.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R242', 'ru', 'Attachment', '1ae8f4aac1fff58ad1a00a8f45cba380ed65030f9c8ce20eff82760903d0d894', 'Присоединение', 'Во время выбора сил адмирал может выбрать развертывание этого отряда либо самостоятельно, как обычно, либо в качестве Присоединения к Родительскому отряду, как описано в разделе Присоединенные отряды на странице 128 справочника Dystopian Wars. Родительский отряд должен иметь указанный Класс или Черту и должен быть выбран из того же ORBAT, что и Присоединение. Полные правила использования Присоединений в игре можно найти на странице 101 справочника Dystopian Wars.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R201', 'ru', 'Attack Run Mission', 'e6a57b9fbe253280dd4aa329546e0f1ad1a5859677f77008088e3564aed42f3e', 'Миссия воздушного удара', '**РЕШЕНИЕ МИССИИ ВОЗДУШНОГО УДARA** Стек SRS, который угрожает вражескому отряду, выполняет миссию воздушного удара, используя следующий процесс. 1. НАЗНАЧЕНИЕ ЦЕЛЕЙ ВОЗДУШНОГО УДARA Активный адмирал назначает модели в вражеском отряде в качестве целей воздушного удара. Максимальное количество целей воздушного удара, которое он может назначить, равно количеству токенов SRS в его стеке. 2. БРОСОК ДЕЙСТВИЯ Активный адмирал совершает один бросок действия, независимо от количества целей воздушного удара, и противостоящий адмирал совершает один бросок сопротивления: Бассейн действий. Каждый токен SRS в стеке добавляет количество кубиков действий, равное его рейтингу атаки. Бассейн сопротивления. Каждая цель воздушного удара добавляет количество кубиков, равное ее рейтингу защиты. Добавьте 1 бонусный кубик за каждый токен эскорта, сопровождающий целевой отряд. Порог успеха. Самый высокий рейтинг брони среди целей. 3. РАСПРЕДЕЛЕНИЕ КРИТИЧЕСКОГО УЩЕРБА За каждый успех, набранный в броске действия, активный адмирал бросает кубик критического ущерба. Затем он распределяет каждый кубик критического ущерба по цели воздушного удара или токену эскорта, сопровождающему целевой отряд. Только один кубик можно распределить по каждой цели воздушного удара. 4. РЕШЕНИЕ КРИТИЧЕСКОГО УЩЕРБА Каждая цель воздушного удара, которой назначен кубик, получает соответствующий эффект критического ущерба. Каждый токен эскорта, которому назначен кубик, удаляется. 5. ОТКАЗ ОТ БОЯ Удалите все токены SRS (дружественные или вражеские), выделенные целевому отряду. **ПЕРЕХВАТ ВОЗДУШНОГО УДARA** Если адмирал решает миссию воздушного удара против вражеского отряда, поддерживаемого стеком SRS, противостоящий адмирал совершает попытку перехвата. Это решается до того, как активный адмирал назначит цели воздушного удара. Противостоящий адмирал совершает бросок действия. Нет броска сопротивления. Бассейн действий. Каждый токен SRS в поддерживающем стеке добавляет количество кубиков действий, равное его рейтингу перехвата. Порог успеха. Рейтинг выносливости стека. За каждый успех, набранный в броске действия, один токен SRS удаляется из стека SRS, совершающего воздушный удар. Если это приводит к удалению последнего токена в стеке, миссия воздушного удара заканчивается. **ПЕРЕХВАТ СМЕШАННЫХ СТЕКОВ** Если попытка перехвата решается против стека SRS, состоящего из двух или более разных типов токенов SRS, этап разрешения результатов броска действия выполняется немного иначе, чем обычно. Сначала активный адмирал выбирает один тип эскадрильи из своего стека. Противостоящий адмирал группирует попадания по рейтингу выносливости этого типа эскадрильи. Таким образом, активный адмирал может попытаться прикрыть эскадрилью с высоким рейтингом атаки эскадрильей с высоким рейтингом выносливости. За каждый успех один токен выбранного типа удаляется. Если после удаления всех токенов этого типа эскадрильи в броске действия остаются попадания, активный адмирал выбирает другой тип эскадрильи из стека. Процесс повторяется с использованием рейтинга выносливости этого типа эскадрильи, пока либо не останутся попадания в броске действия, набирающие успехи, либо не останутся токены SRS в стеке.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R54', 'ru', 'Automata Repair Bay', 'e8d045013da4f70e46f13f2944469ac468c174ee09d063c36090bfda8733b7d5', 'Ремонтная База Автоматов', 'Если модель Боеготового Автомата завершает свой Ход Движения в пределах 10" от хотя бы одной дружественной модели с этой Системой, она восстанавливает 1 Повреждение.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R68', 'ru', 'Autonomous Explosive', '5574adf7f8afca64a29d85d52311133bf7c6de1794624a085f4a248df793b2f6', 'Автономный взрывчатый', 'Эта модель является Автономным взрывчатым. Вражеские модели поверхности и воздушного базирования не могут проходить через Автономный взрывчатый. Когда Автономный взрывчатый и вражеская модель вступают в контакт, каждая модель в пределах 2" от этой модели, которая разделяет позиционный признак с вражеской моделью, сразу же получает 1 уровень Беспорядка. Вражеская модель сама подвергается взрыву Бангпэ. Чтобы разрешить взрыв Бангпэ, бросьте X игральных костей действия. Модель получает 1 повреждение за каждый стандартный Успех, и 2 повреждения за каждый тяжелый Успех или взрывной Успех. Если вражеская модель двигалась и не была уничтожена, она затем продолжает свое движение. Если модель вступает в контакт с несколькими Автономными взрывчатыми одновременно, каждый взрывчатый substance взрывается, как описано выше. После разрешения взрыва Бангпэ эта модель сразу же уничтожается. *Примечание: Модели, находящиеся в интерфазе (см. Генератор интерфазы), могут проходить через Автономные взрывчатые без запуска взрыва Бангпэ.*');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R243', 'ru', 'Auxiliary Mine Layer', '927f3ea6b768cfde512b0be807e182be4625df6f7ba8bcca19287cda95206bdb', 'Вспомогательный минный заградитель', 'Как Специальное Действие Развертывания, отряд этой модели может Распределять Мины. Когда он это делает, Адмирал отряда размещает до X маркеров минных полей в любом месте Игровой Зоны. Каждый из них должен быть размещен на расстоянии не менее 10" от зоны развертывания противника и не может быть размещен в пределах 1" от модели, особенности местности или другого маркера.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R331', 'ru', 'AWACS', '62adfe1a291cfcc4df44a0d62057ee31acf7324f43d026d5fa6347eecb8323a4', 'ДРЛО', 'Эта доктрина может быть приобретена только для флагманского отряда Союза. Когда отряд Союза из этой Силы совершает действие Атаки, в котором Первоначальная Цель находится в пределах 10" от ротора Akron Sentry, его адмирал может попытаться ввести Специальный эффект Мужества с этим отрядом. Если успешно, все вносящие вклад орудия с качествами Бомбардировка или Торпеда получают качества Высокая Скорость (1) и Руководство (1). Если нет вносящих вклад орудий с этими качествами, то этот Специальный эффект Мужества не может быть использован.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R111', 'ru', 'Azhdaya Berserkers', '5c49143d376a301485368e66ab75d55ed71f4240cd178925ad2fbbb3fa36ed22', 'Берсеркеры Азхдайи', 'Если хотя бы одна модель с этим свойством участвует в действии Абordaж, и бросок действия набирает хотя бы один успех, цель получает дополнительный случайный эффект критического урона после того, как действие Абordaж будет разрешено.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R246', 'ru', 'Barrage', '03bc38fd425575fe1f5d26faf803c1c15be4be7a2ef15007c9396faddcbd72db', 'Заградительный огонь', 'Если хотя бы одно оружие, вносящее вклад в действие Атаки, имеет это качество, рейтинг Массы Цели считается на один пункт ниже при разрешении правила Под огнём. Кроме того, если все оружия, вносящие вклад в действие Атаки, имеют это качество и Цель является Воздушной моделью, только Стандартные успехи в броске сопротивления преобразуются в Стандартные контрмеры правилом Необычная цель.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R25', 'ru', 'Blast', 'ea3373272a49e049f019631297c11947ecb6d883da51730c567a57e8a73bbcea', 'Взрыв', 'После выбора модели в качестве Первоначальной Цели, активный Адмирал выбирает точку на модели. Каждая другая модель (друг или враг), находящаяся на расстоянии 3" от этой точки и обладающая общим Позиционным Признаком с Первоначальной Целью, является Второстепенной Целью. После разрешения этого действия Атака активный Адмирал совершает отдельный бросок действия для каждой Второстепенной Цели. Бросок сопротивления не производится. Бросок действия: X Боевых Кубиков для каждого оружия с этим Качеством. Порог успеха: Класс Брони Второстепенной Цели. За каждый Успех, набранный в броске действия, Второстепенная Цель получает 1 Урон. *Обратите внимание, что любые Свойства или Качества оружия, применяемые к Первоначальной Цели, не применяются к Второстепенным Целям.*');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R194', 'ru', 'Blow The Tanks', '7c2d9c6ad998cdceb591aadd0c7ab91b89c6a6c90977830c2d696631c53bf6c0', 'Взрыв танков', 'Если модель в подводном отряде получает 1 или более уровней беспорядка в результате действия вражеского отряда, его адмирал должен сделать Проверку экипажа группы для отряда, как только завершается активация вражеского отряда. Если проверка не пройдена, отряд сразу же выходит на поверхность. *Обратите внимание, что проводится только одна проверка, даже если несколько моделей в отряде получили беспорядок во время активации.*');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R154', 'ru', 'Boarding', '916f0b20c4e782cb649b25f061ea82c8b222e1b45933e645db140a1a283b0289', 'Абордаж', '**РЕШЕНИЕ ДЕЙСТВИЯ АБОРДАЖА** Действия абордажа представляют собой смелые рейды на вражеские суда, чтобы нанести удар по жизненно важным слабым точкам. Отряд может совершить действие абордажа только если у него есть Свойство, которое специально позволяет ему это сделать. Когда отряд совершает действие абордажа, используйте следующий процесс: 1. **ВЫБЕРИТЕ ЦЕЛЬ** Адмирал выбирает вражескую модель, которая будет Целью. Эта модель должна находиться на расстоянии 4" или меньше от хотя бы одной модели в активном отряде. Большинство Свойств, которые позволяют отряду запустить действие абордажа, позволяют ему нацеливаться только на вражеские модели с определенными Позиционными Чертами. 2. **НАЗНАЧЬТЕ УЧАСТВУЮЩИЕ МОДЕЛИ** Адмирал назначает любое количество моделей в активном отряде, которые будут участвовать в действии. Модель не может участвовать, если она находится дальше 4" от Цели или если она уже участвовала в действии абордажа во время этого Хода Действия. 3. **СОДЕРЖИТЕ БРОСОК ДЕЙСТВИЯ** Активный Адмирал совершает бросок действия, а противоположный Адмирал совершает бросок сопротивления: **Пул Действий** Каждая участвующая модель добавляет определенное количество Дайсов Действия, как определено Свойством, которое позволяет совершать действия абордажа. **Пул Сопротивления** Пул Сопротивления начинается с количества дайсов, равного рейтингу Защиты Цели. Добавьте 1 дайс за каждый токен Эскорта, сопровождающий отряд Цели. Если есть Стек СРС, поддерживающий отряд Цели, противоположный Адмирал может выбросить любое количество токенов из Стека. Каждый выброшенный токен добавляет количество дайсов, равное рейтингу Поддержки Стека. **Порог Успеха** Рейтинг Экипажа Цели. 4. **РЕШИТЕ ИТОГИ** Цель получает Эффект Критического Урона для каждого Успеха, набранного в броске действия. Однако вместо того, чтобы бросать дайсы Критического Урона, активный Адмирал может выбрать конкретные Эффекты, которые применяются, представляя крайне целевой характер таких действий. Кроме того, если бросок действия набирает хотя бы один Успех (либо потому, что активный Адмирал бросил хотя бы один Успех, либо потому, что все Попадания в Пуле Действий были нейтрализованы броском сопротивления), цель получает 1 уровень Беспорядка.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R181', 'ru', 'Boarding Parties', '52594a0bb5de2678deb68a17adfe215828ab9e2fc0873babc0bbcbc6953fba33', 'Абордажная команда', 'Отряд этой модели может выполнять абордажные действия. Целью должна быть надводная модель, если иное не установлено другим правилом. Если правило разрешает отряду начать абордаж против воздушной или подводной модели, эта модель может участвовать только при наличии правила, которое разрешает ей это делать. Если эта модель участвует в абордаже, она добавляет X кубиков к броску действия. Если эта модель является целью абордажа, её Адмирал добавляет X кубиков к броску сопротивления.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R205', 'ru', 'Bomb', '1e950fa0153de9e6453812c7c7b2b19c8add2f21f620a60ea3d1641bbb14b832', 'Бомба', 'Оружие с этим Специальным качеством атаки являются бомбовые орудия и могут вносить свой вклад в действие атаки только в том случае, если все вносящие вклад орудия также являются бомбовыми орудиями. Первоначальной целью этого действия не может быть воздушная модель. Это нападение никогда не пользуется правилом Уязвимый корм. Однако бросок сопротивления для этого нападения не может получить бонусные кубики от осложненной видимости или токенов эскорта. Кроме того, если бомбовое орудие установлено на модели, чья центральная точка прошла через первоначальную цель во время шага движения этой активации, каждая из его показателей огневой мощи удваивается. См. Бомбовые орудия на странице 91 книги правил Dystopian Wars.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R138', 'ru', 'Boosted Propulsion', '6873e823ff07dac2450c0b02506001a154810b78b86a278feeca4264dd836998', 'Усиленная тяга', 'До перемещения этой модели ее Адмирал может объявить, что он будет Усилить ее Пропульсию. Если он сделает это, то в течение текущего Хода Движения минимальная скорость модели увеличивается до ее не модифицированной максимальной скорости, ее максимальная скорость на X", а ее Ограничение Поворота уменьшается до 0.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R30', 'ru', 'Breach', 'a6e4b71376a6e4e2c53484e57a10228df2502de461c47614f74f778754465e31', 'Пробоина', 'Если первичная цель этого действия атаки получает хотя бы 1 урон, активный адмирал бросает X критических кубиков урона для каждого орудия с этим качеством. Если один или несколько кубиков показывают результат Прорыва, первичная цель получает один критический эффект урона этого типа. Это качество критического урона. Если к атаке применяются несколько разных качеств критического урона, адмирал делает отдельный бросок для каждого из них.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R118', 'ru', 'Breaching Drill', 'c6702856dfb254bd8dc0c53c513590b537dae21a386885740ac466d8e56568e8', 'Прорыв боевого порядка', 'Эта модель автоматически проходит проверку экипажа при разрешении тарана. Кроме того, шаги броска действия и нанесения урона разрешаются иначе, чем стандартные правила тарана. 3. БРОСОК ДЕЙСТВИЯ Активный адмирал делает бросок действия. Бросок сопротивления не производится. Бассейн действий Бассейн действий начинается с X кубиков. Добавьте 1 бонусный кубик за каждый полный дюйм, на который модель переместилась до тарана. Это не может добавить более 5 бонусных кубиков. Порог успеха Рейтинг брони целевой модели. (Игнорируется модификатор +1, предоставленный генератором тяжелого щита.) 4. НАНЕСЕНИЕ УРОНА За каждый успех, набранный в броске действия, цель получает 1 урон. Затем активный адмирал бросает определенное количество кубиков критического урона, равное количеству нанесенного урона. За каждый кубик, показывающий результат пробоя, цель получает один экземпляр этого критического эффекта урона.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R180', 'ru', 'Broadside', 'e994edae93e9ab2e6969c213635257996be14b14ba1bbc40cd83490c80a048f0', 'Бортовой залп', '**РАЗРЕШЕНИЕ ДЕЙСТВИЯ БОРТОВОГО ЗАЛПА** Действия бортового залпа позволяют отрядам использовать свои батареи ближнего боя на флангах с разрушительным эффектом. Отряд может совершить только одно действие Бортового залпа за активацию. Когда отряд совершает действие Бортового залпа, используйте следующий процесс: 1. НАЗНАЧЕНИЕ УЧАСТВУЮЩИХ МОДЕЛЕЙ Адмирал назначает любое количество моделей в активном отряде, которые будут участвовать в действии. 2. ВЫБОР ЦЕЛИ Адмирал выбирает вражескую модель, которая станет Целью Бортового залпа. 3. ОПРЕДЕЛЕНИЕ ВКЛАДЫВАЮЩИХСЯ БАТАРЕЙ Адмирал определяет, какие батареи моделей вносят вклад в действие. Батареи модели вносят вклад в действие, если модель участвует в действии, и все следующие условия выполнены: • Цель имеет тот же позиционный признак, что и модель. • Цель находится в портовом или правом секторе модели. • Цель находится на расстоянии 4" от модели. • Цель видна модели и не заслонена. Если ни одна из батарей моделей не вносит вклад в действие, адмирал должен либо выбрать другую цель, либо завершить действие. 4. БРОСАЕМ ДЛЯ БОРТОВОГО ЗАЛПА Адмирал бросает количество игральных костей действия, равное общему рейтингу Бортового залпа всех моделей, батареи которых вносят вклад в действие. Цель получает 1 урон за каждый стандартный успех и 2 урона за каждый тяжелый успех и взрывной успех. (Обратите внимание, что это не бросок действия, поэтому взрывные успехи не позволяют бросать дополнительные кубики.) Кроме того, если цель получает хотя бы 1 урон, она также получает 1 уровень беспорядка. 5. РАЗРЕШЕНИЕ ДОПОЛНИТЕЛЬНЫХ ЦЕЛЕЙ Адмирал повторяет этапы 2-4 столько раз, сколько он желает. Каждая вражеская модель может быть выбрана в качестве цели только один раз за действие Бортового залпа.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R52', 'ru', 'Broadside Cascade', 'b0afcc71195ec2d16d5b5886593880adb4809c396f6dd9a3ed2c38941bfbb2a6', 'Каскад бортового залпа', 'Когда эта модель участвует в бортовом залпе, ее бортовые батареи могут внести свой вклад, если целью является модель Surface или Airborne, даже если эта модель имеет другой позиционный признак. Любые другие ограничения по-прежнему применяются.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R228', 'ru', 'Bulnabang Tii-Pak', '189fcef44b9024f77e75819db45d4d077dba3b99b93f20e449aff7cb5c7e5872', 'Бульнабанг Тии-Пак', 'Когда отряд этой модели совершает действие Абордаж, целью может быть воздушная модель, и эта модель может участвовать в действии. Кроме того, когда эта модель участвует в действии Абордаж, до броска действия нанесите 1 уровень Беспорядка цели.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R239', 'ru', 'Bushi Ryu Dojos', 'fe59bd42f874bd698652fcd3233d4cffc0e7ce4fd066337ae684be12e13d8635', 'Додзё Буси Рю', 'Когда отряд этой модели совершает действие Абордаж, Целью может быть модель класса Surface или Airborne, и эта модель может Принимать участие. Если хотя бы одна модель с этим свойством Принимает участие в действии Абордаж, рейтинг экипажа Цели имеет модификатор -1 за каждый эффект критического урона от опасности, который она имеет (до минимума 1), при определении Успехов на этапе разрешения исходов броска действия.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R339', 'ru', 'BUSHIDO', 'f5cce79a73e5f72127ece529e893495eb74444589485cfeae7055eb5bd298734', 'БУСИДО', 'Эта доктрина может быть приобретена только для японского флагманского отряда. Однажды за бой, после того как этот адмирал попытался реализовать эффект Храбрости, и противостоящий адмирал показал карту Запрета, этот адмирал может объявить Бусидо. Если он это сделает, он должен выбросить еще одну карту Победы и Храбрости из своей руки. Как только он это сделает, карта Запрета игнорируется, а эффект Храбрости реализуется успешно.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R22', 'ru', 'Calculated Extrapolation', '9f5fa0ad293fe613d0911130997eb458aff6583102d991cd1b72f1352fc59106', 'Расчетное экстраполирование', 'Каждый ход, во время фазы вытягивания карт в фазе готовности, этот адмирал получает одну бонусную карту (см. страницу 62 книги правил Dystopian Wars).');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R24', 'ru', 'Calculated Reinforcement Sub-Unit', '2f51312babbd5e227604c1ddbae357b115d1988be68d0304f25193d9e98f1259', 'Расчетный резервный подотряд', 'Каждый раз, когда этот Адмирал совершает бросок резерва для отряда в их Силе, он может бросить один дополнительный Бросок действия.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R278', 'ru', 'Callimachus Chrono-Lathe', '56ffd636521fe3f9db07e35a7a51a5617e6efec8ccc543de4801f2e4b2c4304d', 'Хронолатте Каллимаха', 'Один раз за Раунд, во время шага Развертывания Резервов фазы Готовности, контролирующий Адмирал может использовать эту Систему вместо того, чтобы сделать Бросок Резерва, при условии, что эта модель находится в Игровой Зоне. Другой отряд прибывает сразу, и развертывается так, чтобы каждая модель была в пределах 3" от дружественной модели с этой Системой. Каждая модель в недавно развернутом отряде сразу же подвергается одному случаю Критического Повреждения от Опасности, но отряд не помечается статусом Прибытия. Кроме того, как Специальное Действие, отряд этой модели может Применить Временную Реконфигурацию. Только модели с этой Системой могут Принимать участие. Адмирал отряда добавляет Бросок Действия в Местный Пул Аномалий, затем совершает Бросок Аномалии для отряда. (См. раздел Экспериментальных Устройств в ORBAT Просвещенных.) За каждый пустой результат, каждый Принимающий участие модель получает 1 уровень Беспорядка. Если Принимающая участие модель уже имеет 3 Беспорядка, она получает 1 Повреждение вместо этого. Затем каждый дружественный Боеготовый Просвещенный модель в пределах 15" от хотя бы одной Принимающей участие модели сразу же восстанавливает 1 Повреждение. *~ Обратите внимание, что Принимающая участие модель не считается находящейся в пределах 15" от самой себя, но может восстановить Повреждение, если она находится в пределах 15" от другой Принимающей участие модели.*');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R131', 'ru', 'Carrier', 'd6eb122913b250ca1766a09783bdae0a2e95b31a14893bbce20fee37beeb3296', 'Авианосец', 'В фазе запуска этот отряд модели может разрешить запуск SRS. Когда он это делает, эта модель запускает до X токенов SRS, как описано в разделе Запуск короткодиапазонных эскадрилий на странице 108 книги правил Dystopian Wars. Значение X этого свойства уменьшается на 1 за каждый уровень беспорядка на модели. Тип(ы) токенов SRS, которые может запустить эта модель, определяется другими свойствами в профиле отряда, чаще всего свойством SRS: Тип(ы). Если модель может запустить более одного типа токенов SRS, то они могут быть запущены в любой комбинации, пока общее количество запущенных токенов не превышает X. Если подводная модель имеет этот трейт, она не может разрешить запуск SRS, если она не выходит на поверхность.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R314', 'ru', 'Castles in the Sky', '664efa6d5128f89837a11c009d8f1ee60237627e606c7b2ad682e5dec5daf41d', 'Замки в небе', 'Все модели поддержки Империи класса Skyfortress в этом отряде получают свойство Cloud Dive до конца первого хода.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R50', 'ru', 'Celerity', '8b2815d034ed5354c6edd45f72ca3c4756134869745e1b0e55623df0bf8ac91b', 'Скорость', 'После того, как эта Атака была разрешена, активный Адмирал может попытаться реализовать Специальный Эффект Мужества с активным отрядом. Если эффект реализован успешно, этот отряд может сразу же сделать Атаку Следования. Сначала каждая модель в этом отряде, которая имеет оружие с этим Качеством, может сразу же развернуться и переместиться на 4" прямо вперед. Затем этот отряд совершает еще одно действие Атаки, которое не учитывается в его лимите действий. Только оружие с этим качеством может внести свой вклад в это действие. Отряд может совершить только одну Атаку Следования за Активацию.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R320', 'ru', 'CHAIN OF COMMAND', 'a9ddd4334a223f2506e1b689eaa29cd4a52c684f777fa3a58c579afcb88d417c', 'ЦЕПОЧКА КОМАНДОВАНИЯ', 'Один раз за Раунд, во время шага разрешения повторных бросков броска действия, который этот Адмирал совершает для отряда в своей армии, он может реализовать Специальный Эффект Мужества с этим отрядом. Отряд должен быть либо Флагманом, либо находиться в пределах 10" от дружественного Флагмана. Если Эффект реализуется успешно, Адмирал может перебросить любое количество кубиков в пуле.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R64', 'ru', 'Chang’an Tower Generator', 'a25c4e43f4e10c38934492217ce08d33d90da603e7a6f0bcfab79f92767fc4b7', 'Генератор башни Чанъань', 'Это Генератор и дает следующую выгоду отряда: если любая модель в этом отряде, или модель в другом дружественном отряде в радиусе 5", является целью действия Атаки, вы можете преобразовать до 2 взрывных успехов в тяжелые успехи в начале этапа разрешения взрывных успехов. Действия Атаки, сделанные с помощью оружия типа Штурм, Бомба или Погружение, игнорируют этот эффект.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R298', 'ru', 'Chita-Strike', '09baab23afb39c1345eb8a546f9bcf95cdb1f38972cebe1aa99eba97fae96e86', 'Удар Чита', 'Когда японский отряд в этом Флоте объявляет действие Атака, в котором все вносящие вклад орудия имеют качества Подводный и Торпедный, этот Адмирал может объявить, что они выполняют Удар Чита. Если они сделают это, они могут выбросить любое количество токенов Эскорта из атакующего отряда. За каждый выброшенный токен добавьте 3 Броска Действия в Пул Действий. Кроме того, за каждый выброшенный токен добавьте качество Проникновение (1) к одному вносящему вклад оружию.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R120', 'ru', 'Chrono Generator', '2589538db36dd5bc2aa5e9e39e10bb5df86cffb151d3d933e811d1b31cbaf855', 'Хроногенератор', 'Это Генератор и дает следующую выгоду отряда: когда этот отряд активируется, его адмирал может выбрать, использовать ли Хроногенератор или нет. Если он это делает, он добавляет один бросок действия в локализированный аномалийный пул, затем делает бросок аномалии для отряда. (См. раздел Экспериментальные устройства в ORBAT Просвещенных.) За каждый пустой результат, полученный при броске, каждая модель в активном отряде получает 1 уровень беспорядка. Если модель уже имеет 3 беспорядка, она получает 1 урон вместо этого. Затем адмирал вытягивает карту из своей колоды Победа и Доблесть: • Если значение вытянутой карты четное, каждая боеготовая модель в отряде сразу восстанавливает 1 урон. • Если значение вытянутой карты нечетное, первый боевой акт, совершенный во время этой активации, добавляет 5 бонусных кубиков в свой пул действий. • Если значение вытянутой карты равно 1 или 2, адмирал может выбрать один из вышеуказанных результатов.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R175', 'ru', 'Civilian Vessel', '39517e43a4d8899e64b536184aeab9cf24e96d18644928e45a3aff35e02f85d3', 'Гражданское судно', 'Если противостоящий Адмирал желает выбрать эту модель в качестве Цели действия Атака или Бродсайд, он должен сначала сделать Проверку экипажа группы для активного отряда. Если Проверка не пройдена, действие заканчивается немедленно и отряд считается израсходовавшим действие. Кроме того, модели с этим свойством никогда не могут воспользоваться правилом Разведывательные партии.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R101', 'ru', 'Cloud Dive', '38603485826cfe6bb7859c31efe1111710b19f78bf73168e0a63d63ee0352160', 'Прыжок из облаков', 'Это Свойство применяется только в том случае, если каждая модель в отряде имеет его в своем профиле отряда - в противном случае оно игнорируется. Когда этот отряд Развертывается, его Адмирал должен выбрать либо развернуть его в Резерв, либо отложить его и объявить, что он выполнит Прыжок из облаков. Отряд, выполняющий Прыжок из облаков, развертывается на этапе Особого развертывания фазы Развертывания. Его Адмирал размещает отряд где угодно в Игровой зоне так, чтобы ни одна из его моделей не находилась в 2" от вражеской модели или в 15" от зоны развертывания противника. После того, как отряд выполняет Прыжок из облаков, он помечается маркером Входящий, как если бы он был развернут из Резерва.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R313', 'ru', 'Cloud-Strike', '0ce4356b3859be2619100078e56140cf4d50dfff95daaa4c2013c7f792ca3100', 'Удар из облака', 'В начале фазы запуска каждого хода этот Адмирал может запустить один стек из 4 токенов истребителей Doksuri, как если бы он был запущен отрядом авианосца в центре игровой зоны.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R269', 'ru', 'Co-ordinated Explosion', '7b79943883c9a9e52430c60f6307dd38fd9b6f5a8ac08ee47f014fec597cb6b0', 'Координированный взрыв', 'При разрешении миссии Атака, если любая цель Атаки находится в пределах 20" от дружественной модели с свойством Безумная буря, каждая Жетон в Стеке с этим свойством SRS позволяет Адмиралу преобразовать один Тяжелый успех в броске действия в Взрывной успех. Это преобразование происходит в начале этапа разрешения Взрывных успехов.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R265', 'ru', 'Collision', '09c790c0c226e59082df35f3635e2b4e9fd4688933e9f74eb06ff9866a23f149', 'Столкновение', '**РАЗРЕШЕНИЕ СТОЛКНОВЕНИЯ** При столкновении перемещающаяся модель сразу же получает 1 уровень Беспорядка. Если она столкнулась с другой моделью, то эта модель также получает 1 уровень Беспорядка, если только ее рейтинг Массы не выше, чем у перемещающейся модели. Если перемещающаяся модель столкнулась с особенностью местности или с моделью, чей рейтинг Массы выше, чем у нее самой, адмирал перемещающейся модели бросает количество Дайсов Действия, равное рейтингу Массы перемещающейся модели. Перемещающаяся модель получает 1 урон за каждый Успех (любого рода), который они выбрасывают. В своей следующей Активации модель, участвовавшая в столкновении, возможно, не сможет двигаться вперед без возникновения еще одного столкновения. Обычно это можно избежать, сделав Полный Разворот, чтобы двигаться назад вместо этого **ТАРАН** Когда перемещающаяся модель сталкивается с вражеской моделью после перемещения на расстояние не менее 3", и точка контакта находится в переднем секторе перемещающейся модели, активный адмирал может объявить Таран.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R266', 'ru', 'Combat Divers', '8d693aaefd638e73d3ced45bc9dc50e35e85a9582b46c484f3b5820d5923efcf', 'Боевые Пловцы', 'Когда отряд этой модели совершает действие Абордаж, целью может быть модель Поверхности или Подводная модель, и эта модель может участвовать. Кроме того, отряд этой модели может совершать действия Абордаж, находясь Подводой, пока цель также находится Подводой');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R9', 'ru', 'Combat Science Pioneer', '39c79c57b98d1f9d4a32d50f439b31e47630eb093e3ff9f266c3946e7e225432', 'Пионер боевой науки', 'Один раз за игру, когда активируется флагманский отряд, этот Адмирал может попытаться ввести в действие Специальный эффект доблести. Если он успешно введен в действие, отряд получает свойство Вдохновляющий (6”) до фазы конца этого Хода.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R337', 'ru', 'COMBINED ARMS', '84ba4c98d0830dc61b1cff4d1c67abd8b429024be579e29aa0c0fcc47e02bf63', 'ВЗАИМОДЕЙСТВИЕ РОДОВ ВОЙСК', 'Эта доктрина может быть приобретена только для флагманского отряда Союза. Когда последняя модель в отряде из этого Силы уничтожается или отступает, не удаляйте его токены Эскорта из зоны игры. Вместо этого переместите токены Эскорта к ближайшему дружественному отряду с тем же позиционным признаком. Кроме того, всякий раз, когда Акронский Ротор Сентри уничтожается или отступает, бросьте кубик действия: при любом результате Успеха ближайший дружественный отряд получает токен Эскорта. Это правило может позволить отряду иметь больше токенов Эскорта, чем он мог бы обычно купить во время выбора Силы.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R345', 'ru', 'Comunicacao Network', '4c3bbc9276fe19521f97c897991cdf7a821033023114257d6b3186a0441c537a', 'Сеть связи', 'Каждая модель в этом отряде с признаком Portuguese получает систему ретранслятора гидрофона.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R6', 'ru', 'Constructs: Loyal Unto Death', '00734a0498422a9fb4db96bc8d4a558a24d6ebb9ab76279a3bb634ecd6f5703f', 'Конструкты: Верные до смерти', 'Один раз за Раунд, до того как этот Адмирал сделает проверку Экипажа для модели, он может использовать эту Доктрину, чтобы предоставить модификатор +2 к рейтингу Экипажа этой модели, но только для целей этого теста. В случае Групповой проверки Экипажа этот модификатор применяется ко всем моделям в отряде.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R303', 'ru', 'CONTROL OF THE COSMOS', '90ce376231f5b8b11b1a1da2c25f59b1389aebfd2ed94c6788ae7fd28af160b2', 'КОНТРОЛЬ КОСМОСА', 'Эта доктрина может быть приобретена только для отряда флагманского корабля Ордена. Однажды за Ход, в начале фазы активации этого Флота, адмирал может выбросить карту Победы и Доблести из своей руки вместо выполнения миссии СРС. Если он сделает это, он сразу же ликвидирует маркер Портала. Как только это будет разрешено, он может сразу же создать Портал где угодно в Игровой Зоне, где нет модели, особенности местности или другого маркера, или перекрытия с воздушной или подводной моделью. Это можно сделать только в том случае, если в Игровой Зоне есть хотя бы одна дружественная модель манипулятора Портала.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R293', 'ru', 'Coordinated Defences', '7df8900cc1de5fafcf92226469da55ed6a16b3fea51ed004b4128cd4aaa736d4', 'Координированная оборона', 'Когда эта модель выбрана в качестве Начальной Цели действия Атаки, ее Адмирал может выбрать выполнение Проверки Экипажа для нее. Если проверка проходит, бросок сопротивления получает Бонусные Кубики, равные рейтингу Обороны всех других моделей в ее отряде, имеющих эту Систему и находящихся на расстоянии 4" от цели. Это не имеет эффекта против Атак, сделанных с использованием Погруженных Орудий.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R351', 'ru', 'Coordinated Units', 'a8c2068c8f7ede012fa9367fa72253d6cb6b826cd29d6729ff449c8fd8e1bc67', 'Координированные Отряды', 'Один раз за Раунд, Адмирал этого Боевого Флота может реализовать Специальный Эффект Мужества с союзным отрядом в его Силе, в конце его Активации. Если эффект реализован успешно, Адмирал выбирает другой дружественный союзный отряд, который находится в пределах 8" от активного отряда и не имеет статуса Активирован. Этот отряд немедленно Активируется, затем получает статус Активирован. Обратите внимание, что Адмирал не может разрешить Миссию СРС между двумя Активациями.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R43', 'ru', 'Cor Caroli Raiders', '38c861130eedb601adfe2e63619bb62347a45b3ed0f2b10cf5aef0f8fcf9729d', 'Рейдеры Кор Кароли', 'Когда отряд этой модели совершает действие Абордаж, его Адмирал может объявить, что это Рейд Портала. Если он сделает это, целью действия Абордаж может быть любая модель Поверхности, находящаяся в радиусе 4" от маркера Портала. Модели в активном отряде могут участвовать только если они имеют это Свойство и находятся в радиусе 4" от маркера Портала. При разрешении Рейда Портала рейтинг Защиты цели имеет модификатор -2');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R184', 'ru', 'Coruscating', 'd25bd15d466f7bc53fe6c6e3523adca5cf9d5b9946d1dd7eba0c85b9fb1a4ff8', 'Ослепляющий', 'Это оружие не может вносить свой вклад в обычное действие Атаки. Вместо этого этот Адмирал может объявить, что эта модель выпустит Ослепляющий Луч, уникальное действие, которое можно считать действием Атаки для цели любых других Качеств, которыми может обладать это оружие. Для этого этот Адмирал должен нарисовать линию шириной 2 см от носа этого корабля до другой стороны поля боя, обеспечивая, чтобы линия была полностью внутри зоны прицеливания (Targeting Arc) этого оружия. Каждая модель Surface (друг или враг), которую пересекает эта линия, является целью Ослепляющего Луча. *Примечание: инструмент для измерения Warcradle имеет примерно ширину 2 см и идеально подходит для определения траектории вашего луча.* Затем Адмирал бросает количество игральных костей действия, равное рейтингу Огневой мощи этого оружия на соответствующей дистанционной полосе для каждой цели Ослепляющего Луча. Цель получает 1 урон за каждый Стандартный Успех и 2 урона за каждый Тяжелый Успех и Взрывной Успех. Если цель получает хотя бы 1 урон, она также получает 1 уровень Беспорядка. *Примечание: Это не стандартное действие Атаки, поэтому Взрывные Успехи не вызывают дополнительных бросков костей, и правило Под Обстрелом не применяется.*');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R171', 'ru', 'Crew Check', '3359e82a57e39e78199c701b0adc83ef922e9b77fa3e36bb3c3a28e96b5f1051', 'Проверка экипажа', '**ПРОВЕДЕНИЕ ПРОВЕРОК ЭКИПАЖА** Карты Победы и Доблести также используются для проведения проверок экипажа. Когда правила указывают адмиралу провести проверку экипажа для модели, он вытягивает, открывает и затем сбрасывает верхнюю карту из своей колоды. Если значение карты выше рейтинга экипажа модели, проверка не проходит. В противном случае проверка проходит. **АВТОМАТИЧЕСКИЕ ПРОХОЖДЕНИЯ** Некоторые правила позволяют отряду автоматически проходить проверки экипажа. В этом случае не вытягивается карта - отряд просто считается прошедшим. **ДОБРОВОЛЬНЫЙ ПРОХОЖДЕНИЕ** Вместо проведения проверки экипажа адмирал может выбрать не проходить ее. Не вытягивается карта - отряд просто считается не прошедшим. **ГРУППОВЫЕ ПРОВЕРКИ ЭКИПАЖА** Некоторые правила требуют групповой проверки экипажа. Это делается так же, как и стандартная проверка экипажа, но проводится сразу для нескольких моделей. Групповая проверка экипажа использует самый низкий рейтинг экипажа среди моделей, для которых она проводится, учитывая любые модификаторы. **СЛ_OMЕННЫЙ ДУХ** Если колода Победы и Доблести адмирала заканчивается, это означает, что дух его Силы сломлен. Время для достижения незначительных побед и совершения героических поступков прошло. Адмирал сразу же перетасовывает свою кучу сброса и кладет ее рубашкой вниз, чтобы создать новую колоду. На протяжении всей оставшейся игры он больше не может вытягивать карты из колоды в руку. Карты все еще можно вытягивать для разрешения проверок экипажа, но его запас эффектов Доблести и незначительных побед иссяк, и он рискует быть вынужденным сдаться инициативе каждый раунд.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R150', 'ru', 'Crippled', 'af8ebf683796a58b726d2f2ebee97ba51117d7978b3f9feefb1724ef14743982', 'Выход из строя', '**ПОВРЕЖДЕНИЕ МОДЕЛИ** Если количество урона, которое модель накопила, равно или превышает ее рейтинг корпуса, модель сразу же выходит из строя. Противостоящий адмирал сразу же получает количество очков победы, равное рейтингу очков победы модели. **БОЕГОТОВЫЕ МОДЕЛИ** Любая модель, которая не вышла из строя, является боеготовой. Этот термин сам по себе не влияет на правила, но может быть упомянут в других правилах; например, некоторые цели могут быть выполнены только боеготовыми моделями. Поврежденная модель не удаляется из игры сразу, но остается в игре с существенным недостатком');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R105', 'ru', 'Cruor', '16dd628c675880580e432e77013f5b9cbb5612c6ff69c920eeaa3f7700f9dc43', 'Круор', 'После разрешения действия Атаки, в котором одно или несколько орудий с этим Качеством внесли свой вклад, активный Адмирал может попытаться реализовать Специальный Эффект Мужества с активной моделью. Если успешно, каждая модель в пределах 10" от Первоначальной Цели получает 1 уровень Беспорядка, если только у них нет указанного Признака.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R98', 'ru', 'Cryo Generator', '094baa1df771e1463a58cd96c6ca59e5fe372cd406bdbb202c73c9b84c046cf6', 'Генератор Криогена', 'Это Генератор. Криогенный Взрыв - это Специальное Действие, которое может быть выполнено любым отрядом, содержащим хотя бы одну модель с системой Генератора Криогена. **РАЗРЕШЕНИЕ ДЕЙСТВИЯ КРИОГЕННОГО ВЗРЫВА** Когда отряд совершает действие Криогенного Взрыва, его Адмирал использует следующий процесс. 1. ВЫБОР ЦЕЛИ Адмирал выбирает одно из следующих: • Вражескую модель Поверхности. • Конкретную точку Открытой Воды, находящуюся на расстоянии не менее 1" от любой модели, (включая те, у которых есть статус Входящий) Маркеров или Территориальных Объектов. (Отметьте эту точку токеном Эффекта Генератора). • Айсберг с Массой ниже 5. 2. НАЗНАЧЕНИЕ УЧАСТВУЮЩИХ МОДЕЛЕЙ Адмирал назначает любое количество моделей в активном отряде, которые будут участвовать в действии. Модель может участвовать только если она имеет Генератор Криогена, находится на расстоянии 10" от Цели и Цель Видна ей. (Для определения того, видна ли точка Открытой Воды, она считается имеющей рейтинг Массы 0.) Если ни одна модель не может участвовать, необходимо выбрать другую Цель. 3. СОВЕРШЕНИЕ КРИОГЕННОГО ВЗРЫВА Броска Адмирал активного отряда бросает количество Дайсов Действия, равное общему рейтингу Массы всех участвующих моделей. Каждый Тяжелый Успех и Взрывной Успех, выпавший на кубике, засчитывается как один Успех. (Обратите внимание, что это не Бросок Действия, поэтому Взрывные Успехи не позволяют бросать дополнительные кубики.) Если не было заработано ни одного Успеха, действие заканчивается. 4. РАЗРЕШЕНИЕ ИСХОДА Исход Криогенного Взрыва зависит от выбранной цели. ВРАЖЕСКАЯ МОДЕЛЬ ПОВЕРХНОСТИ За каждый заработанный Успех цель получает 1 Критический Ущерб. ОТКРЫТАЯ ВОДА Активный Адмирал заменяет токен Эффекта Генератора на Айсберг. Его Масса не может превышать количество заработанных Успехов. Айсберг должен быть размещен на расстоянии 1" от токена Эффекта Генератора и не находиться в Проксимити любой модели или других Территориальных Объектов. АЙСБЕРГ Масса Айсберга увеличивается на 1 за каждый Успех, до максимальной Массы 5.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R151', 'ru', 'Daredevil Crew', '9d31b029afeab47679872473417503d49c587178eb611e7e9f56e8fbbf4f5ea4', 'Экипаж-авантюрист', 'Эта модель автоматически проходит проверку экипажа при разрешении Тарана и не получает Беспорядок на этапе Нанесение Беспорядка. Вражеская модель получает Беспорядок как обычно. Кроме того, попытка Тарана не мешает этой модели участвовать в действиях Абordaжа на последующем этапе Действия. Она по-прежнему не может участвовать в других Действиях. *Обратите внимание, что это Свойство не позволяет отряду модели запустить действие Абordaжа, если у него нет другого Свойства, которое позволяет ему сделать это.*');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R325', 'ru', 'Dark Hand', '5a264dddbf84d9b821f6ab504924d9d0d9daaa5bd845ab98e132a005a5c4bf92', 'Темная Рука', 'Один раз за Ход, если модель из этого отряда находится в Игровой Зоне, Адмирал этого Боевого Флота может автоматически отклонить Эффект Мужества без сбрасывания карты из своей руки. Если он это сделает, каждая модель в отряде Лордов Худа получает 1 уровень Беспорядка.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R28', 'ru', 'Deathblow', '3fd320ad8a3ede95018e8fc72625f683cf5756c4731b029d2adf59a3d1056dc8', 'Смертельный удар', 'Когда объявляется действие Атака с отрядом, в котором есть хотя бы одно оружие с этим качеством, можно объявить, что будет предпринята попытка Смертельного удара. После шага Объявление вносящих вклад оружий Адмирал производит Групповой бросок экипажа для участвующих моделей. Если проверка пройдена, то каждое оружие в отряде с этим качеством удваивает каждую из своих показателей огневой мощи, но считается имеющим качество Интенсивный. *Обратите внимание, что Смертельный удар можно предпринять только с отрядом, у которого осталось не менее двух действий.*');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R217', 'ru', 'Decend', '9503c8b5a471ffed0c33406d46f355911a7c0fc298b54a3a8db9c830ee247fc1', 'Спуск', 'Это Свойство применяется только если каждая модель в отряде имеет его в своем профиле отряда - в противном случае оно игнорируется. В начале каждой Активации этого отряда, его Адмирал должен выбрать его позицию: он может парить высоко, в этом случае он остается Воздушным отрядом, следуя всем обычным правилам для Воздушных отрядов, или он может Спуститься, чтобы зависнуть на небольшом расстоянии над водой, временно став Поверхностным отрядом. Отряд, который Спускается, получает токен статуса Появления на поверхность до начала своей следующей Активации. Пока он подвержен этому статусу, он считается имеющим позиционный признак Поверхность вместо Воздушный, и не подвержен правилам Открытое небо или Необычная цель. Аналогично, отряд рассматривает все Территориальные особенности как Открытую воду для целей Движения и не препятствуется Опасной водой, не запускает маркеры Минного поля и никогда не получает Критического урона в результате контакта с маркером Обломков. Погруженные орудия не могут вносить свой вклад в действия Атаки против моделей, появляющихся на поверхность.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R208', 'ru', 'Deceptive Deployment', '4561b610aa61694c5fe5b9617dcd798c8a2d1b6372226f50f3e1de71c7563d7a', 'Обманчивое развертывание', 'Это Свойство применяется только в том случае, если каждая модель в отряде имеет его в своем профиле отряда - в противном случае оно игнорируется. Во время развертывания этот отряд может совершить Специальное действие развертывания, чтобы Переразвернуться, пока он был развернут в Игровой зоне. Активный Адмирал удаляет отряд из игры, затем развертывает его снова, следуя всем стандартным правилам развертывания. (Включая любые специальные правила, такие как Передовое развертывание) Отряд можно переразвернуть в Резерв, пока он обычно может сделать это.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R164', 'ru', 'Deck Sweepers', 'c11530e8d214062056e51e6c104119fab2985b6adc1c98954258974f006fd443', 'Чистильщики палубы', 'Когда эта модель выбрана в качестве Цели действия Абordaж, ее Адмирал может выбрать выполнение Проверки экипажа для нее. Если Проверка пройдена, эта модель получает модификатор экипажа +2 при определении количества Успехов, набранных активным Адмиралом.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R86', 'ru', 'Defensive', 'f5537194a85e5a89e61195f17fd20e86ffc8f0d4680f4d99a54a0bd97de6138a', 'Защитный', 'Любая другая дружественная модель, находящаяся в пределах 4" от этой модели и имеющая тот же Позиционный Трейт, защищается ею. Это дает дружественной модели модификатор +X к ее рейтингу защиты. Несколько моделей с этой Системой могут защищать одну и ту же дружественную модель. Когда это происходит, модификаторы складываются вместе.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R226', 'ru', 'Depth Charge', 'ebf543df34e7ca36d14d9c1e1d8de68d535ac135d45e0e778c53c1536761abb9', 'Глубинная бомба', 'Модель подводного класса может быть выбрана в качестве Начального цели этого действия атаки, пока все вносящие вклад орудия обладают этим качеством. Орудие с этим качеством не может вносить вклад в какое-либо действие атаки, в котором модель воздушного класса является Начальной целью.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R45', 'ru', 'Descend', 'd96fdb7e3bd849e272199ae3261f46745cceb436902010649587f1fbbde38b31', 'Снижение', '*Это Свойство применяется только если каждая модель в отряде имеет его в своем профиле отряда - в противном случае оно игнорируется.* В начале каждой Активации этого отряда, его Адмирал должен выбрать его позицию: он может летать высоко, в этом случае он остается Воздушным отрядом, следуя всем обычным правилам для Воздушных отрядов, или он может Спуститься, чтобы зависнуть на коротком расстоянии над водой, временно став Surface отрядом. Отряд, который Спускается, получает токен статуса Появления на поверхность до начала своей следующей Активации. Пока он подвержен этому статусу, он считается имеющим позиционный признак Surface вместо Airborne и не подвержен правилам Wide Open Skies или Unconventional Target. Отряд рассматривает все Территориальные Особенности как Открытую Воду для целей Движения и не препятствуется Опасной Водой, не запускает маркеры Минного поля и никогда не получает Критического Урона в результате контакта с маркером Врека. Модели в отряде могут Пройти Через другие Surface модели, но если они это делают, обе модели получают 1 уровень Беспорядка. Погруженные Орудия не могут Внести свой вклад в Атаки против моделей, появляющихся на поверхность.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R225', 'ru', 'Devastating', '93351aafc8eeb9b806034ab016a2318d00802c3b7a78f6e38ca16aabbcd2c412', 'Разрушительный', 'Каждое орудие с этим качеством позволяет активному Адмиралу преобразовать до X тяжелых успехов в взрывные успехи в броске действия, сразу после броска кубиков, до начала этапа разрешения взрывных успехов. *Примечание: это качество напрямую противостоит свойству Броня-абляция (X). См. подробности в описании этого свойства.*');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R317', 'ru', 'DEVIL’S OWN LUCK', 'b9a819fabd2bc54750a52b55884d619b5fd9a03f4f48c225c9888c5468cd6248', 'ДЬЯВОЛЬСКАЯ УДАЧА', 'Один раз за игру, когда противостоящий Адмирал пытается реализовать Эффект Мужества, этот Адмирал может использовать эту Доктрину вместо попытки отклонить эффект. Противостоящий Адмирал раскрывает свою Карточку Мужества. Если у нее Значение 8 или меньше, она сбрасывается без реализации.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R233', 'ru', 'Diophantus Chaos-Orb', '2319007f3a7c49785431515ae1b6222bd3cf9c1f2ed7f5acaa05585d29027a45', 'Диофант Хаос-Орб', 'На этапе вытягивания карт в фазе готовности контролирующий адмирал вытягивает 2 бонусные карты, если у него есть хотя бы одна модель с этой системой в игровой зоне. Кроме того, как специальное действие, отряд этой модели может выпустить Хаос. Участвовать могут только модели с этой системой. Адмирал отряда добавляет один кубик действия в локализированный аномалийный пул, затем совершает бросок аномалии для отряда. (См. раздел Экспериментальные устройства в ORBAT Просвещенных.) За каждый пустой результат, каждый участвующий модель получает 1 уровень беспорядка. Если участвующая модель уже имеет 3 беспорядка, она получает 1 урон вместо этого. Затем каждая вражеская модель, находящаяся в пределах 5" от хотя бы одной участвующей модели, получает критический урон от эффекта "Разорванная защита".');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R160', 'ru', 'Dirigible', 'e0cb873371f0fe0ebfa9c8b11ba2d9831ca8c5b4ab44e4f5a91bfb3f8dde17be', 'Дирижабль', 'Всегда, когда эта модель должна понести Критический Ущерб Прорыва или Структурного Повреждения, она понесет вместо этого два случая этого Эффекта.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R119', 'ru', 'Disorder', 'ccaa764045995ef4ff98962753cfd9eb8f457ad4055705f52a5624f79a38d943', 'Беспорядок', '**ПРИОБРЕТЕНИЕ БЕСПОРЯДКА** Помимо повреждений, модели могут получить до 3 уровней Беспорядка. Это представляет собой потерю сплоченности среди экипажа судна, будь то из-за стрессовых ситуаций, физического вреда или экологической опасности. Текущий уровень Беспорядка модели, как и повреждения, отслеживается на основе отдельных моделей, путем размещения жетона Беспорядка в контакте с моделью. Если у модели нет Беспорядка, жетон не нужен. Беспорядок не является постоянным, как повреждения, но не может быть удален, если правило не позволяет этого. Наиболее распространенный способ для модели потерять уровни Беспорядка - это ralliing в конце своей Активации. **ЭФФЕКТЫ БЕСПОРЯДКА** Модель с Беспорядком подвергается различным штрафам, в зависимости от уровня Беспорядка: Деморализованный Все уровни Каждый уровень Беспорядка, который имеет модель, накладывает модификатор -1 на ее рейтинг экипажа. *Например, модель с рейтингом экипажа 7 имеет 2 уровня Беспорядка, поэтому ее рейтинг экипажа считается равным 5.* Паника Уровень 2 Если для модели с 2 уровнями Беспорядка сделан бросок действия, любые тяжелые успехи в броске преобразуются в стандартные успехи после разрешения повторных бросков. Мятежный Уровень 3 Если для модели с 3 уровнями Беспорядка сделан бросок действия, любые тяжелые и взрывные успехи в броске преобразуются в стандартные успехи после разрешения повторных бросков. Если модель совершает полный реверс или аварийный маневр, она получает очко повреждения вместо уровня Беспорядка. Если бросок действия сделан для более чем одной модели одновременно (например, при разрешении атаки, в которой участвуют несколько моделей), используется самый высокий уровень Беспорядка среди моделей. **ДРУГИЕ ЭФФЕКТЫ БЕСПОРЯДКА** При броске бортового залпа по цели, если хотя бы одна участвующая модель имеет 2 уровня Беспорядка, тяжелые успехи наносят только 1 повреждение. Если хотя бы одна участвующая модель имеет 3 уровня Беспорядка, тяжелые и взрывные успехи наносят только 1 повреждение. Когда отряд авианосцев разрешает запуск СРС, каждый уровень Беспорядка на модели в отряде уменьшает количество жетонов СРС, которые он может запустить, на 1. **РАСПРОСТРАНЕНИЕ БЕСПОРЯДКА** Модель не может иметь более 3 уровней Беспорядка. Если правило вызывает получение модели четвертого уровня Беспорядка, он распространяется на ближайшую дружественную модель в радиусе 4", которая получает 1 уровень Беспорядка. Если ближайшая дружественная модель уже имеет 3 уровня Беспорядка, он не распространяется и не имеет эффекта. Если две модели находятся на одинаковом расстоянии, Беспорядок распространяется на ту, у которой самый низкий уровень Беспорядка. Если это все еще ничья, противостоящий адмирал выбирает, на какую модель он распространяется.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R197', 'ru', 'Disruption', '1ed10384702a2acea3f60543ea8921c93b5df41897df11746e0eefc24b093ad6', 'Нарушение', 'Если Первоначальная Цель получает хотя бы 1 Беспорядок в результате этого действия, она получает токен Негативного Эффекта (если у нее его еще нет). Это токен Нарушения. Модель с токеном Нарушения имеет модификатор -1 для Экипажа, и стандартные Эффекты Мужества не могут быть применены к ней. (Специальные Эффекты Мужества могут быть применены к ней как обычно.) На этапе Консолидации следующей Активации модели токен Нарушения с нее удаляется.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R162', 'ru', 'Diving And Surfacing', '3309642c9d48427ec5100d9ef8868e98e49d3be598f26751765690209baf0c5c', 'Погружение и всплытие', 'Немедленно после развертывания подводного отряда и в начале каждого его активации, его адмирал должен выбрать его позицию: он может скрываться под волнами, в этом случае он остается подводным отрядом и следует всем правилам на этой странице, или он может подняться на поверхность, временно став отрядом поверхности. Отряд, поднимающийся на поверхность, получает токен статуса всплытия до начала своей следующей активации. Пока он имеет этот статус, он считается имеющим позиционный признак поверхности вместо подводного, и не подвергается правилам подводного положения.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R321', 'ru', 'DO OR DIE', '6d4463db2b7146702466d77bdd2dcdd3a77a910efc76a8d70c28d6b753f4e194', 'СДЕЛАЙ ИЛИ УМРИ', 'Один раз за Ход, до того как этот Адмирал сделает проверку Экипажа для модели, он может использовать эту Доктрину, чтобы предоставить модификатор +2 к рейтингу Экипажа этой модели, но только для цели этого теста. В случае Групповой проверки Экипажа этот модификатор применяется ко всем моделям в отряде.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R218', 'ru', 'Ekranoplan', '6bf90faa6d8782b567ef5c59a40d3b86f9b84d69ed296a9520714fe8743cdb7f', 'Экраноплан', 'Эта модель может перемещаться в или через опасности для посадки без столкновения с ними и может все еще восстанавливать порядок, когда она находится в пределах дистанции действия от них.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R85', 'ru', 'Elevated', 'ff40dc24fca5eb682ee45d933e77d59b4f8bdc6a087d4744d5da9630ebc91bc2', 'Повышенная', 'Эта модель не препятствуется Тревожными водами, не запускает маркеры минных полей и никогда не получает Критического урона в результате контакта с маркером Врека. Если эта модель является Первоначальной целью действия Атаки, погруженные орудия не могут внести свой вклад.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R329', 'ru', 'EMERGENCY FIRING DRILLS', 'dc791c164f12f4e1143f2576387b6deb02690c9c72aa39c65ce3342770137f5c', 'ЭКСТРЕННЫЕ ОГНЕВЫЕ УЧЕНИЯ', 'Может быть приобретено только для отряда флагманского корабля Crown. Однажды за ход, до того как этот Адмирал совершит действие Атаки с отрядом корабля Crown, он может попытаться реализовать Специальный Эффект Храбрости с этим отрядом. Если успешно, Эффекты Беспорядка (см. страницу 57 книги правил Dystopian Wars) игнорируются на протяжении всей атаки.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R282', 'ru', 'Emergency Manoeuvre', 'ac4bdad274ba13d85a8ffe7c6c73c089e6dc8ac26a13675810287e5aaf27ec2b', 'Аварийный маневр', 'Адмирал может объявить, что модель совершит Аварийный маневр в любой момент своего хода. Модель может совершить Дополнительный маневр, но получает уровень Беспорядка. Если модель имеет 3 уровня Беспорядка, она получает очко Урона вместо этого. Модель может совершать Аварийные маневры несколько раз за один ход.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R163', 'ru', 'Encompassing Broadsides', '865ea7bec0624733176023d1860628ec6a7e9a111b439f6e4e73a42d72553189', 'Окружающие бортовые залпы', 'На этапе определения вносящих вклад батарей при действии Борт, эта модель может выбрать Цель, находящуюся в любом из ее Секторов, а не только в левом и правом борту.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R134', 'ru', 'Enhanced Solex', '55f32d9755bc17ed84cd3fec601575819b486d993679b9127fbb1da49eb9e4cf', 'Улучшенный Солекс', 'После шага разрешения взрывающих успехов броска действия Атака, каждое вносящее вклад оружие с этим качеством позволяет активному Адмиралу преобразовать до X маркеров в броске действия в эквивалентные успехи. (Стандартные маркеры становятся стандартными успехами, а тяжелые маркеры становятся тяжелыми успехами.)');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R18', 'ru', 'Enlightened Science', '15312063571f356a7fc0c6306596d9e4b60e703445821a84ff24f945b75102b8', 'Просвещенная наука', 'В фазе окончания каждого хода этот Адмирал удаляет один бросок действия из своего локализованного аномального пула.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R88', 'ru', 'Entropic Generator', '78a387782ebe5e90b05f65df3c860174ef3a2c97b14ee3aad2b2ac56f5b11e6d', 'Генератор Энтропии', 'Это Генератор. Когда модель является целью действия Атаки, ее Адмирал может перебросить два пустых результата в броске сопротивления для каждого Генератора Энтропии, установленного на модели в ее отряде (включая саму модель). Кроме того, каждый Генератор Энтропии всегда оснащен одним из орудий из таблицы ниже (выбираемым во время выбора Сил). Модель с Генератором Энтропии считается оснащенной выбранным орудием (орудиями), используя Сектор (секторов) Тяжелой Точки Установки, которую этот Генератор заменяет. ОРУЖИЕ C S E КАЧЕСТВА Усовершенствованная Эфирная Ланца 4 4 – Точный (1) ESCF Легкая Пушечная Батарея 2 4 – Боеприпасы ESCF ESCF Легкая Ракетная Батарея – 4 – Барраж, Боеприпасы ESCF');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R46', 'ru', 'ESCF Munitions', '577a03299dbee4bf8c6a00561642ac3b1cff5f89145749c9d0817ed10e6473e5', 'Боеприпасы ЭСКФ', 'Если все орудия, вносящие вклад в действие Атаки, имеют это качество, адмирал может перебросить любые Пустые результаты в броске действия.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R272', 'ru', 'Escort', '81fc11e10beafeae5fe413f6ac8ad0107a29edb8818ffc200a8a02d31787a4d1', 'Эскорт', '**ЗАЩИТНЫЙ ОГОНЬ** Когда модель подвергается атаке действия, действию высадки или миссии воздушного нападения, каждый токен Эскорта, выделенный отряду модели, добавляет 1 Бонусный кубик в Пул Сопротивления. **ГЕРОИЧЕСКАЯ ЖЕРТВА** Вместо добавления 1 Кубика Действия в Пул Сопротивления, Адмирал может выбросить токен Эскорта, чтобы добавить 3 Кубика Действия. **ГРУППЫ НАБЕГА** Перед объявлением Действия для отряда, его Адмирал может выбросить любое количество токенов Эскорта из отряда. Если он это делает, отряд получает свойство Группы Набега (X) на время Действия, со значением X, равным удвоенному количеству выброшенных токенов. Это можно использовать, чтобы позволить отряду запустить действие высадки, когда он обычно не может этого сделать, или чтобы увеличить значение X существующего свойства Группы Набега (X) отряда.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R174', 'ru', 'Escort Bay', 'ca2cf49045680812a883bb36e83c9c1065a9369cefe2cb9592597da522b00953', 'Бухта Эскорта', 'Как Специальное Действие, отряд этой модели может Развернуть Эскорты. Сделайте Групповой Проверку Экипажа для отряда. Если проверка пройдена, Адмирал может назначить X токенов Эскорта для каждой модели с этой системой любому дружественному отряду в пределах 10", включая сам отряд. Адмирал может разделить эти токены между разными отрядами, как они считают нужным, но они не могут назначить больше токенов Эскорта отряду, чем обычно разрешено во время выбора Силы.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R169', 'ru', 'Escort Support', 'b68d59250fd17c740d0f959f589987ef588c5d7b1fc2ab1f500140b14582a9ff', 'Поддержка Эскорта', 'Отряд этой модели, и каждый дружественный отряд в пределах 10" от этой модели, имеет Поддержку Эскорта, которая предоставляет следующие преимущества: если отряд использует правило Разведывательные Партии (см. страницу 103 Dystopian Wars: The Rules), значение X свойства Десантные Партии (X) равно три раза числу сброшенных жетонов Эскорта, вместо двух раз. Кроме того, если жетон Эскорта сбрасывается из отряда по любой причине, кроме Разведывательных Партий, его Адмирал совершает бросок действия. Если результат показывает Стандартный Контр или Тяжелый Контр, жетон остается в игре.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R299', 'ru', 'Escort Tokens', 'ee40ce21bc8401ebed95d31b27c7ad2bf799ac90b15a85b5da5e252d825ee316', 'Токены Эскорта', 'См. страницу 102 для полных правил токенов Эскорта. ОБОРОНИТЕЛЬНЫЙ ОГОНЬ Когда модель подвергается атаке действия, действия Борта или миссии Атакующего Пролета, каждый токен Эскорта, выделенный для отряда модели, добавляет 1 Бонусный Кубик в Пул Сопротивления. ГЕРОИЧЕСКАЯ ЖЕРТВА Вместо добавления 1 Кубика Действия в Пул Сопротивления, Адмирал может выбросить токен Эскорта, чтобы добавить 3 Кубика Действия. КОЛЛАТЕРАЛЬНЫЙ УЩЕРБ Если модель понесла Катастрофический Взрыв, противоположный Адмирал бросает кубик для каждого токена Эскорта, сопровождающего его отряд. При Успехе токен Эскорта удаляется из игры. Когда последняя модель в отряде уничтожена или отступает, все его токены Эскорта сразу удаляются из игры. РЕЙДЕРЫ ПЕРЕД объявлением Действия для отряда, его Адмирал может выбросить любое количество токенов Эскорта из отряда. Если они это сделают, отряд получает свойство Десантные Партии (X) на время Действия, со значением X, равным удвоенному числу выброшенных Токенов. Это можно использовать, чтобы позволить отряду запустить действие Борта, когда он обычно не может этого сделать, или чтобы увеличить значение X существующего свойства Десантные Партии (X) отряда.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R123', 'ru', 'Euripidean Host', '75d1e63913951d10434a24d9c73a9411ad3be7c4d3f4d2e74b1027ca951b5aa5', 'Еврипидова Эскадра', 'Один раз за игру отряд этой модели может совершить Специальное Действие, чтобы Отделить Подлодки-реморы. Когда это происходит, адмирал отряда устанавливает новый отряд из 6 подлодок Еврипид. Каждая модель в новом отряде должна быть размещена в пределах 4" от модели в активном отряде, и ни одна модель не может быть размещена в пределах 1" от модели вне активного отряда. Новый отряд помечается маркером Активирован. Теперь это полноценный отряд внутри Силы, и может быть активирован как обычно, начиная со следующего хода.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R286', 'ru', 'Evasive', 'a92dd8482d91de596b10392b198ff0b7145dd8336888988b377c82de5b5defb5', 'Уклонение', 'Во время шага нанесения урона действия Атаки, в котором эта модель является Целью, ее Адмирал может, пока у нее нет 3 уровней Беспорядка, объявить Уклоняющиеся маневры. Если он это делает, то любой нанесенный урон может быть преобразован в Беспорядок до тех пор, пока у модели не будет 3 уровней Беспорядка. Если действие Атаки привело к большему количеству урона, чем это количество, то оставшаяся часть применяется к модели как обычно. Если Адмирал объявляет Уклоняющиеся маневры, то эта модель не страдает от эффектов Под огнем. *Примечание: вам не обязательно сразу преобразовывать весь урон в Беспорядок. Если модель получает 3 урона, она может выбрать преобразовать только 1 в Беспорядок, а не все 3.*');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R358', 'ru', 'EVASIVE MANOEUVRES', 'dce68856dc0e2f99d8247b49242da57c883b69ccd19fa0cd194d0097b61b1f57', 'МАНЁВРЫ УКЛОНЕНИЯ', 'Эта Доктрина может быть приобретена только для флагманского отряда Польско-Литовского флота. Немедленно после броска сопротивления для действия атаки, нацеленной на польско-литовскую модель в их флоте, адмирал этого Боевого флота может попытаться реализовать Специальный Эффект Мужества с этой моделью. Если успешно, любые взрывные успехи в броске сопротивления сразу же преобразуются в Тяжелые Контрмеры.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R308', 'ru', 'EVERYONE HAS THEIR PRICE', '89faf18e4b4192efa5ad3f553e7b6dfcd7233332b4d398ec6f5d1c4ff3408cef', 'У КАЖДОГО СВОЯ ЦЕНА', 'Один раз за игру, до совершения броска действия для действия Boarding, этот Адмирал может выбросить карту Victory и Valour из своей руки. Если он это сделает, то в течение действия рейтинг защиты Цели снижается до 0');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R275', 'ru', 'Exceptional', '8a2477d4d8809fb938540e227ffea65dd3a4f1e8d1ddbe81df1a254534376f8a', 'Исключительный', 'Этот токен СРС может быть объединен только с другими токенами СРС того же типа. Стек, состоящий из этих токенов, не может быть выделен отряду, которому уже выделены дружественные токены СРС другого типа. Обратное также верно - отряду, которому уже выделен стек этих токенов СРС, не могут быть выделены дружественные токены СРС другого типа.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R59', 'ru', 'Exo-sub', 'f8140b022bd7565ceb0b167954ae09345fb90dda884bf2f6b15937bfb778b62d', 'Экзо-подлодка', 'При разрешении миссии Атака с помощью стека, содержащего только токены SRS с этим качеством, каждый Прорыв или Структурная неисправность, распределенный по цели Атаки, также наносит 1 урон.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R365', 'ru', 'Experimental Warfare', 'ecc0a8182cf112af71e34fc1f54625aacbef6f49729cc81ea329ba92d8f515c0', 'Экспериментальная война', 'Один раз за Ход, когда производится бросок ремонта для отряда в этом Флоте с свойством Тевтонская конструкция, Адмирал может перебросить каждый кубик, который не показывает Взрывной успех.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R210', 'ru', 'Eye Of Yeomna', 'ae08a8fed521eb7105ae6e6687fa0a6cb88ee2da4bba857a5f436093e5cd2931', 'Глаз Йомны', 'Как Специальное действие, отряд этой модели может произнести Суд Йомны против вражеского отряда в радиусе 15". Только модели с этой Системой и в радиусе 15" от целевого отряда могут участвовать. Чтобы разрешить Суд Йомны, выделите стопку SRS из X токенов истребителей Доксури для каждой участвующей модели целевому отряду, как если бы он только что запустил миссию Атакующего полета. Кроме того, при разрешении дружественной миссии Атакующего полета, где хотя бы одна цель атаки находится в радиусе 15" от этой модели, увеличьте рейтинг атаки каждого токена истребителя Доксури в стопке на 1 до завершения миссии.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R344', 'ru', 'FALLING AVALANCHE', 'e5f9c806fe377c0b4460a6c7027fbbace5151fa21b559189d09dc48bd8636452', 'ПАДАЮЩАЯ ЛАВИНА', 'Эта доктрина может быть приобретена только для флагманского отряда Империи. Когда этот Адмирал объявляет вражескую модель первоначальной целью действия Атаки, он может сбросить карту Победы и Доблести из своей руки. Если он сделает это, любое орудие с качеством Барраж может использовать стандартное значение огневой мощи на дальнем расстоянии вместо значения огневой мощи на ближнем расстоянии, даже если это орудие не имеет значения огневой мощи на ближнем расстоянии. Однако видимость цели всегда считается затрудненной.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R35', 'ru', 'Flak Barrage', '80036c8934a1f86a43dd8585e7fcf5cd8e18ceddd6edb852a56ae6967f7631d7', 'Зенитный Барабан', 'Как Специальное Действие, отряд этой модели может обрушить Зенитный Барабан на вражеский стек СРС, выделенный отряду или Маркеру в пределах 10". Только модели с этой Системой и в пределах 10" от целевого отряда или Маркера могут участвовать. Чтобы разрешить Зенитный Барабан, активный Адмирал совершает бросок действия. Бросок сопротивления не производится. Участвующие модели в Пуле Действий добавляют X игральных костей действия в Пул. Порог Успеха равен показателю Выносливости целевого стека. За каждый Успех, набранный в броске действия, удаляется один токен СРС из целевого стека. Ховер или Подводный СРС **НЕ МОЖЕТ** быть удален таким образом');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R10', 'ru', 'Flenser Torpedoes', 'cbf0bf3275a9e74f7ce7beef121892b58a1abf6f24a0bacfd3c4f7a30908ff10', 'Торпеды Фленсера', 'Один раз за Раунд, когда отряд из этого Флота совершает действие Атаки и есть хотя бы одно вносящее вклад оружие с качеством Торпеда, Адмирал может выбросить карту Победы и Доблести из своей руки до броска действия. Если он это сделает, он может перебросить любые пустые результаты в броске действия.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R80', 'ru', 'Flight Command', 'f62369a7ba190c873657b92d5394474950a01eac1e03dabf5be60c4767db19ca', 'Команда полета', 'Как Специальное действие, отряд этой модели может отдать новые боевые приказы. Когда он это делает, его Адмирал выбирает до X дружественных стопок СРС, и выделяет каждую из них новому отряду или Маркеру, который находится в пределах 10" от отряда или Маркера, которому она в настоящее время выделена. Это должно быть допустимой целью для стопки, т.е. той, которой она могла бы быть выделена обычно на этапе выбора миссии СРС фазы запуска. *Обратите внимание, что нет дополнительной выгоды от наличия более одной модели в одном отряде с этим свойством.*');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R146', 'ru', 'Flight Deck', '56de68c88bd766a53bf574e6bad92264202d1c90ea54d30dd9a3f4752f24d3a5', 'Полетная палуба', 'В конце Хода перемещения отряда каждая модель в отряде с этим свойством поднимает в воздух ближние эскадрильи, которые могут либо Поддержать Миссию, либо Создать помехи. Если эскадрильи Поддерживают Миссию, Адмирал отряда выбирает дружественный стек СРС. Для каждой взлетевшей модели, находящейся в 10" от модели или маркера, которому назначен выбранный стек, в выбранный стек добавляется один токен СРС указанного типа. Если эскадрильи Создают помехи, каждая взлетевшая модель добавляет один токен СРС указанного типа в активный отряд, как если бы они получали Воздушную поддержку Миссии.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R368', 'ru', 'FLOTILLA OF IRON', '946d8cf19d0d3a98aa02908fd7136655a9ac9671bb8c38013c1bad40fd583fa2', 'ЖЕЛЕЗНАЯ ФЛОТИЛИЯ', 'Эта доктрина может быть приобретена только для отряда прусского флагманского корабля. Все модели прусского флагманского корабля в этом флоте получают модификатор +1 к рейтингу экипажа. Кроме того, все прусские модели в этом флоте, находящиеся на расстоянии 7" или менее от хотя бы одного дружественного прусского флагманского корабля с тем же позиционным признаком, получают модификатор +1 к рейтингу экипажа.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R207', 'ru', 'Flotsam', 'b85b2c1e66fb10f82de5d79fa2df8b4cd91cc31b0a35bdd243d1f90f91e7f780', 'Обломки', 'Если эта модель уничтожена, замените ее на маркер Обломков, размещенный над центральной точкой модели. Если это приведет к тому, что маркер будет размещен в контакте с особенностью местности, моделью или другим маркером, он не размещается.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R302', 'ru', 'FLY, SABIHA, FLY!', 'acb225cac27cd1d938462812fdc13de80789f3de8ad03cb38faeeb3d42a4f3a8', 'ЛЕТИ, САБИХА, ЛЕТИ!', 'Во время Фазы запуска этот адмирал может назначать любое количество стопок токенов Sabiha SRS на маркер Портала, как если бы он был целью. В начале их Фазы активации, при выборе стопки SRS, назначенной на маркер Портала, адмирал выбирает миссию SRS, как в Фазе запуска, и перемещает стопку к допустимой цели, находящейся в пределах 10” от любого маркера Портала. Затем они немедленно разрешают миссию SRS.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R347', 'ru', 'FOR VALOUR!', '02d69a7c3919179d572f6969834b12bea782d095e40a0d30079380e7d73fe88b', 'ЗА ОТВАГУ!', 'Эта доктрина может быть приобретена только для флагманского отряда Альянса. Однажды за Ход, Адмирал этого Флота может заявить «За Храбрость!», когда он объявляет, что он намерен осуществить Эффект Храбрости или Специальный Эффект Храбрости с отрядом Альянса. Если этот Эффект Храбрости или Специальный Эффект Храбрости будет успешно осуществлен, Адмирал сразу же берет карту из верхней части своей колоды и добавляет ее в свою руку.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R144', 'ru', 'Forward Deployment', '2830137a82d31a1b42634f9f5aed9a2723c1036aa5959bff1681d7a9181c94d5', 'Передовая развертка', '*Это Свойство применяется только если каждая модель в отряде имеет его в своем профиле отряда - в противном случае оно игнорируется.* Во время развертки этот отряд не может быть оставлен в Резерве. Кроме того, этот отряд может быть развернут где угодно в Игровой зоне, на расстоянии не менее 10" от зоны развертки противника и не в Проксимити вражеской модели.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R336', 'ru', 'Forward Depot', '58938eddc55db4fdc26c22c4d42f678901e400bd1e580aa5c24a5f7605e9164a', 'Передовой Депо', 'Флагман этого Боевого Флота получает свойство Склад (3) и систему Ремонтные Сооружения (1).');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R319', 'ru', 'FORWARD PATROL', '05f52098f98e87d0651843fa7f9d75ddf7b044e0044b5b0f8dd937f8242c6825', 'ПЕРЕДОВОЙ ПАТРУЛЬ', 'В начале своего хода на этапе выполнения специального развертывания в фазе развертывания этот Адмирал может выбрать один из своих отрядов в игровой зоне, который не является Неподвижным. Этот отряд получает свойство Авангард (5”). Адмирал может использовать эту Доктрину только один раз за игру.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R283', 'ru', 'Freya Array', 'e493ba4db0dca7e8f4c4a33025b1db1e69b9170c99118a7b29ba26f1a87888e7', 'Массив Фрейи', 'Эта модель отряда может совершить Специальное действие, чтобы сгенерировать Разрушительный импульс. Только модели в отряде с Массивом Фрейи могут участвовать. Когда это Специальное действие разрешается, каждая вражеская модель в пределах 10" от хотя бы одной участвующей модели получает 1 уровень Беспорядка. Подводные отряды, получающие Беспорядок таким образом, подвергаются правилу Взорвать баки.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R128', 'ru', 'Full Reverse', 'de704bcb2cfe15399dddb9cf13bcafea16936dcaba2d5d9a457efd0541fb372a', 'Полный Реверс', 'Вместо того, чтобы переместить модель нормально, Адмирал может объявить, что модель будет включать Полный Реверс. Когда модель включает Полный Реверс, она получает уровень Беспорядка. Модель с 3 уровнями Беспорядка вместо этого получает очко Урона. На протяжении всего Хода Движения модель перемещается назад вместо вперед, и подвергается следующим Модификаторам: • Ее минимальный рейтинг Скорости снижается до 0. • Ее максимальный рейтинг Скорости уменьшается вдвое (округляя до ближайшего дюйма). • Ее предел Поворота увеличивается на 2 (до максимального значения 4).');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R206', 'ru', 'Fury Generator', 'd7442f9268e6b143f33a592fe2579c2d6dbb0422c7fa522040d90867f0e78ffe', 'Генератор Ярости', 'Это Генератор и дает следующую Преимущество Отряд: каждая модель в этом отряде имеет свойство Экипаж Смельчаков. Кроме того, в начале Хода Действия этого отряда активный Адмирал может объявить, что он освободит Ярость. Если он сделает это, каждая модель в отряде получает свойство Десантные Партии (X) до конца своей текущей Активации, со значением X, равным рейтингу Экипажа модели. На этапе Консолидации текущей Активации каждая модель в отряде, участвовавшая в Десантном действии, получает 1 уровень Беспорядка.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R202', 'ru', 'Fusillade', 'e0ac8b771ba407cce7b154f1dbc39b5ff287587bf890a7b511a4f4230c81d825', 'Салют', 'При выполнении действия Бродсайд адмирал может перебросить результаты Пусто, пока все вносящие вклад модели имеют это Свойство.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R93', 'ru', 'Gaseous', '8ce526addc2d4f65848717127c69c541739bf3b8bbec1458e82c6b938346e097', 'Газообразный', 'Если все орудия, вносящие вклад в действие Атаки, имеют это качество, Атака считается Газообразной. При разрешении Газообразной атаки каждый Успех, набранный в броске действия, наносит 1 Беспорядок вместо 1 Урона. Если это приведет к тому, что Цель получит более 3 уровней Беспорядка, то каждый избыточный пункт Беспорядка наносит 1 Урон вместо этого. Газообразная атака не запускает правило Под огнем. Однако любая модель, получающая Урон в результате Газообразной атаки, автоматически получает токен критического урона опасности, если она еще его не имеет. *Примечание: Беспорядок распространяется как обычно, даже когда наносится Урон. Кроме того, если действует бонус боевого флота Ярости Нефрита (см. ORBAT Империи), цель получает 1 Урон за каждый избыточный пункт Беспорядка, а не 2.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R39', 'ru', 'Generator Ship', '28f33178bc17fe17efba6408be343670313434c79979ad14fee7f5755b879ecf', 'Генераторный корабль', 'Генераторы, установленные на этой модели, предоставляют отряду преимущества всем дружественным моделям в пределах 10” с тем же позиционным признаком.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R334', 'ru', 'Give ‘em Hell', 'f5e23d05591f4b3e49873480436fb06afc4897da36194f482990d920dcedeb07', 'Адский залп', 'Перед объявлением действия «Брэдсайд» отрядом Союза адмирал этой Силы может сбросить карту Victory & Valour из своей руки. Каждый взрывающийся успех в последующем броске Брэдсайда позволяет бросить ещё один кубик действия, как если бы это был бросок действия (см. «Разрешение взрывающихся успехов» на стр. 46 Правил Dystopian Wars). Кроме того, если активный отряд воздушный, он получает свойство каскада Брэдсайда на время действия. В конце действия каждая модель, чьи батареи задействованы в действии, получает уровень беспорядка и не может восстановиться в последующей фазе консолидации.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R78', 'ru', 'Grapple', '46a3336f8f90fb52c99e6531aeff1d149d68857300bdf3bd3b3b3e811a574499', 'Захват', 'Если вражеская наземная или подводная модель начинает свой Шаг перемещения в пределах 2" от дружественной модели с этой системой, эта модель может попытаться захватить вражескую модель. Все дружественные модели с этой системой и находящиеся в пределах 2" от вражеской модели участвуют в захвате. Если суммарный рейтинг Массы всех участвующих моделей превышает рейтинг Массы вражеской модели, захват считается успешным. Адмирал этой модели бросает количество кубиков действия, равное числу участвующих моделей, затем выбирает один кубик и применяет соответствующий результат из таблицы ниже.
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R263', 'ru', 'Great Wall Generator', 'f53e49dcd1f8bf0c7c8b1e7c1961b6922316818646bcbbc54d1873724b3e2306', 'Генератор Великой Стены', 'Это генератор. **СЕТИ ВЕЛИКОЙ СТЕНЫ** Пока модель с Генератором Великой Стены находится на расстоянии 7" от другой дружественной модели, также оснащённой Генератором Великой Стены и имеющей тот же позиционный признак, между двумя моделями генерируется Энергетическая Стена. Она представляет собой прямую линию, проведённую между центральными точками (Centre Points) обеих моделей. Несколько моделей с Генераторами Великой Стены могут быть соединены друг с другом в Сеть Великой Стены. Количество моделей в Сети Великой Стены определяет общую Силу Стены. Максимальная Сила Стены, достижимая одной Сетью Великой Стены, равна наивысшему рейтингу Массы любой модели, подключённой к ней. Одна модель может генерировать несколько Энергетических Стен, при условии, что она находится в пределах 7" от нескольких подходящих моделей.
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R249', 'ru', 'Ground Assault', 'd2f18b3fb40c6c27d27c6f5a14ef47eeaf29612bb2bf41e2bc31dda4df2e50de', 'Наземный штурм', 'Один раз за игру отряд этой модели может использовать Специальное действие, чтобы выполнить наземный штурм одной целевой Территории. Модели в отряде могут участвовать в действии, если они находятся на расстоянии не более 4” от целевой Территории и обладают этим свойством. Когда эта модель участвует в наземном штурме, она вносит X жетонов высадки. Чтобы разрешить действие наземного штурма, все жетоны высадки от участвующих моделей объединяются в одну стопку высадки (так же, как жетоны SRS объединяются в стопку SRS) и помещаются на целевую Территорию. Если на целевой Территории уже есть дружественная стопка высадки, новые жетоны добавляются к ней.
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R67', 'ru', 'Ground Support Mission', '53fc4c3d1fea6faa61cc50c2bcd7520834dfc302399292d7245f25dd4fa90620', 'Наземная поддержка', '**РЕШЕНИЕ НАЗЕМНОЙ ПОДДЕРЖКИ** Выделите стек SRS в стек дружественного отряда высадки на Территории, находящейся на расстоянии не более 25” от модели, из которой он запускается. Он теперь Приближается к этой Территории. Стек SRS, который Приближается к дружественному отряду высадки, выполняет миссию наземной поддержки, используя следующий процесс. Активный адмирал бросает количество кубиков действия, равное числу токенов Talon Autogyro в стеке. Если выпал хотя бы один успех, добавьте дополнительный токен к отряду высадки. Все токены в стеке SRS затем сбрасываются.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R277', 'ru', 'Grounding Hazards', '76e537fcab2e34b8162b30576aacb9e0cd53f136e5101c97caa7dcadc5296734', 'Отмели', 'Опасность осадки может представлять собой песчаный отмель, большой коралловый риф или аналогичное препятствие. Опасность осадки может быть столкнута как обычно, но её масса считается 0 при определении, блокирует ли она или скрывает видимость. Некоторые свойства и системы могут позволять модели проходить сквозь опасности осадки без столкновения.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R96', 'ru', 'Guardian Generator', '0a8822ab7f0e460c36222fd401f5c3ed8691a88732952aa86b44e6efb19ef326', 'Стражевой Генератор', 'Это Стражевой Генератор. В начале каждой Фазы Активации эта модель вносит X кубиков действия в Стражевой Пул адмирала. Если в Стражевом Пуле есть хотя бы один кубик, когда эта модель становится целью действия атаки, адмирал может объявить, что он будет использовать Стражевые Генераторы. Это нельзя сделать против действия атаки, выполненного штурмовым или погружённым оружием, или против чего‑либо, что не является действием атаки (например, свойства Прорывного Сверла или Сбивающего Удара). Когда адмирал использует Стражевые Генераторы, он немедленно тратит из Стражевого Пула некоторое количество кубиков действия; он обязан потратить минимум один, а максимум количество, которое он может потратить, равно показателю Защиты этой модели. Каждый потраченный таким образом кубик удаляется из Стражевого Пула и добавляется в Пул Сопротивления как бонусный кубик. Кроме того, при выполнении этого броска сопротивления адмирал может перебросить любые Пустые результаты.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R203', 'ru', 'Guardian Pool', '53b79d63ea4b2c11d6ccea12328c22c02cc165aebf76387d16952a32e1739d5f', 'Стражевой Пул', 'СТРАЖЕВОЙ ПУЛ
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R322', 'ru', 'Guardian Resonators', '9b016d42a8ca22e47607d37f92ffa360882dbadb7e66338d15aed25ccc0943db', 'Резонаторы Защиты', 'Если адмирал объявит, что он будет использовать Защитные генераторы (см. систему Защитный генератор (X)) для модели, находящейся в пределах 15” от дружественной Цейлонской Защитной Платформы, он может перебросить любые результаты Взрывного Успеха в броске сопротивления, а также любые Пустые результаты.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R36', 'ru', 'Guardian Surge', '3d824372e6815b967741b6d248ee2d45335eb096d865c9af7b22de1374b0f287', 'Импульс Защитника', 'Отряд этой модели может выполнить Импульс Защитника как Специальное действие. Только модели с этой системой могут участвовать в этом действии. Каждая участвующая модель добавляет X кубика действия в пул Защитника адмирала.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R51', 'ru', 'Guardian Wing', '7e0e2302e455793947326270166cdd5d31ccc1a9ac7e6fbb0082f112f758104b', 'Стражевое крыло', 'Когда отряд этой модели становится целью миссии Attack Run, каждая модель в отряде, имеющая это свойство, добавляет X кубиков к любой попытке перехвата. Это позволяет выполнить попытку перехвата даже при отсутствии SRS Stack, поддерживающего отряд.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R102', 'ru', 'Guided', '02bb6d90a3918bab6d435e2dd1bc750e09b9d2ea327f146f8689450b7060dc4c', 'Наводящийся', 'Если Основная цель этого действия атаки также находится под угрозой со стороны дружественного стека SRS, увеличьте каждый из рейтингов огневой мощности этого орудия на X. Рейтинги огневой мощности, у которых нет значения, не увеличиваются.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R359', 'ru', 'GUNNERY SHARPSHOOTERS', '60ad48e6fbfc50040cf44dbb0e48c385797ec5aab7f3ca0efaa624417e2e5e6b', 'АРТИЛЛЕРИЙСКИЕ СНАЙПЕРЫ', 'Можно приобрести только для отряда Commonwealth Flagship. Если отряд в этом флоте выполняет действие атаки, к которому задействовано хотя бы одно орудие с качеством Rail, и основная цель получает минимум 1 повреждение, действующий адмирал может применить специальный эффект доблести. Если эффект успешно применён, основная цель получает 1 критическое повреждение.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R7', 'ru', 'Gyroscopic Rocket Stabilisers', '6158a7a600bbf7a8519131405a8dc6459a2bd9fdada6644402ee486ff996d25a', 'Гиростабилизаторы ракет', 'Один раз за игру, когда адмирал активирует воздушный отряд, он может отбросить из руки карту Победы и Доблести. Это невозможно, если в отряде есть модели с критическим эффектом повреждения «Системный сбой». Если он делает это, отряд получает систему Боковые двигатели (6”) на время её активации.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R220', 'ru', 'Hampered', '107c997ccf23ca98193ea003ef9290b81f0cf1026128a2562cd721579d276fcb', 'Заслон', 'Во время действия атаки Видимость участвующей модели считается затруднённой, если невозможно провести линию от её центральной точки к любой части цели, не проходя хотя бы через один участок тумана. Это правило действует даже если участвующая модель или цель находятся в воздухе. Вражеский адмирал добавляет 2 бонусные кости к броску сопротивления за каждую участвующую модель с затруднённой Видимостью.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R179', 'ru', 'Harriers', '742177a123ef31d2979dcf797009ecbb6794a31049834d8c1684e8c19b01f0fd', 'Продление', 'Во время миссии «Атака» (Attack Run), если этот жетон отбрасывается из атакующего стека SRS в результате попытки перехвата, он всё равно добавляет 1 куб действия в пул действий миссии «Атака». Если последний жетон в стеке отбрасывается, миссия «Атака» не заканчивается немедленно, если хотя бы один из отбрасываемых жетонов обладает этим свойством.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R253', 'ru', 'Hazard', '4e5eec5102cc9ae92b6732bb8670e2dd84879911f03a795edc0fc91215649794', 'Аварийный эффект', 'Если Основная цель этого действия атаки получает как минимум 1 повреждение, активный адмирал бросает X кубиков критического повреждения за каждое задействованное орудие с этим качеством. Если один или несколько кубиков показывают результат «Опасность», Основная цель получает один эффект критического повреждения соответствующего типа. Это качество критического повреждения. Если к атаке применяются несколько разных качеств критического повреждения, адмирал делает отдельный бросок для каждого из них.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R280', 'ru', 'Heavy Prow', '2abca280b4eec281cc79bfe7785152a25cc6312cfd862ca1ae2eb4bbdab3db42', 'Тяжёлый нос', 'При формировании пула действий для таранa, совершаемого этой моделью, добавьте X бонусных кубиков. Кроме того, когда эта модель сталкивается с другой моделью или совершает таран, либо сама является целью таранa и точка контакта находится в её переднем секторе, количество получаемого повреждения уменьшается на X, минимум до 0.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R139', 'ru', 'Heavy Shield Generator', '061168bcc6eca273bcfc97a3e09f3e91bf1176a562ca87a48c77d27dbacb61d7', 'Генератор тяжёлого щита', 'Это генератор и предоставляет следующее преимущество отряда: каждая модель в этом отряде получает +1 модификатор к своему показателю брони, когда она является основной целью действия атаки. Это не действует против атак, выполненных с помощью штурмового или подводного оружия. Также это не действует против свойств «Breaching Drill» или «Raking Strike».');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R125', 'ru', 'Heavy Transport', '9bb1e0268a3a8645722600655f8a3d7fba0a3714c6c70a4cff95f3d0b6be2fde', 'Тяжёлый транспорт', 'Перед тем как выполнить Reserve Roll для отряда с указанной Trait, находящегося на минимальном Model Count и не имеющего черты Capital, его Admiral может объявить, что он Транспортируется на дружественной модели с этим Property. Для Транспортированного отряда Reserve Roll не требуется. Вместо этого отряд размещается так, чтобы каждая модель находилась в пределах 5” от этой модели. Модель с этим Property может быть выбрана для транспортировки только одного отряда за игру.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R338', 'ru', 'HEC Contractors', '256ffde8d10e8acac92a8bd453f4f548c2a5ecdfa599b7715ee62fa8f53cefb7', 'Контрактники HEC', 'Каждая модель в этом Боевой флотилии получает свойство Спуск.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R14', 'ru', 'Hellion Algol Constructs', 'ad21468791bfe0325942d120c0ed415f2be06c3e10352c70bce45247a1b2c732', 'Алголовский бросок', 'Один раз за Раунд, когда отряд из этой Фракции совершает абордаж, адмирал может сбросить карту Победы и Доблести из своей руки перед броском действия. Если он это делает, он может перебросить любые Пустые результаты в броске действия, и цель получает дополнительный уровень Беспорядка после того, как действие будет разрешено.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R107', 'ru', 'Hellion Assaulters', '5c135ef05e06ae8a993a694bd14b0eeb350894661a7e9564dfdd18ade9e8b0c3', 'Штурмовые Хеллионы', 'Когда отряд этой модели выполняет действие абордажа, целью может быть модель наземная или воздушная, и эта модель может участвовать. Если хотя бы одна модель с этим свойством участвует в действии абордажа, любые результаты пустых кубиков могут быть переброшены.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R330', 'ru', 'HER MAJESTY’S FINEST', '70bcc4b11701b97823859442e932eb66dc150b20f16024d8b8df8f1060a184b6', 'ЛУЧШИЕ СИЛЫ ЕЁ ВЕЛИЧЕСТВА', 'Эта доктрина может быть приобретена только для канадского флагманского отряда. Когда модель канадского отряда в этой Силе является основной целью действия атаки, её адмирал может сбросить карту Победы и Доблести из руки до броска действия. Если он делает это, модель получает свойство Аблативная броня (2). Если у модели уже есть свойство Аблативная броня (X), значение X увеличивается на 2.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R362', 'ru', 'HETMAN OF THE SEA', '78d0759a98a768ab15cc4045efe5f85a96d2dd07144d6bdf8ac19236fb010190', 'МОРСКОЙ ГЕТМАН', 'Эта Доктрина может быть приобретена только для украинского флагманского отряда. В начале активации украинского подводного капитального отряда его адмирал может попытаться применить Специальный эффект Доблести. При успехе отряд получает жетон эффекта Доблести. До начала следующей активации этого отряда все украинские подводные отряды в этих Силах в пределах 7" от него становятся иммунными к эффектам «Blow the Tanks». В начале его следующей активации жетон эффекта Доблести сбрасывается.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R87', 'ru', 'High Velocity', '4a0bfc10f6a5f0c4dd3816f5da55a4a62753aa870bf8e47646f5a6259869c010', 'Высокоскоростной', 'В начале шага подсчёта попаданий этого действия атаки каждое задействованное орудие с этим качеством позволяет активному адмиралу преобразовать X тяжёлых счётчиков в броске сопротивления в стандартные счётчики.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R143', 'ru', 'Homing', '3108928bb6e59a96e7f001da588f9cdfd3634f7119ad165620e47ff5db09fe55', 'Самонаведение', 'Если как минимум половина орудий, задействованных в действии атаки, имеет это качество, бросок сопротивления не получает бонусных кубиков за скрытность или затруднённую видимость.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R204', 'ru', 'Hoved Targeting Array', '1bf04a7f1fb3886b2d218ed44b7ac5553d420591906ac206387874dd16078558', 'Главный целевой массив', 'Когда орудие в этом отряде, обладающее качеством «Залп», задействовано в действии атаки, его адмирал может выбрать использовать значение огневой мощи на стандартной дистанции вместо значения на экстремической дистанции, даже если у этого орудия нет значения огневой мощности на экстремической дистанции. Кроме того, если модель в этом отряде участвует в действии атаки на любой дистанции, и все задействованные орудия имеют качество «Залп», её видимость не может быть затруднена или скрыта.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R231', 'ru', 'Hover SRS', 'c5414eea645396f3dc29b8b97a524830527a5e6f8d1817ef6af51a9f5d49e1ab', 'Блокирующий SRS', 'Если этот жетон размещён на подводном отряде, его показатель атаки снижается до 0. Жетон с этим свойством SRS нельзя удалить в результате зенитного залпа (см. систему Зенитный залп (X)). На этапе очистки в конце фазы такие жетоны удаляются из игры без выполнения воздушной разведки.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R110', 'ru', 'Hunter', 'c6705cd1d523206ce9f7d14e1f12ff5fd6e5a5deae450f2df68f4bc47909ca06', 'Охотник', 'Когда этот отряд совершает действие атаки, активный адмирал может перебросить любые Пустые результаты в броске действия, при условии, что каждая участвующая модель обладает этим Свойством и у основной цели есть указанная Черта.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R343', 'ru', 'HUNTERS IN THE CLOUDS', 'a0d37513d320cff0b52662a31120b6f4c0d7ab08c87f855f76748c87604ef0ba', 'ОХОТНИКИ В ОБЛАКАХ', 'Эта доктрина может быть приобретена только для отряда корейского флагмана. При разрешении миссии Attack Run с SRS Stack, включающим хотя бы один токен истребителя Doksuri, этот адмирал может попытаться применить Эффект особой доблести. При успехе каждый Эффект критического повреждения, нанесённый вражеской модели на этапе распределения критических повреждений этой миссии, также наносит одно очко беспорядка.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R284', 'ru', 'Hydrophone Relay', '6207383dcdd2e93e10d21b4f210e71ea24da81f8dcb9e7ddbb903f871dab7fed', 'Гидрофонный Приём', 'Действия атаки, направленные на вражеские модели в пределах 10” от этой модели, никогда не учитывают их Видимость как ограниченную или скрытую.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R241', 'ru', 'Iceberg', 'a3c4d6bce2e7b42e8bb56663bbef82b6984df22ba90683357c72e9d593686c76', 'Айсберг', 'Айсберги — обычное зрелище в некоторых частях океана, но могут появляться и в других местах благодаря странным технологиям Дистопийской Эры. Все участки игрового поля, находящиеся на расстоянии до 1" от айсберга, считаются Коварной водой.
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R361', 'ru', 'ICEMAKERS', '9e8fc35d04dae2ee5e11a234c6093c370d9a4f12b9a25b8f32000c1547d2b85b', 'ТВОРЦЫ ЛЬДА', 'Эта Доктрина может быть приобретена только для русского надводного флагманского отряда. Когда отряд Содружества в этой Силе выполняет специальное действие «Криогенный взрыв», но до броска любых кубиков, его адмирал может объявить, что он перегрузит генераторы. Если он это делает, любые обычные удары в последующем броске «Криогенный взрыв» также считаются успехами на протяжении всего этого действия. В конце действия все модели, задействованные в этом действии, получают 1 беспорядок.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R256', 'ru', 'Impeded', '0b2cd9457b95f91ec368a0b2cd4270ceadf862c4cff3d507f0366f58fa1404eb', 'Затруднение', 'ЗАТРУДНЁННОЕ ПЕРЕМЕЩЕНИЕ. Коварные воды затрудняют перемещение надводных и подводных моделей, а туман — перемещение надводных и воздушных моделей. Во время шага перемещения, если модель вступает в контакт с одной или несколькими особенностями, затрудняющими её перемещение, она получает 1 уровень беспорядка. Это применяется в конце перемещения модели и применяется только один раз, даже если она вступила в контакт с несколькими особенностями.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R332', 'ru', 'IMPROVED DISSIPATION ARRAY', '6775dbcd08af42c4a05897e92a088024148767f8174d3ee86b2f4fe342734854', 'УЛУЧШЕННЫЙ РАССЕИВАЮЩИЙ МАССИВ', 'Эта Доктрина может быть приобретена только для флагманского отряда Pipeworks. Каждый раз, когда отряд Pipeworks с Генератором дуги в этом Силе объявляет, что они Перегружают свои орудия, этот Адмирал может объявить Эффект особого доблести с этим отрядом. При успехе отряд не получает 1 уровень Беспорядка за Перегрузку своих орудий. Вместо этого Адмирал может перенести этот Беспорядок на ближайшую модель, принадлежащую другому отряду (союзнику или противнику) в пределах 10" от активного отряда. Если в пределах 10" нет другой модели, Беспорядок просто отбрасывается.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R364', 'ru', 'IN TREUE FEST', '2ee5d6287475fc7defac33f6666ba8165cdfba4a17ed0a96b7604f493347e206', 'НЕПОКОЛЕБИМАЯ ВЕРНОСТЬ', 'Эта доктрина может быть приобретена только для отряда Баварского флагмана. При активации баварского отряда адмирал этого флота может попытаться наложить специальный эффект Доблести на этот отряд. При успехе отметьте отряд жетоном эффекта Доблести. До следующей активации каждая модель в отряде получает систему Усилённый ход (+2”) и свойство Абалативная броня (2) до начала их следующей активации. Если у модели уже есть эти правила в профиле отряда, значения X суммируются.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R129', 'ru', 'Incendiary Broadsides', 'cab9043b0e94296825da8db7809c9779e73d63f04146b2205bee8469953d2580', 'Поджигающие бакшоты', 'Если боковые батареи этой модели задействованы в действии бакшот, в результате которого цель получает хотя бы 1 повреждение, бросьте количество кубиков критических повреждений, равное рейтингу бакшота этой модели. За каждый результат «Опасность» цель получает один эффект критического повреждения «Опасность». Если несколько моделей с этим свойством задействованы в действии, используйте наивысший рейтинг бакшота среди них, чтобы определить количество бросаемых кубиков.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R297', 'ru', 'Incoming', 'cf892f9fb652b781ac47ea2d945ac03e4f9de3ff0591fda7ffa0add5360af9a2', 'Прибытие', 'Отряд с токеном статуса Прибытие считается Отрядом в прибытии. Он не считается находящимся в Игровой зоне, поэтому не может быть выбран в качестве цели никакими правилами или эффектами.
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R264', 'ru', 'Indirect', '36c3b047a991da35cca00d96619665481ebeb90c9b7964161209074958caef1f', 'Непрямой огонь', 'Это орудие не требует подтверждения видимости к основной цели, чтобы задействоваться в действии атаки. Однако за каждое теневое орудие, задействованное в атаке, когда видимость к основной цели заблокирована, добавляйте 3 бонусные кости к броску сопротивления. Это орудие не может задействоваться в атаке, если основная цель — воздушная модель.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R168', 'ru', 'Indiscriminate', '2c35372a40914732c0828d3ee877eaa0698392c826cd4612fb993bcbab43e0aa', 'Безразборный', 'Если как минимум половина задействованных орудий в действии атаки имеет это качество, бросок сопротивления не получает бонусных костей за затуманенную или ограниченную видимость. Кроме того, после разрешения этого действия бросьте кубик действия за каждый токен эскорта, сопровождающий отряд цели. При любом результате успеха токен немедленно сбрасывается.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R247', 'ru', 'Indomitable', '5c9dcc79c4b017f05d8ad10e931ccc262df16ca22f4678577ab4a7334ee52edf', 'Несгибаемый', 'Эта модель всегда может восстановиться, даже если другое правило запрещает ей это. В фазе конца каждого раунда, перед шагом Завершить цели, этот адмирал может попытаться применить специальный эффект Доблести к этому отряду. При успехе любые повреждённые модели в этом отряде игнорируют правило «Ненадёжный» и считаются боеготовыми до начала следующего раунда.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R372', 'ru', 'Inductorium', '1259d64d7839f06e8e4109a16bf282b9955351c937605bc898e9566b98416910', 'Индуктор', 'Когда адмирал этой силы объявляет действие атаки имперским отрядом, он может попытаться применить специальный эффект доблести этим отрядом после объявления задействованных орудий. При успехе действие атаки получает качество Взрыв (X), где значение X равно количеству задействованных орудий, имеющих качество Arc (X) и/или Voltaic (X). (Орудия, обладающие обоими качествами, считаются один раз.) Каждый бросок действия против вторичной цели получает 1 бонусный кубик за каждый сбой системы, который есть у модели.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R167', 'ru', 'Inspirational', 'e0830f0aeb32186c51de918cba7df03fafda199e9abd07214d4a4b5fbfbeb253', 'Вдохновение', 'Модель в пределах X" от дружественной боеготовой модели с этим свойством может всегда проводить Подбадривание, даже если другое правило запрещает это. Кроме того, каждый раз, когда такая модель проводит Подбадривание, она теряет один дополнительный уровень беспорядка.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R72', 'ru', 'Intensive', 'aefc11e0f88d523dc887fb11f70e56b27fe26236f4ef948510215cffa41d91a5', 'Перегрузка', 'Если хотя бы одно оружие с этим качеством задействовано в действии атаки, активный отряд считается потратившим дополнительное действие. Если у отряда не хватает оставшихся действий, оружие с этим качеством не может задействоваться в действии.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R124', 'ru', 'Interphase Generator', '63bc38a6aabbeea9ac67ca0c26c5cfb2d7293b894668a64eb4e7632e5424a933', 'Межфазный генератор', 'ИНТЕРФАЗИЯ Если по крайней мере половина моделей в отряде имеет Генератор Интерфазы, его Адмирал может объявить, что он вступит в Интерфазу в конце Шага Объединения. Отметьте отряд жетоном специального эффекта. Все модели в отряде находятся в интерфазном режиме до начала следующего шага действия отряда. В последующем раунде адмирал должен активировать любые интерфазные подразделения в своих силах, прежде чем он активирует любые подразделения, которые не являются интерфазными. На интерфазную модель нельзя нацелиться никакими действиями, правилами или эффектами, и она не может получить урон, критический урон или расстройство каким-либо образом. Он не может блокировать видимость (хотя он все равно может скрывать ее как обычно), и любые свойства и системы, которые он может иметь, кроме Межфазного Генератора, игнорируются. Поверхностные модели могут проходить через интерфазную модель, но в этом случае они получают 1 уровень беспорядка. На этапе движения интерфазного отряда рейтинг максимальной скорости каждой модели удваивается, они рассматривают все особенности местности и особенности окружающей среды как открытую воду, они могут проходить сквозь все другие модели и на них не влияют никакие маркеры. Они не могут развернуться, но в конце движения могут свободно вращаться вокруг своей центральной точки и смотреть в любом направлении. Ни одна модель не может завершить свое движение, коснувшись объекта местности, модели или маркера. В конце шага движения жетон особого эффекта удаляется, и каждая другая модель, друг или враг, через которую прошла одна или несколько моделей в активном отряде, получает 1 уровень беспорядка. На последующем этапе Действия Лимит Действия отряда снижается до 1. Кроме того, у любого оружия в отряде, имеющего качество Поток (X), значение X этого качества снижается до 1 до конца Активации. Он не может снова вступить в фазу на этапе консолидации, если он был в интерфазе в начале своей активации.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R281', 'ru', 'Interphase Navigator', '7d045a7ce7bd2fe59632404df391b1fd37f6a620e4b6685926a8ba1cc2cf0f5d', 'Фазовый навигатор', 'В конце активации этого отряда его адмирал может попытаться выполнить турбо‑энкабуляционный прыжок с ним. (См. *Enlightened ORBAT*.)');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R92', 'ru', 'Invalid Target', '7fe3cde9c7640fc2895a5ca38819b205e56736fd3b58cad02ac3a4b2190b2a19', 'Недопустимая цель', 'Это орудие не может задействоваться в действии атаки, если у основной цели есть любой из перечисленных признаков.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R140', 'ru', 'Islands', '55880b70beca26d45631f8585a4b61b344d4dce241e97d5016e3dc4684b68e42', 'Острова', 'Остров — общее название для островов, полуостровов, атоллов и береговых линий. Все участки Игровой зоны, находящиеся на расстоянии 1” от Острова, считаются Коварной водой. Некоторые Свойства могут позволять моделям перемещаться по Островам так, как будто это Открытая вода.
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R342', 'ru', 'Jade Fury', 'eb967ae441f8c8fc95d3eec99ff9ed333cc607f0c70f34cd8aeb32826f1341b0', 'Изумрудный гнев', 'Пока вражеский отряд содержит одну или более моделей с Эффектом критического повреждения «Опасность», он считается Горящим. Когда Горящий отряд активируется, его адмирал должен выполнить групповую проверку экипажа для него. Если проверка провалена, каждая модель в отряде получает 1 уровень Беспорядка. Кроме того, если модель в Горящем отряде получает четвертый уровень Беспорядка по любой причине, эта модель немедленно получает 1 Повреждение. Затем Беспорядок распространяется как обычно.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R116', 'ru', 'Kingslayer', '50464c82e52edc3a1fbd63624d865676c4d543d515ad8c86b16e143d6e4c02bf', 'Бронебой', 'Если у основной цели этой атаки уровень брони 5 и более, то в шаге разрешения результата она считается имеющей уровень брони 4. После того как будет разрешено X успехов, эта особенность перестаёт действовать, и оставшиеся удары перераспределяются соответствующим образом. Если несколько задействованных орудий обладают этой особенностью, их значения X суммируются.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R268', 'ru', 'Landing Party Support', '44f20dcc7e8e71f0dcb3f0dac4ae4f24abaf6a74c022724202ac5f898eb32d79', 'Поддержка десантной группы', 'Если эта модель находится на расстоянии 4” от Территории в конце своего Шага Движения, её адмирал может либо добавить один жетон к существующему дружественному стеку Десантной группы на этой Территории, либо убрать один жетон из вражеского стека Десантной группы на этой Территории.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R115', 'ru', 'Landstrider', '0bf6775059353d2d1a65e89d7cc10c269396996ff6666880dfa8cad110c73fe8', 'Земляной скиталец', 'Эта модель может перемещаться в/через Grounding Hazards и Islands, не сталкиваясь с ними, хотя её перемещение Impeded. Если эта модель завершает перемещение так, что она полностью находится на Island, она Traversing этот Island. Submerged Weapons больше не могут Contribute к Attack actions против неё. Для определения Visibility её рейтинг Mass увеличивается на Mass Island. Кроме того, она не получает Damage в результате Breach Critical Damage Effect в её Consolidation Step. Пока модель Traversing Territory, вражеский Admiral не может размещать токены Landing Party в этой Territory (см. Ground Assault (X) property), и любые уже размещённые токены Landing Party немедленно удаляются из игры.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R57', 'ru', 'Langsam Generator', '8e05c89928d7750a9085259e793c93c51cbefb2e68204a321443b53772bc47de', 'Генератор Лангсама', 'Это Генератор. В качестве особого действия отряд этой модели может Замедлить видимый вражеский отряд. В этом действии могут участвовать только модели с Генератором Лангсама. Выполняя действие, активный Адмирал выбирает вражескую модель в пределах 10” от участвующей модели в качестве основной цели. Затем Адмирал бросает столько кубиков действия, сколько моделей участвует в действии, выбирает один кубик и применяет соответствующий результат из таблицы. 1. ВЗРЫВНОЙ УСПЕХ Основная цель получает 1 эффект критического повреждения. Кроме того, отряд основной цели Замедляется, как описано ниже. 2. СТАНДАРТНЫЙ/ТЯЖЁЛЫЙ УСПЕХ Основная цель получает 1 повреждение. Кроме того, отряд основной цели Замедляется. 3. ПРОМАХ/ТЯЖЁЛЫЙ ПРОМАХ Отряд основной цели Замедляется. 4. ПУСТАЯ ГРАНЬ Каждая участвующая модель получает эффект критического повреждения «Отказ системы». Чтобы показать, что отряд Замедлен, отметьте его жетоном эффекта Генератора. Пока отряд Замедлен, его лимит действий получает модификатор -1, а максимальная скорость снижается до минимальной. В конце следующей активации отряда он перестаёт быть Замедленным, а жетон эффекта Генератора удаляется.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R254', 'ru', 'Lasu (Localised Anomaly Stabilisation Unit)', '5ce5d15781c0e99f7987983195e8f180369d115d88b53a1b5137d0467722cfa5', 'Lasu (Локализованное устройство стабилизации аномалий)', 'Адмирал этой модели никогда не обязан выполнять Бросок Аномалии (см. раздел «Экспериментальные устройства» в Энлайтэнед ORBAT) для подразделения, если все модели этого подразделения находятся в пределах 6” от этой модели. Если эта модель находится в подразделении, для которого выполняется Бросок Аномалии, эта Система не действует. *Обратите внимание, что пропускается только Бросок Аномалии; если правило требует от Адмирала добавить Куб действия в Локализованный пул аномалий, а затем выполнить Бросок Аномалии, куб все равно добавляется в пул.*');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R136', 'ru', 'Lateral Engines', '77b0210b64e51e026e9e6204b5b4ea72a22e04272ee24522cc2f0586ad41081e', 'Боковые двигатели', 'В начале своего Шага Движения, перед перемещением, эта модель может перемещаться до X" без изменения своего направления. Это свободное перемещение и оно не учитывается при Минимальной Скорости модели и не считается против Максимальной Скорости. Направление этого свободного перемещения должно находиться в пределах её Портовой или Бортовой дуги. Всё свободное перемещение должно быть выполнено в одном и том же направлении. Модель с Критическим Повреждением Эффект Блокировки Навигации не может использовать эту Систему, а также модель, выполняющая Передовой Манёвр, не может её использовать. Кроме того, когда эта модель Перекошена, уменьшайте X" вдвое, округляя вверх.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R257', 'ru', 'Launch Range', 'e751ab7a1a33a51b5774258ea9900332584a7feba81a8324f157edb6bb8a7c1f', 'Дальность запуска', 'На этапе миссии «Выбор SRS» при запуске SRS стек, содержащий один или несколько этих токенов, может быть выделен только юниту или маркеру, находящемуся в пределах X” от модели носителя, с которого он запускается, вместо обычных 30”.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R99', 'ru', 'Leaping', 'acffd7ba155f36d3b41432408e36cf3afc714df5da9fb57d7816eb3a0bd8599b', 'Цепной разряд', 'Оружие с этим качеством может способствовать атакам против целей с признаками Elevated, Amphibious или Landstrider, или моделей с признаком Descend, находящихся на поверхности, даже если оно обычно не может это делать. Оружие с этим качеством игнорирует свойство Reinforced Waterline. Кроме того, если каждое способствующее оружие обладает этим качеством, адмирал подразделения может попытаться применить специальный эффект доблести. В случае успеха правило Vulnerable Stern применяется к цели, даже если участвующие модели находятся за пределами задней дуги цели, и даже если другое правило освобождало бы ее от Vulnerable Stern.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R149', 'ru', 'Legionnaire Assault Pods', '1f801d4e77e5da9048e5a4f2cd6faaca50606887be5cd1564dc8e8cda1e04e95', 'Штурмовые капсулы легионера', 'Когда эта модель участвует в абордажной атаке, и целью является наземная модель, через центр которой была пройдена в предыдущем шаге движения, количество кубиков, которое она вносит в бросок действия, удваивается.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R106', 'ru', 'Levant', '33dcedd483e9a2691c17e9e03ec851435f7bcadac0cbb15efd626c1c74fb2e88', 'Левант', 'Воздушные модели с этим свойством не получают преимущества от правила «Нетрадиционная цель», но засчитываются как модели, приносящие очки, пока они не повреждены.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R353', 'ru', 'Levant Surge', 'a38e7d4bfd73d91c67ba133f05ac6555e6b115da76d8cadd5b68968af3ca703b', 'Всплеск на Леванте', 'Когда Адмирал этого Боевого Флота активирует юнит Marine Levante, он может объявить, что юнит выполнит Levant Surge в этом Раунде. Пометьте юнит токеном Особого Эффекта до начала его следующей Активации. Пока у него есть токен, значение его Максимальной Скорости увеличивается на 3” и он не считается обладающим свойством Низкая Высота.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R186', 'ru', 'Light Vessel', 'b01c889002cac13f69c5b2394d8092cdf0d2bd46e23299997975871852df5e30', 'Лёгкое судно', 'Если эта модель становится Искажённой, она немедленно уничтожается и не вызывает Катастрофический Взрыв.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R221', 'ru', 'Lightning Raids', '50007670a826a4c2e8ea87cd45c99c1c4dddd245d8cb231b95989b521681c582', 'Молниеносные набеги', 'Если эта модель успешно сталкивает воздушную модель в свой фазе движения, её юнит может совершить абордаж в следующей фазе действий. Целью должен быть модель, которая была столкнута, и участвовать могут только модели, которые столкнули ту же вражескую модель. Если у Цели этого действия есть свойство Абордажные группы (X), её адмирал не добавляет X кубиков к броску сопротивления.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R126', 'ru', 'Limited', '96dea97e90893ceb11821726aac750f2735ecd31baca733e30d3d5a9d8a6a9b0', 'Ограниченный', 'После выполнения этого действия Атаки каждое оружие с этим Качеством, которое участвовало в действии, истощается. Модель, на которой установлено оружие, получает жетон состояния Истощено. Это оружие не может участвовать в действии Атаки, если оно установлено на модели с состоянием Истощено. В конце следующего Шага Действия модели жетон состояния Истощено снимается.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R250', 'ru', 'Limited Capacitor', '572a60ac4e616a0632d15a75019f9eb3f5a8157d9ebd7ebe3f2cfa0de38e8ace', 'Ограниченный конденсатор', 'Если модель с этим свойством участвует в действии Атаки, все Сильные удары в Броске действий преобразуются в Обычные удары в начале этапа Подсчёта попаданий.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R273', 'ru', 'Limping', 'fc4c08825f71afcdc49f873b667781ac51f3a899e596815852082f749b54db30', 'Ковыляющий', 'Покалеченная модель уменьшает своё значение Максимальной Скорости вдвое, округляя до ближайшего дюйма. Помните, что значение Максимальной Скорости модели не может быть уменьшено ниже её Минимальной Скорости.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R216', 'ru', 'Lingchi Shadow Jumpers', '718da394d5465de0ea72a16f762d90f3c81c8d906c314d45f0e08e846937c390', 'Тени-прыгуны Лингчи', 'Когда подразделение этой модели совершает абордаж, её адмирал может выбрать Цель, находящуюся в пределах 6 дюймов от этой модели. Модели в подразделении, которые имеют это свойство, могут участвовать, если они находятся в пределах 6 дюймов от Цели. Кроме того, если бросок действия для абордажа принес хотя бы один успех, Цель получает дополнительный эффект опасного критического повреждения после того, как действие было выполнено.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R328', 'ru', 'Lionhearted Crew', 'cea7c40561e128c96cc088fbc3bd4c41f6047a908be0b7571a5a62e1ba202f9a', 'Отважная команда', 'При проведении проверки экипажа или групповой проверки экипажа для подразделения Короны этот Адмирал может сбросить карту Победы и Доблести из своей руки вместо того, чтобы брать верхнюю карту своей колоды. Значение сброшенной карты используется для проверки экипажа.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R147', 'ru', 'Logistical Support', '3d6b2b7fe7ca03411c5ebd14449fc2f856f394b95b3f69b5cb992f251730c1a9', 'Логистическая поддержка', 'Если на этапе «Взять карты» фазы готовности хотя бы одна модель с этой Системой находится в Игровой зоне, контролирующий адмирал увеличивает свой лимит карт на руке на 1.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R176', 'ru', 'Lone Wolf', '2c0178ca12506b3b5c8b6c8d4bb43a55f85ae274b3852d1c6b762663bb3e0915', 'Одинокий волк', 'Блок этой модели не может быть родительским блоком для вложения.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R212', 'ru', 'Long-range Coordination', 'e035b0c1c99e5b70453ccb96c1047a1ae0be00883a56e3ec055811ca5c0ab01a', 'Дальнодействующая координация', 'Если по крайней мере одна модель с этой Системой находится в Игровой зоне, управляющий Адмирал может перебросить любые результаты Пусто при выполнении Резервного броска.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R153', 'ru', 'Low Altitude', 'a7f8912362fee3d5803844b1f5eba33fd8c0dcb4f1b43330ef65ad87d1f7e94b', 'Низкая высота', 'Во время Broadside-атаки батареи этого модели по флангам могут вносить вклад, если у цели есть характеристика Surface. Если у цели есть характеристика Airborne, батареи этого модели по флангам могут вносить вклад только если у цели также есть это свойство. Кроме того, пока эта модель готова к бою, она считается моделью для подсчета очков. Однако эта модель не получает преимущества от правила Unconventional Target, когда она является начальной целью действия атаки. *Обратите внимание, что эта модель может быть целью Broadside-атаки, если вносящая вклад модель является Airborne или имеет свойство Broadside Cascade.*');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R223', 'ru', 'Luftlancer Assault', 'd21f09cd442f6f5b7581dc274ab6ac89b588a9ac7f5676f496836589cc084aac', 'Штурмовой Люфтлансер', 'Когда юнит этой модели совершает абордажное действие, целью может быть воздушная модель, и эта модель может участвовать в действии. Кроме того, когда юнит этой модели совершает абордажное действие, её адмирал может выбрать цель, которая находится в пределах 6” от этой модели. Модели в юните, имеющие это свойство, могут участвовать, пока они находятся в пределах 6” от цели.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R83', 'ru', 'Luminiferous Defences', 'd606cc9d4c59b30bc848bbfbc88b0388fa37c36696d0f49e9a9a0da6c4923362', 'Светоносная защита', 'Рейтинг Защиты этой модели увеличивается на X, пока эта Система активна. Рейтинг Защиты юнита с этой Системой отмечен звездочкой (*) в качестве напоминания.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R89', 'ru', 'Magma Cast Generator', '736e567bbfff5114c492d5f37b3d72bb0198f93f7e820c186c0824ff813f3fcb', 'Генератор отливки магмы', 'Это Генератор. ФОРМАЦИИ ЛАВЫ Формация лавы — это особый тип черты местности. Формации лавы подчиняются правилам айсбергов (см. страницу 120 в справочнике Dystopian Wars), но считаются имеющими броню с рейтингом 5 вместо 3. ДЕЙСТВИЯ ПЛАМЕНИ ЛАВЫ Когда подразделение выполняет действие Пламени Лавы, его адмирал использует следующий процесс. 1. НАЗНАЧЕНИЕ УЧАСТВУЮЩИХ МОДЕЛЕЙ Адмирал назначает любое количество моделей в активном подразделении, которые будут участвовать в действии. Модель может участвовать, только если у неё есть генератор магматического излучения. 2. БРОСОК ПРИ ДЕЙСТВИИ ПЛАМЕНИ ЛАВЫ Активный адмирал бросает количество кубиков действий, равное числу участвующих моделей. Если какая-либо из участвующих моделей имеют характеристику «Столица», бросьте 1 дополнительную кость. Затем они выбирают одну кость и сбрасывают остальные. Эта кость определяет рейтинг Магмы и эффекты извержения Магмы, которые используются на следующих шагах. Если все кости выпали пустыми, действие сразу заканчивается. КОСТИ ДЕЙСТВИЯ МАССА МАГМЫ ИЗВЕРЖЕНИЕ МАГМЫ Взрывной удар Масса 1 или Масса 2 1 урон и 1 беспорядок Стандартный/Тяжёлый удар Масса 1 1 урон и 1 беспорядок Стандартный/Тяжёлый контрудар Масса 1 1 беспорядок 3. СОЗДАТЬ ИЛИ РАСШИРИТЬ ФОРМАЦИЮ МАГМЫ Активный адмирал выбирает один из следующих вариантов: СОЗДАТЬ НОВУЮ ФОРМАЦИЮ МАГМЫ Адмирал ставит Формирование Магмы в Игровую Зону. Оно должно иметь рейтинг Массы, соответствующий Массе Магмы рейтинг, и его необходимо разместить так, чтобы он находился в пределах 15" хотя бы от одной Участвующей модели. Магматическая формация не может быть размещена в контакте с другим элементом местности, или в пределах 1" от модели или маркера. РАСШИРЕНИЕ СУЩЕСТВУЮЩЕЙ МАГМАТИЧЕСКОЙ ФОРМАЦИИ Адмирал выбирает существующую Магматическую формацию, которая находится в пределах 15" хотя бы от одной Участвующей модели. Масса этой формации увеличивается на рейтинг Магмы, до максимального значения 4. (*Например, если на шаге 2 был выбран Взрывоопасный удар, Магматическая формация с массой 1 могла быть расширена до массы 3, а формации с массой 2 или 3 — до массы 4.*) Если возможно, участок местности с Магматической формацией следует заменить на большую. подходящий размер. Новый элемент должен быть размещен так, чтобы оригинальная Магматическая формация полностью находилась внутри него. Он не может соприкасаться с другим ландшафтным объектом, моделью или маркером. Если его невозможно разместить с соблюдением этих условий или если подходящего заменяющего элемента нет, просто отметьте формацию жетоном повреждения, чтобы показать её новую массу. 4. РАЗРЕШИТЬ ВЫПЛЕСКИ ЛАВЫ Каждая модель (своего или чужого) в пределах числа дюймов, равного массе вновь созданной или расширенной Магматической формации, становится целью извержения лавы. Каждая цель испытывает эффекты, указанные в колонке извержения лавы, на основе исходного броска Магматического ожога. (*Например, взрывающийся Удар был выбран на Шаге 2, и он использовался для расширения Магматической Формы до Массы 4. Каждая модель в пределах 4” от этой Формы получает 1 Урон и 1 Беспорядок.*)');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R49', 'ru', 'Magma Formations', 'b90bfe87215e17ee2a110d58e89f2ea3607fd1e0238eb3827bc0f19f415b1522', 'Формирования магмы', 'Магматическое образование — это особый тип ландшафтной особенности, который может быть создан с помощью действия «Обжигание магмой», как описано ниже. Магматические образования следуют правилам айсбергов, но рассматриваются как имеющие броню с показателем 5 вместо 3.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R142', 'ru', 'Magma Tower Generator', 'a0a0984a51c6e83187ef86dc74336aa5b3bb5cf94f24596a6a34b8b574aace3c', 'Генератор Магматической Башни', 'Это Генератор. Его эффект не может быть передан другой единице через систему Генераторного Корабля. Единица этой модели может выполнять Специальное Действие «Пламя Магмы», как описано в ORBAT Империи, с небольшим изменением: при совершении броска «Пламя Магмы» бросьте 4 кубика действия вместо 1 и не добавляйте дополнительные кубики за черту «Капитал». Кроме того, если выбран «Взрывной Удар», то его «Извержение Магмы» наносит 2 урона и 1 беспорядок вместо обычных эффектов.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R122', 'ru', 'Magnetic Accelerator Tubes', 'dc053ff9faeae50da6c1ab4e85a73487a605a31806b4b431b578c61bd4922f38', 'Магнитные ускорительные трубки', 'На этапе «Выбор миссии SRS» запуска SRS, в котором участвует эта модель, любые SRS токены, запущенные этой моделью, могут быть назначены на юнит или маркер, находящийся в пределах 40” от этой модели, вместо обычных 30”.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R187', 'ru', 'Magnetic Generator', 'cd33211b6b2a98ecb83b41171cfd522334af7c33a6ad266f3cceca647db45249', 'Магнитный генератор', 'Это Генератор и предоставляет следующее преимущество юнита: если модель в этом юните становится целью действия Атаки с использованием Воздушного, Штурмового или Подводного оружия, или миссии **Атака с пробегом**, все тяжёлые попадания в броске сопротивления превращаются в тяжелые контратаки на начале этапа подсчета попаданий. Кроме того, если модель в этом юните перемещается в близость к маркеру Минного поля, она может получить 1 уровень Расстройства, чтобы попытаться отразить мины. Если она это делает, бросьте куб действия. Если выпадает Пусто, Минное поле срабатывает как обычно. При любом другом результате уберите маркер с игровой зоны, а в конце хода модели поместите его в пределах 3” от движущейся модели, полностью в пределах её переднего сектора. Если это приводит к контакту маркера Минного поля с другой моделью, эта модель немедленно считается вызвавшей его срабатывание.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R276', 'ru', 'Maritime Patrol', '9d25f15a41c43984fc88359e88ecc5a7f4900cb9a5c1585d9ba381ecf713ec82', 'Морской патруль', 'Во время Размещения вражеские модели не могут быть размещены в пределах 10” от этой модели, если они полностью не находятся в собственной зоне Размещения. Кроме того, если все модели в отряде имеют это свойство, отряд может быть размещен на этапе Размещения Десантного Отряда и размещен в любом месте Игровой зоны, которое находится как минимум в 15” от зоны Размещения противника и не вблизи модели противника.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R182', 'ru', 'Mayhem', '7d0f8cb5767ae960fb23c0f76f459632673f8c37445007559435bab766a55261', 'Хаос', 'Если модель получает как минимум 1 единицу урона от этой атаки, она немедленно получает 1 уровень Расстройства. Это заменяет правило «Под огнём», но любые другие правила, которые вызывают у цели получение Расстройства, по-прежнему применяются. *Если эта атака также имеет качество Взрыв, это влияет на Вторичные цели так же, как и на Первичную цель.*');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R340', 'ru', 'MAZOKU’S IRE', '5c35c12b6bc3c6f559d56b3e9dac8e86a82d25ed013a4310edeec72f0e5af93d', 'ГНЕВ МАЗОКУ', 'Эту Доктрину можно приобрести только для флагманского юнита Империи. Один раз за игру, когда противостоящий Адмирал пытается применить Эффект Доблести, этот Адмирал может использовать эту Доктрину вместо попытки Отменить Эффект. Противостоящий Адмирал раскрывает свою Карту Победы и Доблести. Если раскрытая карта имеет значение 8 или меньше, она сбрасывается без применения.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R69', 'ru', 'Mechanical Soul', '94545431854209f344a5c8d4c047ca580642ff8c8b5b466684fa859d0471f45d', 'Механическая Душа', 'Рейтинг экипажа этой модели нельзя изменить. Модели с этим свойством не подвержены эффектам доблести, применяемым их адмиралом. Они подвержены специальным эффектам доблести (применяемым любым адмиралом) как обычно.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R370', 'ru', 'Mercenary Battlefleet', 'e35b05071b42aec9d8bc09dd57d841941cf8dc0fc42a8496867efd8e523b8975', 'Наемный боевой флот', 'Доктрина флота не может быть приобретена для флагманского корабля этого боевого флота. Все подразделения в этом боевом флоте получают характеристику "Отпрыски Ютландии", если у них её ещё нет, а также свойство "Стоический".');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R13', 'ru', 'Micro-Molecular Reinforcement', 'c7fd31804d063e4055af19403cf8ad8170213508aadebd66160f68b89806043e', 'Микромолекулярное усиление', 'Раз в Раунд, когда подводная модель в этой Силе подвергается атаке, к которой Стрелковое оружие участвует, её Адмирал может перебросить любые Пустые результаты в Броске Сопротивления.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R267', 'ru', 'Microwave Control Node', '9346ea0495f0ac004d42663a0e7aec88f469a76194f3e5afb3f3dc83e98f6446', 'Узел управления микроволновой печью', 'Если эта модель получает эффект критического повреждения, её адмирал может провести проверку экипажа для неё. Если проверка пройдена, адмирал назначает дружественную модель Автоматы в пределах 10" от этой модели. Назначенная модель уничтожается, и эта модель не получает эффект критического повреждения. *Примечание: если в пределах 10" нет дружественной модели Автоматы, это свойство не может быть использовано*');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R61', 'ru', 'Mindless Storm', '8ed1aea8d4a3a929238594582e6219f652746423e7f1f5f1a8d0cdd34cbbd4a6', 'Безмысленная буря', 'Всякий раз, когда дружественное подразделение запускает Стеки жетонов Истребителя Коса SRS, его Адмирал может назначить любое количество дружественных моделей с этим свойством для выполнения Безумной Бури. Эти модели не обязаны находиться в одном подразделении и могут быть расположены в любой части Игровой зоны. На этапе Выбора миссий SRS при запуске Стека его можно направить на вражеское подразделение в пределах 10” от модели, выполняющей Безумную Бурю, даже если это подразделение находится вне 30” от модели, производящей запуск. Кроме того, за каждую модель, выполняющую Безумную Бурю, которая находится в пределах 10” от вражеского подразделения, к Стеку добавляется дополнительный жетон Истребителя Коса. Модель может участвовать только в одной Безумной Буре за каждый Фазу запуска. Чтобы отслеживать это, каждая номинированная модель отмечается жетоном Особого Эффекта до конца Фазы Запуска.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R259', 'ru', 'Mine Clearance Mission', '98cebd0bc48a79fda7f3f0bab47b83d0e59d9d008500c725b6ea10de263952be', 'Миссия по разминированию', '**ВЫПОЛНЕНИЕ МИССИИ ПО РАЗМИНИРОВАНИЮ** Стек SRS, назначенный на маркер минного поля, выполняет миссию по разминированию. Активный адмирал бросает количество кубиков действий, равное количеству жетонов SRS в стеке. Если выпадает хотя бы один результат «Взрывной удар», маркер минного поля считается очищенным. Любые дополнительные результаты «Взрывной удар» позволяют адмиралу очистить еще один маркер минного поля в пределах 5 дюймов от исходной цели. Затем все жетоны SRS из стека отправляются в сброс.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R44', 'ru', 'Mine Layer', 'fd30f1ea914a9880763810aafaacea4055ae0fb7b8326cade0a299a4a0663dfa', 'Минный заградитель', 'В качестве действия специального развертывания, юнит этой модели может распределять мины. Когда это происходит, для каждой модели в юните с этим свойством, адмирал юнита размещает до X маркеров минного поля в любом месте игровой зоны. Каждый маркер должен быть размещен как минимум в 10” от зоны развертывания противника. Кроме того, начиная со второго раунда, юнит этой модели может запускать мины как специальное действие, даже если он находится под водой. Его адмирал размещает один маркер минного поля в пределах 5” от модели в юните, которая имеет это свойство. Маркеры минного поля, размещенные с использованием этого свойства, не могут быть размещены ближе, чем в 1” от модели (включая модель со статусным жетоном «Incoming»), элемента местности или другого маркера.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R244', 'ru', 'Mine Sweeper', 'cde94052ad1e6541891e7e3f994e4c07e1c83141076a0f70ec67a53d852b2966', 'Сапёр', 'В качестве Особого Действия, юнит этой модели может выполнять Разминирование. Только модели с этой Системой и находящиеся в пределах 5” от маркера Минного Полевого могут Участвовать. Контролирующий Адмирал бросает X Кубиков Действий для каждой Участвующей модели. За каждый выпавший Взрывной Удар он может выбрать Разминировать маркер Минного Полевого, находящийся в пределах 5” хотя бы одной Участвующей модели.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R165', 'ru', 'Mirage Generator', '76e1bd575958ce7fd9d140be1507efceac5eb5b440a77f2b3df2340676935021', 'Генератор миражей', 'Это Генератор и предоставляет следующую Пользу Юниту: Когда модель в этом юните выбирается в качестве Первичной Цели действия Атаки, и она находится более чем в 10” от любых Участвующих моделей, её Адмирал может объявить, что он будет Поднимать Преломляющие Поля до того, как будет сделан Бросок Действия. Они не могут сделать это, если у этой модели 3 уровня Беспорядка. Если они это сделают, их противник должен перебросить любые Стандартные Удары в Броске Действия. Если при выполнении Броска Действия нет Участвующих моделей в радиусе 30”, они также должны перебросить любые Тяжёлые Удары. После полного разрешения действия Атаки эта модель получает 1 уровень Беспорядка.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R296', 'ru', 'Mirage Projector Array', '208bb995975adfcdf06d1cd9c9e0d40975b277913aa3debe21da5b587558ae0e', 'Массив проекторов миражей', 'Когда дружелюбная модель в пределах 7 дюймов от этой модели выбирается в качестве Первоначальной Цели действия Атаки, её Адмирал может использовать эту систему, чтобы предоставить этой модели систему Генератора Миражей на время действия, даже если у целевой модели есть Критический Эффект Повреждения Системы. Они не могут сделать это, если у этой модели 3 уровня Расстройства. После полного выполнения действия Атаки эта модель получает 1 уровень Расстройства, как указано в правилах Генератора Миражей, вместо целевой модели.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R240', 'ru', 'Mobile', 'cb194e484dc4ef7480b3556dd4972321b6c2f8525fb5465ae6356fe92cd9fbcf', 'Мобильный', 'В начале своего шага перемещения эта модель может выполнить до двух бесплатных поворотов перед движением. Затем она должна двигаться по прямой линии, при этом расстояние измеряется от Центральной точки в её начальной позиции до Центральной точки в её конечной позиции. В конце движения она может выполнить до двух бесплатных поворотов.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R371', 'ru', 'MODULAR CONFIGURATION', '2225dbf12e97aa3434944002f013592ecfe2fb5bafd00ad0387cdc279f4f019f', 'МОДУЛЬНАЯ КОНФИГУРАЦИЯ', '«Подразделение в этой Силе, содержащее хотя бы одну прусскую модель, может в начале своего Шага Действия принять решение Перенастроить своё оружие. Контролирующий адмирал сбрасывает из руки карту Победы и Доблести. Каждая прусская модель в подразделении может обменять одно Лёгкое или Тяжёлое оружие для крепления на другое оружие, которое могло быть выбрано для этого крепления во время Выбора Силы. Генераторное крепление нельзя менять таким образом. До конца текущего Шага Действия подразделение получает модификатор -1 к своей оценке Предела Действий.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R315', 'ru', 'Monument of Fire', 'fbc3eb7308864022ff2510061826e5ae38262794318a520f6cf9e45f029e8eca', 'Памятник Огню', 'На фазе завершения каждого раунда, на этапе завершения целей, этот адмирал может сбросить карту Победы и Доблести из своей руки. Если он это сделает, он получает количество очков Победы, равное Массе самой большой Магматической формации, полностью находящейся на половине игрового поля противника.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R104', 'ru', 'Moon Pool', '0e37eb4e89a80a607b0e178362fb115109090ec900f0b34a2ef58e1311199ceb', 'Лунный бассейн', 'Юнит Империи, находящийся в пределах 10" от хотя бы одной дружественной модели с этим свойством, получает преимущества от поддержки Чита и следующие преимущества: если юнит с Поддержкой Чита использует правило Рейдовых Групп, значение X свойства Посадочных Групп (X) превращается в три раза больше сброшенных жетонов Эскорта, а не вдвое больше. Каждый раз, когда жетон Эскорта сбрасывается у юнита с поддержкой Чита по любой причине, отличной от рейдовых групп, бросайте кубик действия. Если результат показывает стандартный или тяжёлый счётчик, жетон остаётся в игре.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R224', 'ru', 'Mothership', 'b8db610878e93b7beda79f12388eb614d415a186faf055a2af32af0817d894c0', 'Материнский корабль', 'Во время Выбора Сил, Принадлежность, выбранная для подразделения этой модели, не ограничена минимальным количеством моделей — она может включать полное количество моделей. Кроме того, если дружеское подразделение указанного Класса прибывает из Резерва, Адмирал может выбрать его развертывание так, чтобы каждая модель в подразделении находилась в пределах 5" от этой модели, вместо размещения вдоль Края.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R213', 'ru', 'Multiple Batteries', 'a4d9d1cf3450a4a41520ed11fc0df5368222e8bd7789b70c50d9c643803dd9fd', 'Несколько аккумуляторов', 'Это оружие может быть выбрано для участия в действии Атаки до X раз за один актив, вместо того чтобы использоваться только один раз. Каждый раз, когда оно участвует в атаке, Цель должна находиться в другой зоне прицеливания, чем та, которая использовалась ранее в этом активе.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R1', 'ru', 'Multiple Manufacturers', '0dceee5cbe0d56c467152b368af4ee849a8a8e26978c396f58a2e9571384416d', 'Несколько производителей', 'Этот адмирал может приобрести две доктрины боевого флота для флагмана этого боевого флота: одну, которая управляется сверстниками, и одну, которая создана кузницей. Самую дешевую из двух приобретают бесплатно. Это не мешает адмиралу выбрать доктрину «Создано кузницей» для другого флагмана, даже если обычно существует ограничение одна на формирование.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R346', 'ru', 'Naval Maniple', 'df9efc4b0aaeceb11c0bd47e8f45c215e1b02d1997bf7744268d738970df540a', 'Морская манипула', 'Все итальянские патрульные подразделения в этом соединении получают системы «Координированная защита» и «Сквозная очистка палуб».');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R190', 'ru', 'Naval Shield Amplifier', '4915951882960adebe915d4ed0a2cd0069c89e00adf2b0ae1a19ae1ba3877b79', 'Усилитель морского щита', 'При выполнении броска Сопротивления для этой модели, или для дружественной модели с той же Позиционной Чертой в пределах 10” от этой модели, управляющий Адмирал может перебросить Пустые значения.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R211', 'ru', 'Navigation Lock', '8756353324416dca2c141b9f21438592fdd0265d57ffee324a902fe3d20273b0', 'Блокировка навигации', 'Если Начальная Цель этого действия Атаки получает как минимум 1 Урон, активный Адмирал бросает X кубиков Критического Урона для каждого Вкладного оружия с этим Качеством. Если один или несколько кубиков показывают результат Блокировки Навигации, Начальная Цель получает один Эффект Критического Урона этого типа. Это Качество Критического Урона. Если к Атаке применяются несколько разных Качеств Критического Урона, Адмирал делает отдельный бросок для каждого из них.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R258', 'ru', 'Null-Clone Generator', '8762e6b6ec13d462c3aad9e3a815daf34d824153203da1d6d707bbfeea72b1dd', 'Генератор нулевых клонов', 'Это Генератор. В качестве Особого Действия юнит этой модели может Взаимодействовать с Нулевыми Клон-Генераторами. Участвовать могут только модели с этой Системой. Адмирал юнита добавляет Кость Действия в Локализованный Аномальный Пул, затем выполняет Бросок Аномалии для юнита. (См. раздел «Экспериментальные Устройства» в ORBAT Просвещённых.) За каждый выпавший Пустой результат каждая Участвующая модель получает 1 уровень Беспорядка. Если у Участвующей модели уже есть 3 уровня Беспорядка, она вместо этого получает 1 Повреждение. Затем каждая вражеская модель в пределах 5” от Участвующей модели получает Эффект Критического Повреждения Отказа Системы, если у неё его ещё нет. За каждый вызванный таким образом Отказ Системы, активный Адмирал может удалить Систему. Отказ от участвующей модели или другой дружелюбной модели в пределах 10 дюймов от участвующей модели.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R262', 'ru', 'Obscured', 'cdd76183d8a36d7610e1dfbc51c3831613ea54bcc2b2b2463113c2864a90c6b4', 'Затемнённый', '**СКРЫТЫЕ ЦЕЛИ** Как только будет установлено, что цель Видима, противоположный адмирал проверяет, скрыта ли Видимость активной модели. Видимость считается скрытой, если невозможно провести прямую линию от Центрной точки активной модели до любой части модели цели, не проходя через хотя бы одну другую модель или элемент местности. Эти другие модели или элементы местности скрывают Видимость активной модели. Когда модель участвует в атакующем действии и её Видимость скрыта, противоположный адмирал добавляет бонусные кубики к своему пулу сопротивления, равные Массе самой большой модели или элемента местности, скрывающих видимость, увеличивая эффективность атаки менее эффективно. Противоположный адмирал делает это для каждой участвующей модели, чья видимость затемнена.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R56', 'ru', 'Offensive', '73a0f38b71d409af3036728bdb649ce8ea7aa05890054bd14abecdc8a0b87bd0', 'Оскорбительный', 'Этот токен SRS не учитывается при выполнении миссии по разминированию с его стеком.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R237', 'ru', 'Optimal Target', '534b7d4f238c9997b7f6ffd08e0cc3a984442cd8e17c3e1418c780be627f2064', 'Оптимальная цель', 'Если у Изначальной Цели есть все перечисленные Черты, увеличьте каждое значение Огневой Мощи этого оружия на X. Значения Огневой Мощи, которые не имеют числа, не увеличиваются.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R178', 'ru', 'Orichalcite Construction', '832091a0948f84af7a3ce6bd0b8148c8b9305ef335318e356417d6fc1a7a9945', 'Строительство из орихалка', 'Если у этой модели есть более одного экземпляра одного и того же эффекта критического повреждения, при разрешении текущих штрафов учитывается только один экземпляр этого эффекта. Это не влияет на количество эффектов критического повреждения, необходимых для вызова катастрофического взрыва. Например, если у модели с массой 3 и этой характеристикой есть два или более эффекта разрушения, она получает только 1 повреждение на своем шаге консолидации — но если она получит еще один эффект критического повреждения, произойдет катастрофический взрыв.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R19', 'ru', 'Overcharged Capacitors', '008ed4843435498fd5307246acf4a97f0a2f770765796b3323bd98b3091c376f', 'Перезаряженные конденсаторы', 'Раз в Раунд, когда юнит из этой Силы совершает действие Атаки, этот Адмирал может объявить, что он Превышает Протоколы Безопасности непосредственно перед броском действий, и выполнить Проверку Группового Экипажа для всех участвующих моделей. Если Проверка пройдена, этот Адмирал может перебросить Стандартные и Тяжелые счетчики в броске действий. Если Проверка провалена, действие Атаки завершается немедленно, и каждая участвующая модель получает 2 критических эффекта Системной Поломки и 1 урон.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R62', 'ru', 'Overthrusters', '92455a4be1ea1dff9d5609f78e7b93c724d5b9d0a39c4a2af366375ce12c1a18', 'Сверхтормоза', 'Когда эта модель использует свою систему Усиленной Пропульсии (+X’’), отметьте её жетоном Особого Эффекта, чтобы показать, что она находится на Полной Тяге. Пока модель находится на Полной Тяге, она получает преимущества от эффекта правила Нетрадиционная Цель, даже если она не является Воздушной единицей. Если модель на Полной Тяге получает Критический Урон из-за Блокировки Навигации или Сбой Системы, она немедленно перестаёт находиться на Полной Тяге, и жетон Особого Эффекта снимается. В противном случае жетон снимается на этапе Уборки в Конечной Фазе.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R369', 'ru', 'Pack Hunters', 'dee3d6ebe87279b34c1df6fe960b0d923544c53795d969523e0afc84b97426aa', 'Стачные охотники', 'При выполнении действия Атаки или Действия захвата на борт, подразделение «Потомки Ютландии» в этой Силе может перебросить количество Пустых или Контр-значков в Ролле действия, равное количеству токенов Негативного эффекта на Первичной цели.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R341', 'ru', 'PADDLEWHEEL SURGE', '362e0a7f5b17f2ad5cd628de35d6be20d49d69dcde2f397208cb46a97a27f7b8', 'РЫВОК ГРЕБНЫХ КОЛЁС', 'Эта Доктрина может быть куплена только для китайского наземного флагманского юнита. Когда этот Адмирал активирует китайский наземный юнит с характеристикой Pivot, они могут попытаться выполнить Особый Эффект Доблести. Если попытка удачна, каждая модель в юните получает систему Усиленной Пропульсии (X) до конца их Шага Движения, где X равен Массе этой модели.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R323', 'ru', 'PAX BRITANNICA!', 'd8b1ae1cd8f9f6b37b6891ceb166f0e954b1a6355945439b204f539406f91a51', 'PAX BRITANNICA!', 'Можно приобрести только для флагманского корабля Короны. Один раз за раунд, перед тем как этот адмирал совершит атаку с флагманским кораблём Короны, он может попытаться применить специальный эффект доблести с этим кораблём. Если эффект успешно применён, каждая стандартная фишка в броске действия превращается в стандартный удар.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R309', 'ru', 'Peer in Residence', 'f5d8eddd71af2df4ba736a5a8bbdbfcbe721d0b50be4c1b639f42b354e4bb424', 'Стажёр в резиденции', 'Каждый раз, когда Адмирал этого Боевого Флота активирует юнит Багровой Лиги в своем Структурном Составе, он может снять один Эффект Критического Повреждения Системы с одной Боеготовой модели в этом юните.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R172', 'ru', 'Physeter Construct', '2b2754d9bf717e32314e4733e8a2e92b0e89eb4df4de31ba72afa952e6195466', 'Физетер Констракт', 'Ни одна единица не может иметь более 3 токенов Конструкта Физетера, выделенных для неё. Адмирал может Выпускать токены Конструкта Физетера из единицы, удаляя их из игры, чтобы использовать Защиту Физетера или провести Саботаж Физетера, следующим образом. **ЗАЩИТА ФИЗЕТЕРА** Адмирал может Выпустить один или несколько токенов Конструкта Физетера, выделенных для единицы, если модель в этой единице является целью любого из следующих действий: • Боевое захватывание; • Атака, к которой хотя бы одно штурмовое или погруженное оружие вносит вклад; • Миссия Атакующего Рейда, выполненная стеком СРС, содержащим хотя бы один токен с свойством Подводная СРС; • Саботаж Физетера (см. ниже). 2 бонусные кости добавляются к Сопротивлению Бросайте кости за каждый жетон Физетер Конструкт, который был Выпущен. **САБОТАЖ ФИЗЕТЕРА** Юнит с одним или несколькими жетонами Физетер Конструкт может совершить Специальное Действие, чтобы осуществить Саботаж Физетера. Адмирал юнита выбирает цель среди вражеских моделей на поверхности или под водой в пределах 20 дюймов от как минимум одной модели в активном юните, затем выпускает один или несколько жетонов Физетер Конструкт, выделенных активному юниту. Затем они делают Бросок Действия, а противоположный адмирал делает Бросок Сопротивления: Пул Действия Пул Сопротивления Порог Успеха Каждый жетон Физетер Конструкт, который был Выпущен, добавляет 5 кубиков Действия в пул. Пул Сопротивления начинается с числа кубиков, равного рейтингу Защиты цели. Добавьте 1 Бонус Погибайте за каждый жетон Эскорта, сопровождающий целевую единицу. Если цель сопровождается одним или несколькими жетонами SRS с свойством Подводный SRS, каждый из них добавляет количество дополнительных кубиков, равное его рейтингу поддержки. Рейтинг брони цели. Если у цели есть Генератор тяжёлого щита, модификатор +1 к её рейтингу брони игнорируется. За каждую Успешную попытку в броске действия действующий Адмирал бросает кубик критического урона. Каждый полученный эффект критического урона накладывается на цель.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R17', 'ru', 'Physeter Echo Communicators', 'bfd74c240730341e84bc4f9d4a8c35092f3a98c235042da615fda2bf8798774b', 'Коммуникаторы Физетер Эхо', 'В конце шага Развертывания этот Адмирал получает 6 жетонов Конструкта Физетера. Затем они могут распределить эти жетоны между подразделениями в своей Силе, при этом максимум 3 жетона на одно подразделение.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R38', 'ru', 'Physeter Support Hub', '1d2599dc346f277d9d304094f2ee67fddc62ba5e2ac5f125e7ae13f51e30e900', 'Центр поддержки Physeter', 'В конце шага Развертывания Адмирал этой модели получает 4 жетона Физетер Конструкта (см. Просвещенный ОРБАТ). Затем они могут распределить эти жетоны между подразделениями в своей Силе, причём максимум по 3 жетона на подразделение. После того как Адмирал этой модели использует Физетер Защиту или Физетер Саботаж с подразделением этой модели, или с другим подразделением, которое находится в пределах 7” хотя бы от одной дружественной модели с этим свойством, они кидают Кость Действия за каждый жетон Физетер Конструкта, который был Выпущен. Если они получают Тяжёлый удар или Взрывной удар, они возвращают жетон в подразделение, из которого он был Выпущен.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R71', 'ru', 'Piercing', '1fe5104db15fc6543b6abfe69159f739129c50edf0cb62f2a685e34155b9e54f', 'Бронебойный', 'На этапе «Разрешение Результата» этого действия Атаки, начальная цель получает -1 к своей оценке Брони (до минимума 1) в течение этапа «Разрешение Результата». После того как будет достигнуто X успехов, это Качество перестает действовать, и оставшиеся Удары перераспределяются соответствующим образом. Если несколько Содействующих оружий имеют это Качество, их значения X суммируются.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R170', 'ru', 'Pivot', 'd0464606c8b8b36ea18d4204564506f9e09263f923ebc5c04988e77ff9779c65', 'Поворот', 'Эта модель может вращаться, когда это происходит во время её шага движения.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R335', 'ru', 'Plant the Flag', '4215a3f649e689e15f67c1efcf1b096206c1d17d61075bfcec51ccddcab46518', 'Высадить флаг', 'На этапе «Завершение целей» фазы конца этот адмирал Флотилии получает 4 очка победы за каждую Территорию, где у него больше жетонов Десанта, чем у противника, при условии, что эта Территория находится в пределах 10” от дружественного юнита с характеристиками Союз и Платформа.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R248', 'ru', 'Platform', 'd428bcdefd24dc20c1888828b07d38b96cb88315a59b838a881f2e5a06adaaed', 'Платформа', 'В начале Фазы Развертывания адмирал этой модели должен разделить своё подразделение на одну или несколько Групп Платформ (каждая из которых содержит как минимум одну модель). Каждая Группа Платформ считается отдельным подразделением на протяжении всей игры, включая цели Развертывания. Подразделение этой модели не может быть Развернуто в Резерв. После Развертывания оно не может двигаться и его нельзя перемещать до конца игры, и оно также никогда не может Отступить. Когда эта модель становится целью действия Атаки, правило Уязвительная Корма не применяется. Если эта модель Уничтожена или Покинута, замените её маркером Обломка, размещённым над Центром модели. Если маркер должен быть размещён в контакте с Местностью Функция, модель или другой Маркер не размещаются. *Обратите внимание, что Платформы могут быть заброшены! Это обозначает уход экипажа и установку взрывных устройств, чтобы предотвратить попадание важного объекта в руки врага.*');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R287', 'ru', 'Platform Transport', '5be88e8f61d5095fea186616cc1387d548439e4feeb16fcb2894cc93b569f8f5', 'Платформенный транспорт', 'Один раз за игру, во время шага Развертывания резервов фазы Готовности, адмирал этой модели может развернуть одну модель Платформы Союза с рейтингом Массы 3 или ниже в пределах 2” от этой единицы. Это бесплатная модель, и её не нужно выбирать во время Выбора Сил.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R66', 'ru', 'Portal Accelerator Array', 'c31a6db401a861ac96fe72346a613df06934921998ac947b64d94600032e4d3e', 'Массив ускорителей портала', 'Эта модель имеет дополнительные опции при Создании Портала или Закрытии Портала, как описано в разделе Технология Порталов в ORBAT Султаната. **УСКОРЕННОЕ ТВОРЕНИЕ** Если назначенный Ткач оснащён Массивом Ускорителя Порталов, Адмирал может либо разместить до 2 маркеров Портала (согласно стандартным правилам), либо разместить один маркер Портала на расстоянии до 20” от Ткача, плюс 10” за каждый дополнительный Модуль Манипуляции Порталом в подразделении. (Этим дополнительным моделям не обязательно иметь Массив Ускорителя Порталов.) **ИМПЛОДИРОВАНИЕ ПОРТАЛА** Если хотя бы одна модель Модуля Манипуляции Порталом в подразделении оснащена Массивом Ускорения Порталов, её Адмирал может выбрать Имплодиировать Портал вместо Закрытие его обычным способом. Если они это делают, они назначают модель в активном отряде, которая имеет Портальный Ускорительный Массив, и выбирают Портальный маркер в пределах 20” от этой модели. Затем они делают Проверку Экипажа для назначенной модели. Если проверка неудачна, каждая модель (своего или вражеского) в пределах 3” от выбранного маркера немедленно получает 1 уровень Беспорядка, после чего маркер удаляется из игры. Если проверка успешна, назначенная модель получает 1, 2 или 3 уровня Беспорядка, выбранные активным Адмиралом. Если это приведет к превышению 3 уровней Беспорядка у модели, считается, что она получает только столько уровней, чтобы достичь 3. Затем каждая модель (своего или вражеского) в пределах 3” от выбранного Портального маркера получает Урон, равный количество Беспорядка, полученного выбранной моделью, и получает 1 Беспорядок. Наконец, Маркер убирается из игры.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R127', 'ru', 'Portal Generator', '09cdb8bbc5abea0433a6002db852efbf3e5b84a59afeaf1c4d031ff91e8df59d', 'Генератор порталов', 'Это Генератор, единица этой модели может Плетить и Перемещать Порталы. Маркер Портала рассматривается как имеющий Массу 3 и может Блокировать или Затемнять Видимость так же, как и модель. **ОГРАНИЧЕНИЯ ПО ПОРТАЛАМ** Максимальное количество маркеров Портала, разрешённых на Игровой Площадке, равно Лимиту Порталов и зависит от Масштаба Состязания в игре. Если оба Адмирала могут создавать Порталы, этот лимит применяется к каждому из них отдельно. Малое Состязание: 4 Среднее Состязание: 6 Большое Состязание: 8 **СТОЛКНОВЕНИЕ С МАРКЕРАМИ ПОРТАЛА** Воздушные и Подводные модели могут Проходить Сквозь маркер Портала. Наземные модели могут Передвигаться через маркеры Портала. В конце Передвижения Наземной модели она получает 1 уровень Беспорядок за каждый маркер Портала, через который он прошёл. Затем для каждого из этих маркеров Портала адмирал модели бросает количество кубиков действий, равное показателю Массы модели. Если один или несколько кубиков показывают тяжёлый удар или взрывной удар, Портал разваливается, и маркер удаляется с игровой зоны. Если движение модели заканчивается прикасанием к маркеру Портала, маркер автоматически удаляется (бросок кубика не требуется). *Обратите внимание, что модель получает Беспорядок за маркер, даже если она не прошла полностью через него.* **УПРАВЛЕНИЕ ПОРТАЛАМИ** Модель с системой Генератора Порталов является Манипулятором Порталов. Её можно использовать для Создания Портала в фазе Запуска, а также для Сдвига и/или Закрытия Портала, как Особое действие во время активации. Модель с эффектом критического повреждения из-за системного сбоя не считается манипулятором порталов. **ТКАНИЕ ПОРТАЛА** Во время фазы запуска контролирующий адмирал может назначить юнит, содержащий как минимум одну модель-манипулятор порталов, так, как если бы это был юнит носителя, для ткачества портала. Если юнит-носитель содержит модель-манипулятор порталов, его можно выбрать дважды в фазе запуска — один раз для ткания портала и один раз для разрешения запуска SRS. Когда юнит ткет портал, его адмирал назначает модель-манипулятор порталов в юните ткачем, после чего размещает маркер портала в пределах 10” от этой модели. Это расстояние увеличивается на 10” за каждый дополнительный портал. Модель манипулятора в юните, не включая Ткача. Маркер Портала не может быть размещён вблизи модели Поверхности, элемента Рельефа или другого Маркера, а также не может перекрывать модель в Воздухе или Под водой. Юнит не может Ткать Портал, если в зоне игры уже есть маркеры Портала, количество которых достигает Лимита Порталов Адмирала. **УСОВЕРШЕНСТВОВАННОЕ ТКАНИЕ** Если назначенный Ткач оснащён Массой Ускорителя Порталов, Адмирал может либо разместить до 2 маркеров Портала (согласно стандартным правилам), либо разместить один маркер Портала на расстоянии до 20” от Ткача, плюс 10” за каждого дополнительного Манипулятора Портала в юните. (Эти дополнительные модели не обязательно должны быть оснащены Ускорителем Порталов) Массивы.) **СМЕЩЕНИЕ ПОРТАЛА** Юнит, содержащий как минимум одну модель Манипулятора Портала, может Смещать Портал как Специальное Действие во время своей Активации. Только модели Манипулятора Портала могут Участвовать в этом Действии. Когда это происходит, активный Адмирал выбирает маркер Портала в любой точке Игровой Площадки и перемещает его в пределах 10” от его текущего положения. Обратите внимание, что, в отличие от Процесса Ткачества Портала, это расстояние не увеличивается за счет наличия более чем одной модели Манипулятора Портала в юните. Маркер Портала нельзя перемещать в пределах Близости к модели Поверхности, объекту Местности или другому Маркеру, а также накладывать на Летающую или Подводную модель. **ЗАКРЫТИЕ ПОРТАЛА** Юнит, содержащий... По крайней мере одна модель Манипулятора Порталов может Закрыть Портал как Особое Действие во время своей Активации. Только модели Манипулятора Порталов могут Учавствовать в этом Действии. Когда это происходит, активный Адмирал выбирает маркер Портала где угодно на Игровой зоне. Каждая модель (своя или вражеская) в пределах 3” от Маркера немедленно получает 1 уровень Расстройства, затем Маркер убирается из игры. **ВЗРЫВ ПОРТАЛА** Если по крайней мере одна модель Манипулятора Порталов в отряде оснащена Массивом Ускорения Портала, её Адмирал может выбрать Взорвать Портал вместо его обычного Закрытия. Если он это делает, он назначает модель в активном отряде, которая имеет Массив Ускорителя Портала, и выбирает маркер Портала в 20” этого образца. Затем они проводят Проверку Экипажа для названного образца. Если проверка неудачна, каждая модель (своя или вражеская) в пределах 3” от выбранного Маркера немедленно получает 1 уровень Расстройства, после чего Маркер удаляется с игрового поля. Если проверка успешна, названная модель получает 1, 2 или 3 уровня Расстройства, выбираемые активным Адмиралом. Если это приведет к превышению 3 уровней Расстройства у модели, считается, что она получила только столько уровней, сколько необходимо, чтобы достигнуть 3. Затем каждая модель (своя или вражеская) в пределах 3” от выбранного Маркера Портала получает Урон, равный количеству Расстройства, полученного названной моделью, и получает 1 уровень Расстройства. Наконец, Маркер удаляется с игрового поля. **ИСПОЛЬЗОВАНИЕ ПОРТАЛОВ** Многие Султанаты единицы могут Развёртываться, Атаковать и Покидать через Порталы. **РАЗВЁРТЫВАНИЕ ЧЕРЕЗ ПОРТАЛ** Когда подразделение Султаната на поверхности прибывает из Резерва, оно может Развёртываться через Портал, если ни одна модель в подразделении не имеет показатель Массы больше 3. Адмирал подразделения выбирает Портал на Игровой площадке, затем Развёртывает подразделение так, чтобы каждая модель находилась в пределах 5” от выбранного Маркера, и выбранный Маркер находился в задней дуге каждой модели. Обратите внимание, что подразделение не получает жетон статуса «В пути». Модель, которая Развёртывается с маркера Портала, не может быть размещена вблизи Террейн-объекта или модели из другого подразделения. Атака через Портал. Когда подразделение Султаната на поверхности совершает действие Атаки, его Адмирал может объявить, что они будут Атаковать через маркер Портала. Если они делают это, Адмирал должен назначить один маркер Портала в Игровой зоне как Входной Портал, а другой маркер Портала в Игровой зоне как Выходной Портал. Модели в отряде могут участвовать в Действии только если Входной Портал находится в пределах 7” и виден им. Оружие может вносить вклад в Действие только если Входной Портал находится в одной из его зон прицеливания. Дальность Атаки определяется измерением расстояния между Начальной целью и Выходным Порталом. При определении видимости любые линии проводятся от центра Выходного Портала, а не от атакующей модели. Портал всегда считается Препятствием для каждого Видимость участвующей модели. В результате противоборствующий адмирал всегда добавляет как минимум 3 бонусных кубика к своему броску Сопротивления за каждую участвующую модель. **УХОД ЧЕРЕЗ ПОРТАЛ** В начале шага движения единицы поверхности Султаната её адмирал может объявить, что единица уйдет через портал. Если в ходе этого шага модель из этой единицы с рейтингом массы 3 или меньше входит в контакт с маркером портала, и точка контакта находится в переднем секторе модели, модель удаляется из игры и откладывается в сторону. Коллизия не разрешается. В конце шага движения любые модели в единице, которые все еще находятся на игровой площади, признаются оставленными. Остальная часть единицы возвращается. в Адмиральский резерв и может вернуться в Игровую зону на фазе готовности последующего раунда.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R74', 'ru', 'Portal Strike', '8ed8f1ad648f4a65cb2ab52ef2cd0458ebc75e8e46ed4af5ee0fab204ded6b2a', 'Атака портала', 'Когда этот Адмирал выполняет миссию Атаки против враждебного юнита, находящегося в пределах 10” от маркера Портала, он может объявить Удар Портала в начале Фазы Отступления, сбросив карту Победы и Доблести из своей руки. Если он это делает, любые жетоны SRS с этим свойством SRS не удаляются из игры. Вместо этого активный Адмирал выбирает другой враждебный юнит, находящийся в пределах 10” от другого маркера Портала, и распределяет эти жетоны SRS на этот юнит, либо формируя новый стек SRS, либо добавляя их в дружественный стек, который уже выделен для него. Отметьте стек SRS жетоном Негативного Эффекта до Фазы Очистки Этапа Завершения, чтобы показать, что он не может совершить другой Портал. Пропустите этот раунд. Это жетон запретного удара.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R261', 'ru', 'Power Transfer Generator', '9778a01c037f6cbdf328594cd5771e5fb97e74423d90f8b9af4f87deb8af11c3', 'Генератор передачи энергии', 'Это Генератор. При выполнении Броска Действия или Броска Сопротивления для другой модели Просвещённого в пределах 4" от этой модели, её Адмирал может добавить 3 Бонусные Кости в Базу. Если он это делает, эта модель получает 1 уровень Беспорядка. Если у неё уже есть 3 уровня Беспорядка, она получает 1 Повреждение вместо этого.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R113', 'ru', 'Powered', 'faf91c9cef0a05c96e1dd383c42015041f1c23055e78585ee554591d6766c766', 'Энергией', 'Это оружие не может способствовать действию Атаки, если модель, на которой оно установлено, имеет критический эффект повреждения «Отказ системы».');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R199', 'ru', 'Precise', 'de2202d329e4ddd66a0c696789aafeb0c22f65fbf6fab713c4ec260142cc4fff', 'Точный', 'Если Изначальная Цель этого действия Атаки получает как минимум 1 Очко Урона, активный Адмирал выбирает Эффект Критического Урона. После того как Эффект был объявлен противоположному Адмиралу, активный Адмирал бросает X Критических Кубиков Урона за каждое Вкладное оружие с этим Качеством. Если хотя бы один кубик соответствует объявленному Эффекту, один экземпляр этого Эффекта немедленно применяется к Цели.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R311', 'ru', 'Press the Advantage', 'c2b95bb95da5de529953fc228f8644eb373201cab0b48b11836576775cf012c2', 'Использовать преимущество', 'До тех пор, пока у Адмирала этого Боевого флота больше Очков Победы, чем у его противника, действует следующее правило: При выполнении броска действия для подразделения EITC или Индийского Раджа этот Адмирал может перебросить любые результаты Пусто.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R252', 'ru', 'Priority Signals', 'e6010ef9c50aef95f6e77003611029735c55ebb6a46b69c594d959b3e086aada', 'Сигналы приоритета', 'При попытке активировать Эффект Доблести, но до того, как противостоящий Адмирал объявит, будет ли он пытаться его Отменить, Адмирал этой модели может объявить, что он использует Приоритетные Сигналы, при условии, что у него есть хотя бы одна модель с этой Системой в Игровой Зоне. Если он так делает, Значение карты Доблести рассматривается как увеличенное на 2, до максимума 12. Адмирал может использовать Приоритетные Сигналы только один раз за Раунд, даже если у него несколько моделей с этой Системой.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R117', 'ru', 'Protective Fire', '249fb074f6056109ac87fed87eaa753bbee4dd2c176634c8562594ce051af150', 'Огонь прикрытия', 'Когда модель с этим оружием является целью миссии «Атака», или действия «Атака», в котором хотя бы одно оружие с характеристикой «Залп» участвует, она может выполнить «Огневое прикрытие». Добавьте количество бонусных кубиков к броску сопротивления, равное сумме значений X всех оружий на модели с этой характеристикой.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R79', 'ru', 'Proximity', '47acb37eebd9438c9218b3b00f8f23f12b24eb7f951729172f508049ef184a57', 'Близость', 'Всякий раз, когда два модели с чертой Поверхность находятся на расстоянии менее 2 дюймов друг от друга, обе модели считаются находящимися в близости друг к другу. Модель с чертой Воздушная или Подводная никогда не считается находящейся в близости другой модели, и наоборот. Аналогично, всякий раз, когда модель Поверхности или Подводная находится на расстоянии менее 2 дюймов от элемента местности или маркера, модель и элемент местности или маркер считаются находящимися в близости друг к другу. Близость всегда взаимна; если Модель A находится в близости к Модели B, Модель B также находится в близости к Модели A.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R63', 'ru', 'Rail', '18d90ea1fbca9c0f7705ca7e8553e4ba4010e3ddf0130ec4b5f35ae7976ada36', 'Рельсовый', 'На этапе «Разрешение взрывающихся ударов» в рамках действия броска для этой атаки первые X взрывающихся ударов вызывают бросок двух дополнительных кубиков действия, вместо одного. Если у нескольких участвующих оружий есть это свойство, их значения X суммируются. *Например, у оружий, участвующих в атаке, в сумме есть Rail (4). В изначальном броске действия выпало 3 взрывающихся удара, поэтому бросают 6 дополнительных кубиков (по два за каждый взрывающийся удар), что приносит ещё 2 взрывающихся удара. Затем они бросают 3 дополнительных кубика: два за первый взрывающийся удар и только один за второй, так как Rail больше не применяется.*');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R108', 'ru', 'Raking Strike', '77d39e2e6e9daa808a5cbfd5fcd616350a5a3b555dffbf47593260fccd8ae181', 'Косающий удар', 'Один раз за Активацию, в качестве Специального Действия, подразделение этой модели может выполнить Раздра́гивающий Удар, даже если оно Подводное. Только модели с этим Свойством могут Учавствовать. Это Действие направлено на вражескую модель, через которую хотя бы одна участвующая модель Прошла во время своего Шага Передвижения. Цель должна иметь такой же Позиционный Признак или быть Наземной моделью. Контролирующий Адмирал делает Бросок Действия. Броска Сопротивления нет. Пул Действий X Кубики Действия для каждой участвующей модели. Порог Успеха — Рейтинг Брони Цели. Если у Цели есть Тяжёлый Генератор Щита, модификатор +1 к её Рейтингу Брони игнорируется. За каждый успех, полученный в Броске Действия, Целевая Модель получает 1 Повреждение. Кроме того, если Бросок Действия принес хотя бы один Успех, Модель-Цель получает 1 уровень Расстройства.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R109', 'ru', 'Rally', '3c9b08871b85084d5edb65f01bf7722f0e101892bc3c5b0f84396193469e754e', 'Ралли', '4. ШАГ КОНСОЛИДАЦИИ На этом этапе каждая модель в подразделении собирается, если она может это сделать. ЭФФЕКТЫ КРИТИЧЕСКИХ ПОВРЕЖДЕНИЙ Некоторые эффекты критических повреждений разрешаются на этапе консолидации активации подразделения. Эти эффекты разрешаются после того, как подразделение имело возможность собраться. СОБИРАНИЕ МОДЕЛИ Модель может собраться, если она соответствует следующим критериям: • Модель не нарушает когерентность. • Модель не находится в радиусе 3 от элемента местности. • Модель не находится в радиусе действия модели из другого подразделения (дружелюбного или вражеского). Когда модель собирается, она теряет один уровень нарушений, плюс дополнительный уровень нарушений за каждое действие, которое её подразделение не использовало на предыдущем этапе. Шаг действия. Например, у подразделения рейтинг Лимита Действия равен 3. В течение своего Шага действия оно совершает два Атаки действия, но не совершает третье Действие. На Шаге консолидации каждая модель, которая может Воспрянуть, теряет 2 уровня Беспорядка. ХАОС! Модель не может Воспрянуть, если в её подразделении есть одна или несколько Калечных моделей.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R191', 'ru', 'Ram', '995da0acfc40d82e36318cf8608da71178be43a48adf0790b9d8a73ceafd60eb', 'Баран', 'Если движущаяся модель сталкивается с вражеской моделью после того, как прошла как минимум 3 дюйма, и точка контакта между двумя моделями находится в передней дуге движущейся модели, активный адмирал может объявить таран. Модель может пытаться выполнить таран только во время собственного шага движения. РАЗРЕШЕНИЕ ТАРАНА Когда адмирал объявляет таран, он выполняет шаги, указанные ниже. В этом процессе движущаяся модель называется Моделью-Таранщиком, а другая модель — Целью. 1. Проверка Экипажа Адмирал выполняет проверку экипажа для Модели-Таранщика. Если проверка неудачна, таран не осуществляется, и разрешается обычное столкновение. Если проверка успешна, переходят к следующему шагу. 2. Вызов беспорядка у обеих моделей Таранщиком и Цель получает 1 уровень Беспорядка. 3. Совершить Бросок Действия Активный Адмирал совершает Бросок Действия. Броска Сопротивления нет. Шаг Определения Исходов данного Броска Действия выполняется дважды — один раз для модели Цели и один раз для модели Таранного удара. Бассейн Действий Добавьте количество Кубиков Действия, равное рейтингу Корпуса модели Таранного удара. Добавьте 1 Бонусный Кубик за каждый полный дюйм, который модель прошла перед Таранным ударом. Это не может добавить более 5 Бонусных Кубиков. Порог Успеха (модель Цели) Рейтинг Массы модели Цели. Порог Успеха (модель Таранного удара) Рейтинг Массы модели Таранного удара. 4. Наносить Урон Каждая модель получает 1 Урон за каждый Успех, полученный на шаге Определения Исходов. 5. Отойти целевая модель перемещается на 1” напрямую назад. Если она сталкивается с другой моделью или элементом местности, она прекращает движение, но столкновение не разрешается. **ПОСЛЕДСТВИЯ ТАРАНА** Если модель пытается совершить Таран в ходе Шага движения, она не может участвовать в каких-либо действиях на последующем Шаге действий — даже если Проверка экипажа проваливается и Таран разрешается как Столкновение.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R2', 'ru', 'Reclamator Repair Bay', '4a54bebfc90bc8d0d4eeaf496016bea844e2e1f3c4aa62f7f5c6435629a780e0', 'Ремонтная зона Рекламатора', 'Этот Адмирал может снять 1 Эффект Критического Повреждения с модели из этой Силы с свойством Десантные Отряды (X) всякий раз, когда он завершает свою Активацию вблизи вражеской модели, которая имеет как минимум 1 повреждение.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R285', 'ru', 'Reclamator Swarm', 'a00ae5926111e2e24c98451c371999ad8f7269bde1fb38c6a5807947f98fbdc5', 'Рекламаторный рой', 'Если вражеская модель поверхности завершает своё Активирование в пределах 4” от этой модели, Адмирал этой модели бросает Кость Действия. Если выпадает Взрывающийся Удар, вражеская модель получает Критический Эффект Повреждения Структуры. Если вражеская модель завершает своё Активирование в пределах 4” от более чем одной модели с этой Свойством, бросьте Кость Действия для каждой и примените Повреждение Структуры за каждый выпавший Взрывающийся Удар.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R209', 'ru', 'Recombination Nexus', '761aa1fbed20da8fa050906689377a7be92bd07d473fbc88f47946464569dca2', 'Узел рекомбинации', 'Блок этой модели может Усилить Реальность как Особое Действие. Только модели с этой Системой могут Участвовать в этом Действии. Каждая участвующая модель убирает X кубиков действий из Локального Аномального Резерва своего Адмирала. (См. *Просвещённый ORBAT*.)');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R41', 'ru', 'Reinforced Decking', '9f4d775df91f87f38a4426b7ff65e44e5368be9903d8a5b879ea9f09590cbb90', 'Укреплённое настил', 'Когда эта модель становится целью действия «Атака», выполненного с использованием Воздушного оружия, любые Тяжёлые удары в броске действий преобразуются в Стандартные удары в начале шага Подсчёта попаданий.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R73', 'ru', 'Reinforced Waterline', '57b781658608416e3eb3d01aeb578fcc3e4234cc8727552c70284729221ae7f5', 'Укреплённая водная линия', 'Когда эта модель становится целью действия «Атака», выполненного с использованием Подводного оружия, любые Тяжёлые удары в броске действия преобразуются в Обычные удары в начале этапа «Подсчёт попаданий».');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R58', 'ru', 'Repair Facilities', 'b3c473bc943639d9b76a72446e2da4489e94f0e13ddf800ec7c84bf4413fa000', 'Ремонтные предприятия', 'Модели в пределах 4 дюймов хотя бы от одной дружественной модели с этой Системой находятся в зоне ремонта, при условии, что они имеют одинаковую позиционную черту. Модель с этой Системой всегда считается находящейся в зоне ремонта. При совершении броска ремонта для модели, находящейся в зоне ремонта, добавьте X бонусных кубиков. Если бросок позволяет юниту удалить больше эффектов критического повреждения, чем ему было назначено, с модели также убирается 1 повреждение.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R236', 'ru', 'Repulsion Generator', 'c6c579c745f16d049b7a8befd186d0a3a29b741a7f9a17d39885a90355a955fe', 'Генератор отталкивания', 'Это Генератор и предоставляет следующее преимущество для юнита: При перемещении модели в этом юните её Адмирал может объявить, что они будут использовать Поля Отталкивания. В течение перемещения модели она рассматривает все Ландшафтные Объекты как Открытую Воду и может Проходить через поверхностные модели. Она учитывает контакт с Минным полем или Обломком только если завершает своё перемещение в контакте с маркером. В конце перемещения модель получает 1 уровень Беспорядка. Если она завершает перемещение в контакте с Ландшафтным Объектом, она немедленно Разрушается.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R157', 'ru', 'Reserve', '98975fe1fb29942b1c295ac519dae8c280ed4b34f249ed0db0efdee6e60fd96a', 'Резерв', 'Во время Развёртывания Адмиралы могут отложить часть своих отрядов, поместив их в Резерв вместо размещения в игровой зоне. На этапе Развёртывания резервов Адмиралы могут по очереди пытаться развернуть эти отряды. БРОСОК РЕЗЕРВА В свой ход Адмирал может выбрать отряд в своём Резерве, а затем выполнить бросок Резерва, бросив количество кубиков действия, равное номеру текущего раунда. Если в броске нет тяжёлых или взрывных успехов, отряд задерживается и не прибывает в этом раунде. Отметьте его жетоном статуса «Активирован», чтобы показать, что его нельзя выбрать повторно. В противном случае Адмирал развёртывает отряд и отмечает его жетоном статуса «Прибытие». Отряд должен быть развёрнут в построении: все его модели должны касаться края игровой зоны и находиться не ближе 5” от вражеской модели. Модели должны быть развёрнуты в своей зоне развёртывания, если только в броске не выпал хотя бы 1 взрывной успех. В таком случае их можно развернуть вдоль любого края, если ни одна модель не находится в зоне развёртывания противника.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R27', 'ru', 'Resilient', '5609714cd3ac2ab6333cbc6ce2cae6a01e70967a2a78501811432870b986f2ab', 'Устойчивый', 'Когда эта модель становится целью действия «Атака» указанного качества, все «Тяжелые удары» в броске действия преобразуются в «Стандартные удары» в начале шага подсчета попаданий.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R183', 'ru', 'Resupply', '6e45024da58d1aab024432409b56cea079b2c807b598df946f80dc8c01301f14', 'Пополнение запасов', 'Во время фазы запуска контролирующий адмирал может назначить юнит этой модели, как если бы это был юнит транспортного корабля, для выполнения поставки. Когда юнит выполняет поставку, каждая модель запускает X жетонов поставки. Каждый жетон должен быть назначен дружественному юниту в пределах 10” от модели, которая его запускает. В начале активации юнита каждый назначенный ему жетон поставки позволяет одной модели в юните принять припасы. Модель, принимающая припасы, убирает 1 уровень расстройства, даже если она в противном случае не смогла бы пройти сбор. Кроме того, если у модели есть жетон состояния «Истощён», её адмирал может выбрать проверку экипажа для неё. Если проверка пройдена, жетон состояния «Истощён» удаляется. Все Марки перезарядки, выделенные подразделению, затем отбрасываются, независимо от того, были ли они использованы.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R355', 'ru', 'REVOLUTIONARY ZEAL', 'b90ae1e56aaddcdda7201aa3966c67fd9c4a06ce7ee6f20e093a166852008167', 'РЕВОЛЮЦИОННЫЙ ПЫЛ', 'Эта Доктрина может быть приобретена только для флагманского юнита SUSA. При проведении проверки экипажа группы, чтобы определить, могут ли поврежденные модели с характеристикой SUSA участвовать в действии, адмирал этой силы может сбросить карту Победы и Доблести из своей руки, чтобы автоматически пройти проверку.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R326', 'ru', 'RFC ELITE', '9ee0b9c539cb056ce6966e24b5c88239c41890529602f9815b2916a51d32fe45', 'ЭЛИТА RFC', 'Может быть приобретен только для единицы «Флагманский авианосец Короны». Один раз за раунд, до того как этот адмирал решит выполнить миссию «Атака» с подразделением Defiance SRS, он может попытаться осуществить Эффект Особой Доблести. Если эффект успешно реализован, эскадрилья SRS может выполнить «Погружение сокола»; если они это делают, никакая попытка перехвата не может быть совершена против этой атаки. Если Эффект Особой Доблести не удается, адмирал может продолжить выполнение миссии «Атака» (и любые связанные попытки перехвата) как обычно. В качестве альтернативы, адмирал может выбрать не выполнять миссию «Атака» в это время и продолжить активацию своей единицы.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R354', 'ru', 'ROLLING BROADSIDE', '9ee2ab13560e1b02141e222fdc5736fbe23995bf97ed086acd5e8f9ef8702e09', 'КРУЖАЩИЙ БОРТОВОЙ ЗАЛП', 'Эта Доктрина может быть приобретена только для французского флагманского подразделения. Когда адмирал этой силы объявляет действие «Бортовой огонь» с французским надводным подразделением, он может сбросить карту «Победа и Доблесть», чтобы сделать это «Кружащимся бортовым огнем». В течение этого действия модели в подразделении могут делать вклад в действие «Бортовой огонь» по цели в пределах 6 дюймов вместо обычных 4 дюймов.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R327', 'ru', 'SABRE RATTLE', 'a3f9c17f71428adf3ec1c605c0c77fd9d1fb598d43ef8b7e8c4b075f1fa5c1b5', 'БРЯЦАНИЕ САБЛЯМИ', 'Эту доктрину можно приобрести только для флагманского подразделения Индийской Раши. Каждое подразделение Индийской Раши в составе сил этого Адмирала получает свойство Авангард (5”). Когда подразделение Индийской Раши в составе сил этого Адмирала совершает авангардное перемещение, каждая его модель должна завершить движение ближе к зоне развертывания противника, чем была в начале.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R60', 'ru', 'Sealed Vessels', '01d8e1da18e4e9ce90aaba2af1011541f522183069bf8067de390068dee76af7', 'Запечатанные сосуды', 'Подводное подразделение не может выполнять никакие действия, если не указано специально, что они могут выполняться подводным подразделением. Например, Погружённое');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R103', 'ru', 'Self Destruct', '0cc490bf26ff9f4f8efea9cc343e7a201a4d6ed6700d3b55413dca13ef7ab6f5', 'Самоуничтожение', 'Когда эта модель Получена повреждениями или Уничтожена, её Адмирал может немедленно попытаться использовать Специальный эффект Доблести с этой моделью. Если попытка успешна, модель немедленно подвергается Катастрофическому Взрыву, принимая её рейтинг Массы как на X выше и нанося X урона каждой модели в пределах досягаемости вместо 1.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R16', 'ru', 'Self-Refining Behaviour Protocols', 'e59cbd7a87f4e1b89f8a5c1a61b54e3b1e3cf5dd844d25f9a1c38748cdecd0d8', 'Протоколы самосовершенствующегося поведения', 'Все единицы автоматов в этой силе получают свойство Стоик.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R11', 'ru', 'Self-Repairing Hull', '1570875d8ca5e0ee9e75139ba93e2bbef68a26740e1a9d3f65ec616806223957', 'Самовосстанавливающийся корпус', 'Всякий раз, когда флагманская модель этой силы становится целью действия Атака, этот Адмирал может провести Проверку Экипажа для модели в начале этапа Нанесения Урона. Если Проверка пройдена, юнит получает на 1 меньше Урона, минимум 1.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R219', 'ru', 'Sentinel Generator', 'a5321dcad86f2af55f23586fd17fd5b33f492fff1657a54adab171c9d00fc7d6', 'Генератор Сентинел', 'Это Генератор и предоставляет следующую Пользу Юниту: Перед тем как будет выполнен бросок действий для действия Атаки или миссии Атаки на маршруте, в которой модель из этого юнита является целью, её Адмирал может объявить, что он активирует её Сентинельный Генератор. Они не могут сделать это, если модель является целью Атаки с использованием Штурмового, Бомбового или Подводного оружия. Если Сентинельный Генератор модели активирован, она не может получать пользу от других Генераторов в ходе этого действия Атаки или миссии Атаки на маршруте. Однако непосредственно перед шагом Разрешения Взрывных Ударов при броске действий её Адмирал может удалить 2 кубика действий по своему выбору из броска.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R307', 'ru', 'Serpens Caput', 'e3f440c7e38523345b2b8ed082cdf958a742b417601e365ebf5ae0f13bd1ba06', 'Голова Змеи', 'Один раз за раунд, при объявлении Содействующих Оружий для действия Атаки, выполняемого юнитом Воздушного Патруля в этом Формировании, когда Начальная Цель находится в передней дуге всех участвующих моделей, Адмирал этого Боевого Флота может раскрыть и сбросить карту Победы и Доблести из своей руки. Если он это делает, он добавляет Бонусные Кости в пул действий в количестве, равном значению карты.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R70', 'ru', 'Shallow Draught', '7547c63249c8c695393d11ec5d8c28d7d4c5f953aa7494978862bba7f8da89b6', 'Мелководный', 'Движение этой модели не затрудняется коварной водой, и она может проводить сбор даже если находится вблизи элемента местности.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R145', 'ru', 'Shockwave Generator', 'c2fde6f75622320679c31f796a67e9dbb75c7402bb06fa9eeff9e2e56099f37d', 'Генератор ударной волны', 'Это Генератор. В качестве Специального Действия, юнит этой модели может излучать Сейсмический Взрыв. Только модели с этой Системой могут участвовать. Активный Адмирал выбирает вражескую модель в пределах 10” от всех участвующих моделей. Затем они делают Ролл Волны Удара, используя количество Кубиков Действий, равное суммарному показателю Массы всех участвующих моделей. За каждую Выпавшую Сильную Атаку или Взрывающуюся Атаку, вражеская модель получает 1 уровень Беспорядка.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R135', 'ru', 'Shredded Defences', '63a7b9644ce110d6ddc47609047150f295841aa8d134da42674c0f3ea6d58839', 'Разрушенные обороны', 'Если начальная цель этого действия Атаки получает хотя бы 1 единицу урона, активный адмирал бросает X кубиков критического урона за каждое содействующее оружие с этим качеством. Если один или несколько кубиков показывают результат «Разрушенные защиты», начальная цель получает один эффект критического урона этого типа. Это качество критического урона. Если к атаке применяются несколько разных качеств критического урона, адмирал делает отдельный бросок для каждого из них.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R84', 'ru', 'Shroud Generator', 'dc465e6f0bc20ce46acdc9e92af5e6dbc5e7b05d492734fdf6b817dd277708dc', 'Генератор савана', 'Это Генератор и предоставляет следующее преимущество юнита: когда модель в этом юните является Исходной Целью действия Атаки, Видимость каждой Участвующей модели всегда считается Ограниченной (как описано в Разделе «Особенности Окружения» на странице 117 Правил Dystopian Wars), если только она не находится в пределах 5” от Исходной Цели и не имеет того же Позиционного Признака. Кроме того, когда эта модель Затеняет Видимость другой модели во время действия Атаки, Видимость этой модели будет одновременно Ограниченной и Затенённой.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R294', 'ru', 'Silent Hunters', 'cfe68eac095480a1c8ef463cb42e54e05e49a49beb60a5453c6d559da2fd17e3', 'Тихие охотники', 'Подводная модель не может быть выбрана в качестве Первоначальной цели для действия Атаки, если правило специально не указывает иначе.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R31', 'ru', 'Singular', '43be63011d2e63201daf0df5fb696921c7c32bd48ce9600accbc4368b157d8e5', 'Единственное число', 'Все оружие, учащееся в этом действии, должно иметь точно такое же название, как указано в их записи о сетке оружия.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R230', 'ru', 'Skimmer', 'f5fafb6985f9abb8fa3e9dec7949518cd3b6139235764303311d5e81ab98744c', 'Скиммер', 'Эта модель рассматривает все особенности местности как открытую воду и может проходить через модели поверхности. Скиммер не вызывает маркеры минных полей и никогда не получает критические повреждения в результате контакта с маркером обломков. Подводное оружие не может участвовать в действиях атаки против моделей скиммеров. Штурмовое оружие может учитывать модели скиммеров как модели поверхности или воздушные, по выбору действующего адмирала. При объявлении действия посадки на борт или залпового действия с моделью скиммера или против неё, скиммер может учитываться как поверхность или воздушная, по выбору действующего адмирала.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R222', 'ru', 'Sky Commandos', '1f7b284f8d5fa0910c3e1108167cc0e221dee4717be03fbf4e48329eeef4fb4e', 'Небесные коммандос', 'Когда подразделение этой модели выполняет посадку на борт, целью может быть наземная или воздушная модель, и эта модель может участвовать.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R133', 'ru', 'Sky Strike', '7978a31bf420a469e12e49df70cd87b89c1c5eb7627ebdb9d8f66086d4185e53', 'Небесный удар', 'Если начальной целью этой атаки является воздушно-десантная модель, увеличьте каждое значение огневой мощи этого оружия на X. Значения огневой мощи, которые не имеют значения, не увеличиваются. Кроме того, если все оружия, участвующие в этой атаке, обладают этим качеством, правило о необычной цели не применяется.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R324', 'ru', 'SNOWBIRD AIR PATROL', '23a9b2821285da7b0cf2126b258de56d17a160a267774d4c3aa9d337b51f85db', 'ВОЗДУШНЫЙ ПАТРУЛЬ «СНЕЖНАЯ ПТИЦА»', 'Эта доктрина может быть приобретена только для канадского флагманского подразделения. Каждый раз, когда канадское наземное подразделение в этом формировании является целью миссии атакующего пролета, попытка перехвата выполняется с 2 бонусными кубиками — и может быть выполнена даже если нет СРС-стека, поддерживающего подразделение.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R97', 'ru', 'Soar', 'dd56addaad81572bbfb9cc86ca2429104e5eed60116f9efbe38bfe6b18881b75', 'Парить', 'Эта модель может перемещаться на все типы местности или через них, не сталкиваясь с ними, и может по-прежнему собираться, находясь рядом с ними. Эта модель может проходить сквозь другие модели, и они могут проходить сквозь неё.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R192', 'ru', 'Solex', 'b6bcb944e5afcedb5cc60fea4f157912663869cde07222f7b37c7fefdd8eb4b6', 'Солекс', 'После шага «Решить Взрывные Удары» действия Атаки, каждое Стрелковое оружие с этим качеством позволяет активному Адмиралу преобразовать до X стандартных фишек в броске действия в стандартные удары.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R141', 'ru', 'Solex Generator', 'd9420ab580461277c34d9f0cc6fafad666f4b9581044ff692e6d9e3eda7be483', 'Генератор Солекс', 'Это Генератор и предоставляет следующую пользу для подразделения: Когда это подразделение выполняет действие Атаки, его Адмирал может объявить Тепловое Возбуждение. В течение действия все Содействующие орудия, имеющие качество Солекс (X), используют вместо него улучшенное качество Солекс (X), сохраняя то же значение X. После разрешения действия активный Адмирал выбирает одну модель в подразделении с Генератором Солекс. Эта модель получает 1 уровень Беспорядка. Если у нее уже есть 3 уровня Беспорядка, она получает 1 Повреждение вместо этого. Если польза для подразделения была предоставлена моделью из другого подразделения — например, моделью с системой Корабль-генератор — тогда эта модель получает Беспорядок.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R305', 'ru', 'Special Rules', 'ae3c4af69b5d95e07e33d8b7aaa888159afedf2ecc43eb1a422ed668b8f20ef4', 'Специальные правила', 'Доктрину флота нельзя приобрести для флагманского корабля этого боевого флота. Все единицы в этом боевом флоте получают черту "Багровой Лиги". Это наёмный боевой флот и может использоваться как специализированный боевой флот в составе силы, созданной с использованием другого ОРБАТа. Когда он используется таким образом, все его единицы всё равно должны быть выбраны из этого ОРБАТа.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R333', 'ru', 'Special Rules', 'fd5aa651cf364a0f93cc54ddbd90746b1bddbb887ca5d822eabaa8e4277fdd76', 'Специальные правила', 'Доктрину флота нельзя приобрести для флагманского корабля этого боевого флота. Это наемный боевой флот. Если этот боевой флот используется как наемный в составе силы, которая берется из внеюнитного ORBAT, тогда любые торговые или платформенные единицы, приобретенные как часть этого боевого флота, должны быть из этого ORBAT.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R33', 'ru', 'Specialist', '84c8867c419a2d46e3a3b5874cf0453c770b1e59488400b73a39862961d66413', 'Специалист', 'При выборе миссии для SRS-строя, который содержит один или несколько жетонов этого типа, его адмирал должен выбрать из конкретного списка миссий, как показано в его ORBAT. Это может включать специальные миссии, которые обычно недоступны для жетонов SRS. Для подробностей смотрите раздел Короткодействующие эскадроны в ORBAT этого жетона.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R349', 'ru', 'Splendor Dei', '3ee24f9347ca087094a8149d541ad39331299914929a5359ef69aed460fd7ab2', 'Величие Бога', 'Флагман этого Боевого флота получает систему Корабля-генератора.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R34', 'ru', 'SRS', 'd6e44b38122bf20b178af586a78d9a9cde936ad9d9acd9d9b457d109e1b123dd', 'SRS', 'На этапе запуска модели кораблей этого подразделения могут запускать токены SRS того(их) типа(ов), которые указаны. (Существуют специальные миссии, которые могут выполнять некоторые конкретные SRS, смотрите в самом низу для их обозначения) *Если адмирал желает, чтобы одна или несколько повреждённых моделей приняли участие в запуске SRS, они должны выполнить проверку экипажа группы, так же как если бы хотели, чтобы повреждённые модели участвовали в действии.* **ЗАПУСК КОРОТКОЙ ДИСТАНЦИОННОЙ ЭСКАДРЫ** В свой ход адмирал выбирает одно из своих подразделений на игровом поле, которое содержит одну или несколько моделей кораблей, и выполняет запуск SRS, используя приведённый ниже процесс. Подразделение не может быть выбрано, если оно уже выполнило запуск SRS в этом раунде. 1. ОБЪЯВИТЬ УЧАСТВУЮЩИЕ МОДЕЛИ Адмирал объявляет, какие модели в активном подразделении будут участвовать в запуске. Модель не может участвовать, если у нее нет свойства, позволяющего запускать токены SRS, или если ей иначе запрещено запускать токены SRS. 2. СОЗДАНИЕ SRS СТОПКИ(СТОПОК) Каждая участвующая модель запускает определенное количество токенов SRS, как указано в свойстве, позволяющем это делать. Адмирал располагает эти запущенные токены SRS в любое количество SRS Стопок. Нет верхнего или нижнего предела количества токенов в стопке или количества отдельных Стопок, запущенных с одного Перевозчика. 3. ВЫБОР МИССИИ SRS Для каждой SRS Стопки Адмирал выбирает одну из следующих Миссии SRS: **МИССИЯ АТАКИ** Назначьте SRS Стек на вражескую единицу в пределах 30” от модели, с которой он запускается. Теперь он представляет угрозу этой единице. Когда эта миссия будет выполнена, она может нанести критический урон моделям во вражеской единице или уничтожить эскорт этой единицы. **МИССИЯ АВИАПОДДЕРЖКИ** Назначьте SRS Стек на дружественную единицу в пределах 30” от модели, с которой он запускается. Теперь он поддерживает эту единицу. Эта миссия не выполняется в начале Активизации. Вместо этого Стек может обеспечить авиационную поддержку, если дружественная единица становится целью действия Атаки или Действия абордажа, и может сделать попытку перехвата, если дружественная единица подвергнут цели миссии Авианалета. **МИССИЯ РАЗМИНИРОВАНИЯ** Назначьте Стеки SRS на маркер минного поля в пределах 30” от модели, с которой он запускается. Теперь он начинает Проходить этот маркер минного поля. Когда эта миссия будет выполнена, она потенциально очистит маркер минного поля и другие маркеры минного поля в радиусе 5” от него. **ОТСУТСТВУЮЩИЕ ЦЕЛИ** Если Цель Стеков SRS удаляется из игры (например, если последняя модель в дружественном подразделении, которое он поддерживает, Отступает или Разрушена), Стек откладывается в сторону (например, на край Игровой зоны). В Конечной фазе все Короткодействующие Эскадрильи, которые были отложены, будут выполнять Воздушную Разведку. Вот SRS который может выполнять определённые миссии. **Автожиры Talon** МИССИЯ НАШЕСТВИЯ TALON, МИССИЯ ПОДДЕРЖКИ НА ЗЕМЛЕ, МИССИЯ ПОБРОСКА ПОСТАВОК');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R21', 'ru', 'Stereoscopic Distance Calculators', '1145d6d6210fbd6f3e4072a19a86298d97d3f7fc008089f57251dd9fb9a48583', 'Стереоскопические калькуляторы расстояния', 'Раз в Раунд, когда подразделение из этой Силы выполняет действие Атаки и есть как минимум одно Вкладное оружие с качеством «Залп», Адмирал может сбросить карту Победы и Доблести из своей руки перед броском на Действие. Если он это сделает, он может перебросить любые Пустые результаты в броске на Действие.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R114', 'ru', 'Stockpile', 'd48bbdab33b928f2450f10884414b37a915e65b51a84d8cb67377e840ccc56bc', 'Запас', 'Когда модель с жетоном статуса «Истощён» начинает свою Активацию в пределах 4” от этой модели, её Адмирал может заявить, что эта модель попытается Передать Боеприпасы. Адмирал проводит Проверку Экипажа для этой модели. Если проверка проходит успешно, жетон статуса «Истощён» перемещается на эту модель. Если у этой модели есть как минимум X жетонов статуса «Истощён», она больше не может Передавать Боеприпасы. Во время Фазы Действия этой модели её подразделение может выполнить Специальное Действие. Участвовать могут только модели с характеристикой Запас (X). Каждая участвующая модель теряет один жетон статуса «Истощён», если он имеется. Это Специальное Действие можно выполнять несколько раз во время одной и той же Активации. *Примечание: Если моделей больше одной если может Передавать Боеприпасы, его Адмирал решает каждый случай отдельно, в порядке их выбора. Кроме того, если модель с токеном состояния Истощен находится в пределах 4” от более чем одной модели с этим Свойством в начале своей Активации, только одна модель может попытаться Передать Боеприпасы.*');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R132', 'ru', 'Stoic', '9b69758b5dec7604bf5612460ea392aa7f8f5f7f2b8c715f674007d8d4a5bc7c', 'Стоик', 'Всякий раз, когда этот персонаж повышает свой уровень Беспорядка с 0 до 1, он получает токен Стоика вместо этого, если у него его еще нет. Персонаж с токеном Стоика не испытывает никаких эффектов, связанных с наличием Беспорядка. Если он получает еще один уровень Беспорядка, токен Стоика удаляется и заменяется токеном 1 уровня Беспорядка. Любое правило, позволяющее персонажу потерять уровень Беспорядка, также позволяет удалить токен Стоика.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R245', 'ru', 'Storm Generator', 'd5103a1e010da2e6cde0e3ac745b14cb40578a0bda4b9a08ee858320c22882cd', 'Генератор шторма', 'Это Генератор и предоставляет следующую Пользу Юниту: Когда модель в этом юните становится Первичной Целью действия Атаки или Целью действия Штурма, противоположный Адмирал должен перебросить любые Тяжелые Удары в Броске Действия. Кроме того, в конце Активации этого юнита каждая вражеская модель в Близости хотя бы одной модели в юните с этой Системой получает 1 уровень Беспорядка.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R82', 'ru', 'Strategic Asset', '085f6345e920fe26f39ec8ee4b5f5c7df777e22a68d947c5bfe77ff7c28563b9', 'Стратегический актив', 'Если эта модель находится в Игровой зоне и готова к бою в конце игры, управляющий адмирал получает X очков победы.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R318', 'ru', 'STRATEGIC RESERVES', 'b251e6f8288bd2f99c8ef150faddeba19418f98634f60ea9a00ea7c8047e00b3', 'СТРАТЕГИЧЕСКИЕ РЕЗЕРВЫ', 'Всякий раз, когда этот адмирал делает бросок запаса для подразделения в своей силе, он может бросить одну дополнительную кость действия.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R367', 'ru', 'Strategic Vantage', 'a7d02c208375392b3156f61d6bd7d4d282cb0175cca8eb3e93ecce4aa6d2194f', 'Стратегическое преимущество', 'При определении инициативы в начале игры адмирал Флотской Эскадры может вытащить две карты "Победа и Доблесть" и выбрать карту с наибольшим значением. Кроме того, при определении инициативы на фазе готовности последующих раундов, если адмирал этой Флотской Эскадры решит сохранять самообладание, он может вытащить две бонусные карты вместо одной.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R137', 'ru', 'Structural Failure', '16da35ba9e8c73909dd72197639967c9d584cc58ba529517a1d9af985ada1db4', 'Структурный отказ', 'Если Начальная Цель этого действия Атаки получает хотя бы 1 Урон, активный Адмирал бросает X кубиков Критического Урона для каждого Вкладного оружия с этим Качеством. Если один или несколько кубиков показывают результат Структурной Поломки, Начальная Цель получает один Эффект Критического Урона этого типа. Это Качество Критического Урона. Если к Атаке применяются несколько разных Качеств Критического Урона, Адмирал делает отдельный бросок для каждого из них.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R161', 'ru', 'Structures', '5aeee0a1a91ae074f36348d9d5c3ca117c252753023ca01df54d2cccd782db69', 'Структуры', 'Структура — это искусственный элемент рельефа, такой как обслуживающая платформа или буровая установка. Все части игровой зоны в пределах 1 дюйма от Структуры считаются Опасной Водой. СТРЕЛЬБА ПО СТРУКТУРАМ Структура может быть выбрана в качестве цели действия Атаки, как если бы это была вражеская модель, и рассматривается как имеющая защиту 3, если адмиралы не решат иначе. Если Структура накапливает урон, равный её массе, она снимается с игры и заменяется на Маркер Обломков.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R292', 'ru', 'Stygian Depths', 'f5f5291157dbba1102040d6770ad508e03c4ce2072d156010ae23ec1046136b2', 'Стигийские глубины', 'Когда подводная модель перемещается, она может проходить сквозь модели, находящиеся не под водой, но сталкивается с особенностями местности как обычно. Ее адмирал может решать, проходит ли она сквозь или сталкивается с другими подводными моделями. Когда надводная модель перемещается, она проходит сквозь подводные модели. Во время действия Атаки видимость участвующих подводных моделей не может быть заблокирована или затемнена другими моделями. Аналогично, если подводная модель является целью действия Атаки, видимость участвующих моделей не может быть заблокирована или затемнена другими моделями. В обоих случаях особенности местности могут блокировать или затемнять видимость как обычно.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R193', 'ru', 'Submarauder', 'e035e0bc3f7e4476c68282bbc7aa59a4c8df36c938455e681fa9d575af0f2532', 'Подводный налётчик', '*Это свойство применяется только в том случае, если каждый модельный элемент в юните имеет его в своем профиле — в противном случае оно игнорируется.* Если у этого юнита есть жетон статуса «Всплытие» на этапе консолидации активации этого юнита, его Адмирал может выбрать выполнение проверки группы экипажа для юнита. Если проверка проходит, юнит немедленно теряет статус «Всплытие».');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R189', 'ru', 'Submerged', '1203ca01f440fd711efce8a0e54deac881ddb934bd652497e49311bbdf1b4992', 'Подводное оружие', 'Оружие с этим Специальным Качеством Атаки является Подводным оружием и может участвовать в действии Атаки только если все участвующие оружия также являются Подводным оружием. Подводная модель может быть выбрана в качестве Первичной цели этого действия. Воздушная модель не может быть выбрана в качестве Первичной цели этого действия. При определении, видима ли Первичная цель для модели, выполняющей эту атаку, все особенности местности рассматриваются как имеющие большую Массy, чем цель — даже особенности местности с Массой 0. Подводное подразделение может выполнять действие Атаки с Подводным оружием, даже если обычно оно не может выполнять действия Атаки.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R42', 'ru', 'Superior Mine Clearance', '0c59e81eaedf3c7216e66e829c4ac4b53a78d0c5c00f0283b61afeb5451d8ae3', 'Превосходная разминировка', 'После броска Костей Действия для Миссии по Очистке Мины, активный адмирал может преобразовать один Тяжелый Удар в Взрывной Удар за каждый жетон в Стеке с этим свойством SRS.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R291', 'ru', 'Superior Void Engine', 'd2801b181f638f81c88889bba8f43b90a0a0c91c5a5249e982564c737f0ff376', 'Превосходный Пустотный двигатель', 'Эта модель и другие дружественные модели Просвещённых в радиусе 10” от этой модели получают преимущества от Превосходных Пустотных Двигателей. Когда подразделение совершает Прыжок Турбо-Энкабуляции (см. раздел Экспериментальные Устройства в ОРБАТе Просвещённых), любые модели в подразделении, получающие преимущества от Превосходных Пустотных Двигателей, могут прыгнуть на расстояние до 20”, вместо до 15”.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R306', 'ru', 'Superior Weaponry', 'c2f283a1e2cf91e35528a2be21028cc7a3070af3569e0e14c03da1a838b0d8d6', 'Превосходное оружие', 'Один раз за Раунд, при объявлении Вкладных Оружий для действия Атаки, выполняемого подразделением Султаната в этой Силе, Адмирал этой Боевой Флотилии может объявить, что подразделение получит пользу от Превосходного Вооружения. На протяжении этого Действия все Вкладные оружия, обладающие качествами Пронзающий (X), Точный (X) или Структурный Сбой (X), увеличивают все свои значения Огневой Мощи на значение X данного Качества. Если оружие имеет несколько Качеств, используется только наибольшее значение X. Значения Огневой Мощи, указанные как ‘-’, не изменяются.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R48', 'ru', 'Supply Drop Mission', 'c9e1036a706e8abccf6d8d4e3fd7291e83ce920f5709ad622e44c5e39a84618c', 'Миссия по доставке припасов', '**РЕШАЕМ МИССИЮ ПО ДОСТАВКЕ ПОСТАВОК** Разместите стек SRS на дружественном юните в пределах 25” от модели, с которой он запускается. Сейчас он снабжает этот юнит. Стек SRS, снабжающий дружественный юнит, выполняет миссию по доставке поставок, используя следующий процесс. Активный Адмирал кидает количество кубиков действий, равное количеству фишек Talon Autogyro в стеке. За каждый выпавший Strike активный Адмирал может выбрать модель в юните. Эта модель может немедленно потерять 1 уровень Расстройства или снять жетон состояния «Истощён». Она может сделать это даже в том случае, если обычно не могла бы прийти в порядок (Rally). Модель не может быть выбрана более одного раза за миссию.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R196', 'ru', 'Surgical Strike', '1ba370630faa5cb4a47fa9b6b036a3f786b0294e8ad7766179288036a93c8b87', 'Хирургический удар', 'На этапе «Разрешение критического урона» в миссии «Атака на марш» при распределении кубиков критического урона между целями атаки каждый жетон в стопке с этим свойством SRS заставляет один кубик критического урона указанного типа нанести два воздействия этого эффекта.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R100', 'ru', 'Sympathetic Detonation', '357b4736c45a64de0cd841c39f5e5f204d16ff9d161b8db51ea95d9b22f86a24', 'Симпатический детонатор', 'Когда выполняется действие Атаки, в котором участвует одно или несколько оружий с этой Качеством, в начале шага Разрешения Взрывающихся Ударов активный Адмирал может сбросить один или несколько дружественных жетонов Скайт Файтер SRS, прикрепленных к юниту Начальной Цели. За каждый сброшенный жетон один Тяжелый Удар в броске действия превращается во Взрывающийся Удар.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R166', 'ru', 'Synergy', 'e45522a476f8a9a7ba3cb66ff720f350ad7dc7f9aa64be4ebd388b5aa834f00e', 'Синергия', 'Для каждого дополнительного оружия с этим качеством (свыше одного), которое участвует в этом действии Атаки, увеличьте рейтинг Огневой мощи каждого из этих оружий на 1. Рейтинги Огневой мощи, у которых нет значения, не увеличиваются.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R155', 'ru', 'System Failure', '5d2cc54050d9062a0532d2941610d2749a418fc5a158e6ef43603844552abe03', 'Сбой системы', 'Если Начальная Цель этого действия Атаки получает хотя бы 1 Урон, активный Адмирал бросает X кубиков Критического Урона для каждого Вкладного оружия с этим Качеством. Если один или несколько кубиков показывают результат Отказа Системы, Начальная Цель получает один Эффект Критического Урона этого типа. Это Качество Критического Урона. Если к Атаке применяются несколько разных Качеств Критического Урона, Адмирал делает отдельный бросок для каждого из них.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R227', 'ru', 'Tail Gunners', 'fb7cc7bb87fd44f295ff2709f15ad1787c5a5ed661b493eaea9951c17ec71694', 'Кормовые стрелки', 'Во время миссии «Атакующий рейд», если адмирал противника предпринимает попытку перехвата, адмирал этого жетона совершает проверку Сопротивления. Каждый жетон в атакующем стеке SRS с этим свойством добавляет X кубиков действий в пул Сопротивления.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R32', 'ru', 'Talon Assault Mission', '26b6d16973284388d67a44c11b9891410c9fa5d724f9cd89f495a449f21bb8bd', 'Миссия нападения Талон', 'Назначьте SRS Stack на вражескую наземную или воздушную единицу в пределах 25” от модели, с которой он запускается. Теперь он атакует эту единицу. Когда эта миссия будет выполнена, она имеет потенциал нанести высоко целевой критический урон моделям вражеской единицы. **ВЫПОЛНЕНИЕ МИССИИ TALON ASSAULT** SRS Stack, который атакует вражескую единицу, выполняет миссию Talon Assault, используя следующий процесс. 1. РЕШИТЕ ПОПЫТКУ ПЕРЕХВАТА Если вражеская единица поддерживается SRS Stack, противоположный Адмирал выполняет попытку перехвата так, как если бы это была миссия Attack Run. После её выполнения все SRS токены в вражеском Stack сразу же сбрасываются. 2. НАЗНАЧИТЬ ЦЕЛИ НА АТАКУ Активный адмирал назначает модели вражеского подразделения целями для атаки. Максимальное количество целей для атаки, которое он может назначить, равно количеству жетонов Talon Autogyro в его стопке. 3. СДЕЛАТЬ БРОСК ДЕЙСТВИЯ Активный адмирал делает один бросок действия независимо от числа целей для атаки, а противостоящий адмирал делает один бросок сопротивления. Шаг разрешения исходов броска действия пропускается. Пул действий Каждый жетон Talon Autogyro в стопке активного адмирала добавляет количество кубиков действий, равное его показателю атаки. Пул сопротивления Каждая цель для атаки добавляет количество кубиков, равное её показателю защиты. Добавьте 1 бонусный кубик за каждого эскорта, который сопровождающий целевой блок. 4. РЕШАЕМ НАПАДЕНИЯ Активный Адмирал выбирает Цель Нападения и убирает количество Ударов из пула действий, равное характеристике Экипажа модели. Если это невозможно, этот шаг заканчивается немедленно. Выбранная модель получает 1 Нарушение и получает Эффект Критического Повреждения, выбранный активным Адмиралом. Активный Адмирал повторяет этот шаг столько раз, сколько возможно, но каждая Цель Нападения может быть выбрана только один раз. 5. РАЗЪЕДИНИТЬСЯ Сбрасываются все жетоны Системы Реактивной Поддержки (SRS) в стопке активного Адмирала.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R238', 'ru', 'Temperamental', '5e28e1ef12568f1af0b38639f0aae528d860460deb14a19dea270c1569745740', 'Темпераментный', 'Когда для этой модели выполняется Бросок Ремонта, Сильные Удары не позволяют Адмиралу снять Эффекты Критического Повреждения. Кроме того, модель с этим свойством не может пытаться проводить Временный Ремонт.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R270', 'ru', 'Terminator Assault Mission', 'a4cffca26a1ac008ad6f1de5bf58f8edd56360cbc9941eed8ae78aa0d170b295', 'Миссия нападения Терминатора', 'Назначьте SRS-Стек на вражескую наземную или воздушную единицу в пределах 25” от модели, с которой он запускается. Он теперь осуществляет штурм этой единицы. Когда эта миссия будет выполнена, она имеет потенциал для нанесения очень прицельного критического урона моделям во вражеской единице. **ВЫПОЛНЕНИЕ МИССИИ ШТУРМА ТЕРМИНАТОРА** SRS-Стек, который штурмует вражескую единицу, выполняет миссию штурма Терминатора, используя следующий процесс. 1. РЕШАЮЩИЙ ПЫТАНИЕ ПЕРЕХВАТА Если вражеская единица поддерживается SRS-Стеком, противоположный Адмирал делает попытку перехвата так, как будто это миссия Боевого Прыжка. После того как это будет выполнено, все SRS токены во вражеском Стеке немедленно сбрасываются. 2. НАЗНАЧЕНИЕ ЦЕЛЕЙ ДЛЯ ШТУРМА Активный адмирал назначает модели в вражеском подразделении в качестве целей для штурма. Максимальное количество целей для штурма, которое он может назначить, равно числу жетонов Talon Rotor в его стопке. 3. СДЕЛАТЬ БРОСОК ДЕЙСТВИЯ Активный адмирал выполняет один бросок действия независимо от количества целей для штурма, а противоположный адмирал выполняет один бросок сопротивления. Шаг разрешения исходов броска действия пропускается. Пул действий Каждый жетон Talon Rotor в стопке активного адмирала добавляет количество кубиков действия, равное его рейтингу атаки. Пул сопротивления Каждая цель для штурма добавляет количество кубиков, равное её рейтингу защиты. Добавьте 1 бонусный кубик за каждое эскортное судно, которое сопровождающий целевое подразделение. 4. РЕШАЕМ НАПАДЕНИЯ Активный Адмирал выбирает Цель Нападения и убирает из Пула Действий количество Попаданий, равное рейтингу Экипажа модели. Если это невозможно, этот шаг немедленно завершается. В противном случае активный Адмирал бросает два кубика Критического Повреждения и выбирает один для нанесения целевой модели. Если результаты одинаковы, целевая модель также получает 1 Повреждение. Активный Адмирал повторяет этот шаг столько раз, сколько возможно, но каждая Цель Нападения может быть выбрана только один раз. 5. ОТСТУПЛЕНИЕ Сбрасываются все жетоны SRS в стеке активного Адмирала.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R251', 'ru', 'Terrifying', 'baff7f25e1bf004baf6045ec82ecd4c65ae36c722a938a9acd243f304e795446', 'Ужасный', 'Как только подразделение этой модели завершает свой Шаг Передвижения, любые модели (своих или чужих) в пределах 5 дюймов мгновенно получают 1 уровень Расстройства. Модели с указанным Признаком не подвержены этому свойству.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R159', 'ru', 'Territory', '1df4c59957b3d40231f71397fbfa90b6583d155044cfe4c505eec4780c470384', 'Территория', 'ТЕРРИТОРИИ Большой остров (по крайней мере 6 дюймов в ширину) называется Территорией. Территории подчиняются всем правилам для островов, но другие правила могут взаимодействовать с ними особым образом.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R363', 'ru', 'Terrors from Above', '2135c30fa10c542fa3d8404a5a4bdbf19340a908fa3890ed7dd2bc7911c3c3ed', 'Ужасы с небес', 'В начале своего хода Адмирал этого Боевого Флота может выбрать подразделение Воздушно-десантных войск Содружества в своей Силе со статусом «Входящее» и выполнить Особый Эффект Доблести. В случае успеха подразделение теряет статус «Входящее» и мгновенно активируется, даже если в этой Силе есть подразделения, у которых нет статуса «Входящее» и которые ещё не активировались в этом Раунде. В случае неудачи Особого Эффекта Доблести подразделение не активируется, и вместо него Адмирал этого Боевого Флота активирует другое подразделение в своей Силе.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R348', 'ru', 'TESTUDO VIRIDIS', 'ed7bbfc25f73096a781170c7c19d3dabccc6562969748f36af93e7ac3a505a3a', 'ЗЕЛЁНАЯ ЧЕРЕПАХА', 'Эта Доктрина может быть приобретена только для итальянского флагманского подразделения. Во время Фазы Активации вместо выполнения миссии SRS Адмирал этой Силы может выбрать маркер минного поля в пределах 10” от модели итальянского подразделения и объявить Дистанционный Взрыв. Все модели вблизи маркера минного поля (не только ближайшие) подвергаются последствиям Взрыва Минного Поля. После того как это будет выполнено, маркер минного поля немедленно удаляется. Дистанционный Взрыв может быть объявлен даже если на Игровой Площадке нет дружественных стеков SRS.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R232', 'ru', 'Teutonic Construct', 'bcfcb99699525efa9624202ad831321da62dfa7a6a0725e395469c639cbc4c76', 'Тевтонская конструкция', 'Когда для этой модели выполняется бросок на ремонт, «Сильные Удары» не позволяют Адмиралу устранять эффекты критических повреждений. Однако, если эта модель готова к бою в момент выполнения броска на ремонт, любое количество «Взрывающихся Ударов» можно использовать для выполнения структурного ремонта вместо использования для устранения эффектов критических повреждений. За каждый кубик, использованный для структурного ремонта, снимите 1 очко повреждения с этой модели. Модель с этим свойством не может пытаться выполнять временный ремонт и не может пользоваться системой ремонтных средств (X).');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R40', 'ru', 'The Localised Anomaly Pool', 'efc89906de6b03298b32c8a39a673f845c5def3f995d6d43ab7ccd3ddd995a2f', 'Локализованный пул аномалий', 'Просвещённый Адмирал имеет пул Кубиков Действий, называемый Локализованный Аномальный Пул. В начале игры в пуле нет кубиков, но некоторые правила будут указывать Адмиралу добавлять их туда. Кубики Действий, добавленные в Локализованный Аномальный Пул, остаются в нём до тех пор, пока правило специально не укажет их удалить. Если правило указывает Адмиралу сделать Бросок Аномалии, он бросает все кубики из Локализованного Аномального Пула, разрешает результат в соответствии с инструкциями, а затем возвращает кубики в пул. В дополнение к Прыжкам Турбо-Энкабулации (см. ниже), следующие Системы (согласно Глоссарию Дистопических Войн) взаимодействуют с Локализованным Аномальным Пулом:* Крони-Латунь Каллимаха, Хроно Генератор, Диофантов Хаос-Орб, Блок Локализованной Стабилизации Аномалий, Генератор Нулевых Клонов, Узел Рекомбинации.* **Турбо-Инкапсуляционные Прыжки** Некоторые правила (например, система Турбо-Инкапсуляционного Привода) позволяют юниту пытаться выполнить Турбо-Инкапсуляционный Прыжок как Специальное Действие. Только модели с системой TED (Турбо-Инкапсуляционного Привода) могут участвовать. Сначала Адмирал добавляет 2 Кости Действия в Пул Локализованных Аномалий, затем делает Бросок Аномалии для юнита. За каждый Пустой результат каждая участвующая модель получает 1 уровень Беспорядка. Если это приведет к тому, что какая-либо модель получит четвертый уровень Беспорядка, разрешается Провальный Прыжок. В противном случае разрешается Успешный Прыжок. **Разрешение Провального Прыжка** Когда турбо-энкабуляционный прыжок проваливается, вся активная единица (включая любые модели, которые не участвовали) удаляется с игровой зоны и помещается в резерв. Единица может попытаться вернуться в игровую зону с помощью броска резерва в последующих раундах. Если единица всё ещё находится в резерве в конце игры, все оставшиеся модели считаются покинутыми. **Разрешение успешного прыжка** Когда турбо-энкабуляционный прыжок не проваливается, адмирал перемещает каждую участвующую модель по одной, убирая её из игры, а затем возвращая в игровую зону, не дальше чем на 15” от её первоначального положения. Модели могут быть размещены в любом направлении, но не могут находиться вблизи вражеской модели, и единица должна находиться в согласованности, как только все модели будут расставлены. После выполнения Турбоуправляемого Прыжка единица не может выполнять больше никаких действий в этом шаге действий и не учитывается как имеющая неиспользованные действия для целей сборки войск на шаге консолидации. *Когда единица выполняет Прыжок с Инкапсуляцией (независимо от того, неудачный он или успешный), любые жетоны SRS, назначенные единице, остаются на месте, как если бы она отступила (см. Отсутствующие цели на странице 109 правил Dystopian Wars: The Rules). Любые другие жетоны (Эскорт, Конструкт Физетера, Повреждение, Расстройство, Критическое повреждение и т.д.) перемещаются с моделью(ями) как обычно. Это может привести к тому, что модели в резерве будут иметь жетоны, хотя обычно это не происходит. возможный.*');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R20', 'ru', 'The Respect Of Meritocratic Rank', 'e0624e711db3463b77e2558e6903180d440eaa1e23a0741fe4cef8c4557d6ff0', 'Уважение меритократического ранга', 'Один раз за раунд, во время шага переброски Решимости при выполнении действия этим Адмиралом для юнита в его силе, он может активировать Специальный Эффект Доблести с этим юнитом. Юнит должен быть либо Флагманом, либо находиться в пределах 10” от дружественного Флагмана. Если Эффект успешно активирован, Адмирал может перебросить любое количество кубиков в пуле.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R310', 'ru', 'THE SULTAN’S HAMMER', '42008f1de3c1f938bb5ab4184535849bff3046dde8aaeb3aabf9208bf5665c62', 'МОЛОТ СУЛТАНА', 'Может быть приобретено только для флагманского юнита Султаната. Один раз за Раунд этот Адмирал может сбросить карту «Победа и Доблесть» из своей руки, когда объявляет атаку с флагманским юнитом. База действий для этого действия получает количество бонусных кубиков, равное значению сброшенной карты.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R8', 'ru', 'The Things Science Cannot Predict', 'c344d9b18c946dbd38c462d5e59f1d653b4c564a975e4b7a70c60b65a84ec9e8', 'Вещи, которые наука не может предсказать', 'Один раз за игру, когда противостоящий адмирал пытается осуществить Эффект Доблести, этот адмирал может использовать эту Доктрину вместо попытки Отменить эффект. Противостоящий адмирал показывает свою Карту Доблести. Если её Значение равно 8 или меньше, она сбрасывается без исполнения.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R304', 'ru', 'THE THIRTEENTH', 'aaacf7c6679a24fa07b2eea72702464d988d5ac02e5f4a0afe9ed8964fa61344', 'ТРИНАДЦАТЫЙ', 'Эта Доктрина может быть приобретена только для египетского флагманского юнита. Один раз за игру, на этапе Уборки в фазе Конца, Адмирал этой Силы может сбросить карту Победы и Доблести из своей руки. Если он это делает, он может немедленно снять все уровни Беспорядка со всех египетских моделей в Игровой зоне.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R316', 'ru', 'Their Will Made Manifest', '63d8de2abde489b412d65368da4e4f3d6fc514864396dafe134c2fa7e1f52851', 'Их воля проявилась', 'Боевые драконоподобные модели в этой Силе являются Засчитываемыми моделями.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R4', 'ru', 'To Keep The Science Secret…', '8092565d8941a8133377e6493d1e5d33a763a7f6befa0b5fbff03d52cda9a8fc', 'Чтобы сохранить науку в тайне…', 'Если модель из этой Силы добровольно Отступает на этапе Активизации, её Адмирал может выбрать Разрешить Катастрофический Взрыв с моделью перед её выводом из игры.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R300', 'ru', 'TO THE SULTAN I COMMEND MYSELF', 'da70e00ae398cc9bd09aaa0fd08e4378cd8d94e07eeda96c0e601c568b618d4d', 'СУЛТАНУ Я ВВЕРЯЮ СЕБЯ', 'Один раз за ход, перед тем как этот адмирал выполняет проверку экипажа для модели, он может использовать эту доктрину, чтобы предоставить этой модели модификатор +2 к рейтингу экипажа только для этой проверки. В случае групповой проверки экипажа этот модификатор применяется ко всем моделям в подразделении.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R188', 'ru', 'Torpedo', '287b09df89e8bbffb37bfd5a625c651df6443faf0cd7eeff41227bd72a836d96', 'Торпеда', 'Это оружие не может способствовать действию Атаки, если исходная цель находится в пределах 5” от этой модели.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R152', 'ru', 'Torrent', '24ac64acfdfef38c4c95b248454ed6266778471cb3222c3f64c96a77f51c9adc', 'Шквал', 'Оружие с этим Качеством Специальной Атаки является Потоковым оружием и может участвовать в действии Атаки только в том случае, если все участвующие оружия также являются Потоковыми. *См. Потоковое оружие на странице 92 Руководства по правилам Dystopian Wars.* Подводная модель не может быть выбрана в качестве Первичной Цели этого Действия. Если в качестве Первичной Цели выбрана воздушная модель, участвовать могут только воздушные модели. На этапе Броска Действия для Первичной Цели её показатель Обороны равен 0, и Бросок Сопротивления не может получать дополнительные кубики от Эскорта или Воздушной Поддержки SRS. После завершения этапа Нанесения Урона этого Действия, активный Адмирал может полностью повторно выполнить это Действие. Они можно выбрать либо ту же самую начальную цель, либо другую модель, которая имеет тот же позицционный признак, что и предыдущая начальная цель, и находится в пределах 4” от неё. (Если предыдущая начальная цель была уничтожена, новую начальную цель следует выбрать до того, как она будет убрана с поля боя.) Обычные правила выбора цели, назначения участвующих моделей и объявления участвующих оружий по-прежнему применяются. В целом, действие Атаки может быть выполнено до X раз. Если к действию участвуют оружия с разными значениями Потока (X), используется наименьшее значение X среди них. Эта последовательность повторяющихся действий Атаки называется Потоком и учитывается как одно действие для целей единицы. Лимит действий. Оружие может способствовать нескольким действиям в рамках одного Потока. Модель не может получить более 1 Расстройства из-за правила Под огнем от одного Потока, даже если она выбрана в качестве Начальной цели более одного раза.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R53', 'ru', 'Tracer', '38ee98292eaf56b1b502c325865819c116a8508abc4007f217a18dc6861d7e12', 'Трассирующий', 'После разрешения действия Атаки, в котором одно или несколько оружий с этим Качеством участвуют, Изначальная Цель помечается. Отслеживайте это, размещая жетон Негативного Эффекта на Изначальной Цели. Когда любое подразделение выполняет действие Атаки, нацеленное на Помеченную модель, активный Адмирал перебрасывает все Пропуски в Броске Действия. Уберите жетон Негативного Эффекта на этапе Очистки в Конечной Фазе.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R91', 'ru', 'Traction', '00e45155c08a069a9d3fe530cf23ea33555cca0285b2d3586cf6ffc17ceb775e', 'Тяга', 'Если действие Атаки с использованием этого оружия приносит количество Успехов, равное или превышающее значение Массы Первоначальной Цели, активный Адмирал может выбрать одно Содействующее оружие с этим Качеством. Первоначальная Цель немедленно перемещается на 4” прямо к модели, на которой установлено это оружие, без изменения своего направления. Любые Столкновения, возникшие в результате этого перемещения, разрешаются как обычно.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R94', 'ru', 'Treacherous Water', '3ec4f0286b28d31baff6fdb73f792d8e659c0b985630942105d4c775fb2f8045', 'Вероломная вода', 'ЭКОЛОГИЧЕСКИЕ ОБЪЕКТЫ При расстановке части поверхности Игровой зоны могут быть определены как Экологические объекты. Они должны занимать явно выделенный участок Игровой зоны и должны быть определены как ЛОЖНАЯ ВОДА (представляющая сильные течения, плавающий мусор или скрытые опасности) или ТУМАН (который может быть туманом, низко лежащими облаками или густым дымом). Экологические объекты не являются Рельефными объектами, поэтому модели не могут сталкиваться с ними, и они не затрудняют видимость, если не указано иное. См. Раздел «Затрудненное движение» для получения дополнительных правил, касающихся Ложной воды.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R148', 'ru', 'Triangulate', '0f2cfb3cd3fb96522b7d2781558fb4a80cfe150ca96a28b45c57514a397474b2', 'Триангулировать', 'Если первоначальная цель этого действия атаки находится в пределах 15” от дружественной модели с системой гидрофонного ретранслятора, увеличьте каждое значение огневой мощи этого оружия на X. Значения огневой мощи, которые не имеют значения, не увеличиваются.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R81', 'ru', 'Trident Generator', '6f05595bb77ee35ab916b5550f0fbeeac86cb1c58e1a957e2e2bc2aadfed2a31', 'Генератор Трайдент', 'Это Генератор. Блок этой модели может Отметить Цель как Специальное Действие, даже если она находится Под водой. Только модели с Генератором Трезубца могут Участвовать в этом Действии. Выполняя это Действие, каждая участвующая модель может Отметить одну вражескую модель на Поверхности или Под водой в пределах 20”. Отметьте каждую Отмеченную модель жетоном Эффекта Генератора. Всякий раз, когда Отмеченная модель становится Целью для атаки с использованием Подводного Оружия, все Стандартные Счётчики в Броске Действия превращаются в Стандартные Удары на этапе Подсчёта Попаданий.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R215', 'ru', 'Turbo Encabulation', '6d747208c097b7639bdfc7602bf7f9701319e46a14f7835c50a2a92186dfd02d', 'Турбо энкабулация', 'Прыжки Турбо Энкабуляции Некоторые правила позволяют Адмиралу попытаться совершить Прыжок Турбо Энкабуляции с подразделением. Сначала Адмирал перемещает каждую модель в подразделении по одной, убирая её из игры, а затем возвращая на Игровую Площадку на расстояние не более 15 дюймов от предыдущего положения. Модели могут быть размещены в любом направлении, но не могут находиться вблизи модели противника, и подразделение должно находиться в Целостности после того, как все модели будут размещены. После этого каждая модель в подразделении получает 1 уровень Беспорядка. Затем Адмирал добавляет Кость Действия в Пул Локализованных Аномалий и выполняет Бросок Аномалии, бросая все кости из Пула. Если ни одна кость не выпала Пустой, прыжок проходит идеально выполнено. Если один или два кубика показывают Пустое значение, каждая модель в отряде получает как Сбой Системы, так и Критический Эффект Опасности. Если три или более кубиков показывают Пустое значение, Активация отряда заканчивается немедленно; он удаляется с игровой зоны и помещается в Резерв, сохраняя любые жетоны (Повреждение, Расстройство, Критическое Повреждение и т. д.). Если отряд всё ещё находится в Резерве в конце игры, все оставшиеся модели считаются Брошенными. ПРЕДЕЛЫ ЭНКАБУЛЯЦИИ Модель, имеющая Критический Эффект Повреждения Системы и/или 3 уровня Расстройства, не может принимать участие в попытке Прыжка Турбо-Энкабулации. Если её отряд пытается Прыжок Турбо-Энкабулации, модель удаляется из игры как обычно, но не возвращается в Игровую Зону. Если оно было Боеготово, противостоящий Адмирал немедленно получает Очки Победы, как если бы оно было Выведено из строя.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R65', 'ru', 'Turbo Encabulation Drive', '7e7f01ffa5be06dd3745390a30d821d3b944b0c85b5ece8915ad5ccfe7f02537', 'Турбоэнкапсуляционный привод', 'В качестве специального действия юнит этой модели может совершить прыжок Турбо Энкабулации, как подробно описано в разделе ''Экспериментальные приспособления'' Просвещённого ОРБАТа. Только модели с этой системой могут участвовать в действии.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R158', 'ru', 'Ubiquitous', '6774a5227bcdad2ed57ad91f9b57388d22edaa916078d8a2657e23d44daa589f', 'Вездесущий', 'Во время Выбора Сил, Боевой Флот может содержать до двух единиц этого Класса, или три, если это Класс Опоры. Это отменяет ограничение на Дублирующиеся Классы (см. страницу 126 правил Dystopian Wars).');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R195', 'ru', 'Unconventional Target', '62d24c299df064c886a389d5278986bf4c41a0b7ad07006c7e3ed4efd7df44a7', 'Нетрадиционная цель', 'Когда модель Воздушного юнита становится целью действия Атаки, любые Обычные Удары и Тяжёлые Удары в Ролле Сопротивления преобразуются в Обычные Контратаки. Это происходит даже если юнит, выполняющий Атаку, также является Воздушным.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R271', 'ru', 'Under Fire', '004b9f99dd8b330eebfff6103f88541cbdaa08d012413f3a208b2e719863cc17', 'Под обстрелом', 'Если цель получает количество Урона, равное или превышающее её показатель Массы в результате одной атаки, то она также получает 1 уровень Расстройства.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R255', 'ru', 'Underwater', 'b0c4cc6adf3fefddb4e403f135969e65a379b3a5846c0482abe82509c4fbc06f', 'Под водой', 'Подводные модели следуют этим дополнительным правилам: Погружение и всплытие, Сдувание баллонов, Стигийские глубины, Герметичные сосуды, Бесшумные охотники');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R55', 'ru', 'Underwater Carrier', '6cd6c0d495d34916f2bf4c4355446595838a9ebe70b586fad4566b72acfb2aeb', 'Подводный авианосец', 'На фазе запуска эта единица модели может выполнить запуск SRS. Когда это происходит, эта модель запускает до X токенов SRS, как описано в разделе «Запуск короткодействующих эскадронов» на странице 108 книги Dystopian Wars: The Rules. Значение X этого свойства уменьшается на 1 за каждый уровень Беспорядка на модели. Тип(ы) токенов SRS, которые эта модель может запускать, определяется другими свойствами в профиле единицы, чаще всего свойством SRS (Type). Если модель может запускать более чем один тип токенов SRS, они могут быть запущены в любой комбинации, при условии, что общее количество запущенных токенов не превышает X. В отличие от моделей со свойством Carrier, если подводная модель имеет эту характеристику, она может запустить SRS без предварительной активации.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R29', 'ru', 'Underwater SRS', '15fab21a2b66a2cd0db73f6a59eb3311ce55387649b04bd6a27b486613a46990', 'Подводный SRS', 'Если этот жетон SRS выделен для воздушного подразделения, наземного подразделения с свойствами Возвышение или Планирование, подразделения с свойством Спуск, которое всплывает, или подразделения с амфибийным свойством, которое пересекает участок местности, его показатели Атаки, Перехвата и Поддержки снижаются до 0. Жетон с этим свойством SRS не может быть удален в результате Зенитной Бомбардировки (см. систему Зенитная Бомбардировка (X)). На этапе Очистки в Финальной фазе, жетоны с этим свойством SRS удаляются из игры без выполнения Воздушной Разведки.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R198', 'ru', 'Unexpected Arrival', '83c52bc71cf4f492b505d1cfa48e568730cc1f8d8c020253c68c6e8b8feee553', 'Непредвиденное прибытие', '*Это свойство применяется только в том случае, если оно указано в профиле каждого миниатюры в юните — в противном случае оно игнорируется.* Перед тем как делать бросок на резерв, его адмирал может объявить, что юнит совершит Неожиданный Прибытие. Ему не нужно делать бросок на резерв; юнит появляется автоматически. Адмирал может разместить его в любой точке игровой зоны при условии, что никакие миниатюры не находятся рядом с другими миниатюрами или элементами местности. Юнит не получает жетон статуса "Прибывает", но когда он будет активирован позже в раунде, его максимальная скорость будет уменьшена вдвое (с округлением вверх), а Ограничение Действий получит модификатор -1, минимум до 1.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R75', 'ru', 'Valorous', '1c61201ddb3342840de4551d4dbe0ab9aa6d88fe6d31872948f5fdc2c067e849', 'Доблестный', 'Когда выбирается юнит, содержащий модель с этим свойством, чтобы выполнить Эффект Доблести, вы можете объявить, что эта модель Доблестна. Считайте значение их Карты равным Рейтингу Экипажа этой Модели, учитывая любые модификаторы. После того как Эффект Доблести разрешён (даже если он был Отвергнут), каждая модель в юните получает 1 уровень Беспорядка.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R200', 'ru', 'Vanguard', '88c5b12ef008737a4c0ad4b3ddc319751b6313b5777d4bba54d4c67947e8711d', 'Авангард', '*Это свойство применяется только в том случае, если у каждой модели в отряде оно указано в её профиле отряда — в противном случае оно игнорируется.* Этот отряд может выполнить Специальное Действие Развертывания, чтобы совершить Передвижение Авангарда. Когда он это делает, каждая модель в отряде совершает передвижение так, как если бы это был Шаг Передвижения её Активации. Во время этого передвижения каждая модель имеет Минимальную Скорость 0” и Максимальную Скорость X”. Если этот отряд развернут в Резерв, его Адмирал добавляет 2 дополнительных кубика к любым броскам Резерва, которые он выполняет для него.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R77', 'ru', 'Very Large', '120363938bf17ca8b0021e99a2d32cb2df44d8445656c7d353f2e7a242d005df', 'Очень большой', 'Когда эта модель развернута, ей не требуется полностью находиться в зоне развертывания её адмирала, пока её центральная точка находится в зоне развертывания. Модель с этим свойством не получает расстройства от столкновений или действий тарана и никогда не ограничена в возможности проводить сборы из-за близости. Когда эта модель становится целью действия «Бортовой залп», противник-адмирал добавляет две бонусные кости к броску бортового залпа. Если эта модель уничтожена, замените её четырьмя маркерами обломков. Первый размещается над центральной точкой модели. Затем адмирал этой модели размещает оставшиеся три маркера так, чтобы каждый находился в пределах 1 дюйма от первого, и при этом ни один не соприкасался с другими маркерами, моделями или местностью. Особенности. Любые маркеры, которые нельзя разместить в соответствии с этими правилами, не размещаются.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R352', 'ru', 'Veteran Cadre', '2e4d6ee178d4ee51f9bf853385973e85f36b1b53b58ac1e6012b416cb4f60e15', 'Ветеранский кадровый состав', 'Когда Адмирал этого Боевого флота активирует юнит SUSA, он может немедленно применить Специальный эффект доблести. В случае успеха каждая модель в юните получает свойство Штурмовые команды (X) на время этой Активации, при этом значение X равно удвоенной Массе модели. Дополнительно, если юнит получает хотя бы один Успех во время штурмовой действия в этой Активации, его Адмирал получает 3 Очка Победы.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R295', 'ru', 'Vikingr', 'e12f61f64ac9e833b3e55ea5ddd43fed7869ad34065c5a8be70cd8de0e4b37b8', 'Викинг', 'Когда эта модель участвует в абордажном действии, Цель получает X отрицательных эффектов. Это токены Викингр и они указывают, что цель подвергается атаке. В следующей активации модели-цели её отряд может совершить особое действие, чтобы отразить абордаж. Участвовать могут только модели, находящиеся под атакой, но модель может участвовать в этом действии несколько раз в рамках одной активации. За каждую участвующую модель активный адмирал бросает количество кубиков действий, равное показателю команды модели. За каждый удар он убирает один токен Викингр с модели. В конце активации модели она получает 1 урон за каждый оставшийся токен Викингр. Затем все её токены Викингр... удаляются, и больше не находятся под атакой. Если несколько моделей с этим свойством участвуют в абордажном действии, цель получает количество жетонов Vikingr, равное сумме их значений X.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R90', 'ru', 'Visibility', 'eedc53697154a286d098ad7e9212d86f2d95f8cf0170c522266366ed7ff4e074', 'Видимость', 'Во время действия Атаки видимость Участвующей модели затрудняется, если невозможно провести линию от центральной точки модели до каждой части Цели, не пройдя хотя бы через один участок Тумана. Это применимо даже если Участвующая модель или Цель находятся в воздухе. Противоположный Адмирал добавляет 2 бонусных кубика к броску Сопротивления за каждую Участвующую модель, у которой затруднена видимость.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R234', 'ru', 'Vitruvian Form', '55b0582f0e19218777ac662df132fd71a08f9d41191be9f2da3efb0e8f59ef75', 'Витрувианская форма', 'В начале своего хода перемещения эта модель может сделать бесплатный разворот перед движением. Кроме того, эта модель всегда должна разворачиваться при развороте кормой, но такие развороты стоят 1" перемещения вместо 2". Эта модель не может объявлять таран.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R130', 'ru', 'Voltaic', 'f4f2b5e700d6b22c9c6f1cefeb120d6e19cd8aebb46de544423d2fa0bc5bfbc2', 'Вольтаический', 'Каждое значение Огневой Мощи этого оружия увеличивается на X за каждый Эффект Критического Повреждения Системного Сбоя у цели. Значения Огневой Мощи, которые не имеют значения, не увеличиваются.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R274', 'ru', 'Wavelurker', '812a86c903e5bbf0b48beb37dc004f14e4776ca036b51a93d23804841a9d1f23', 'Вейвлёркер', 'Эта модель может проходить через другие модели поверхностей во время своего шага движения и не блокирует и не заслоняет видимость, когда дружеская единица совершает действие Атаки. Кроме того, когда эта модель является целью действия Атаки, перед совершением броска Сопротивления адмирал этой модели может провести Проверку Экипажа для неё. Если проверка успешна, все Стандартные Удары в броске Сопротивления превращаются в Стандартные Ответные Удары. Это не применяется, если действие Атаки совершается с использованием Штурмового или Погруженного оружия. Если у этой модели есть Эффект Критического Повреждения Блокировки Навигации, это свойство не действует.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R26', 'ru', 'Wide Open Skies', 'b6a762acce5070235cc9719ae4bbdd0d603bd02e50e5a05b31426ab65bad745e', 'Широкие открытые небеса', 'Модель воздушного транспорта рассматривает все элементы местности как открытые воды и может проходить сквозь модели, не являющиеся воздушными. Её адмирал может решать, проходит ли она сквозь или сталкивается с другими воздушными моделями. Аналогично, когда модель, не являющаяся воздушной, перемещается, она проходит сквозь воздушные модели. Видимость к воздушной модели или от неё никогда не блокируется и не затрудняется другими моделями или элементами местности, если правило специально не указывает иное. Кроме того, воздушные модели никогда не блокируют и не затрудняют видимость другой модели.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R366', 'ru', 'WOLVES OF THE SEA', 'a21380d1cfa13f6f0c2b264b0e8e1206f5005d5aa8fa66b830d95d6735992798', 'МОРСКИЕ ВОЛКИ', 'Эта Доктрина может быть приобретена только для флагманского скандинавского юнита. Поврежденные скандинавские модели в Силе этого Бойевого Флота всегда могут участвовать в действии, даже если их адмирал не проходит необходимую проверку экипажа группы. Обратите внимание, что проверка все равно должна проводиться, поэтому даже если единственные поврежденные модели в юните — скандинавские, карта из Колоды Победы и Доблести все равно должна быть открыта и сброшена.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R357', 'ru', 'Wolves upon the Fold', 'a1ed0171c03188c4a9511ce270acb9c33011e4dc43729a9f20fa27374e46c9d0', 'Волки на пастбище', 'Когда дружественная единица Black Wolf совершает действие Атаки или Десантное действие, и цель имеет как минимум 2 уровня Беспорядка, Адмирал может перебросить любые пустые результаты в броске действия.');
INSERT INTO rule_translations (rule_id, language, source_title, source_hash, title, text) VALUES ('R360', 'ru', 'Zaporozhian Spirit', 'f4f357ecf6b6f3f04dfb46cd08dba1fe0a7a172eab1f8da75ec10ed74c730112', 'Запорожский дух', 'Когда подразделение украинских подводных сил в этом соединении совершает атаку, в которой участвует одно или несколько подводных орудий, его адмирал может сбросить карту «Победа и Доблесть» до того, как будут брошены любые кости. Если он это сделает, бросок действия не подвержен влиянию безпорядка.');
